const c="117",n=117,t="https://zh.wikisource.org/zh-hant/史記三家註/卷117",e="https://zh.wikisource.org/zh-hant/史記/卷117",o=JSON.parse('[{"id":"a1","section":"司馬相如列傳第五十七","anchor":"司馬相如者，蜀郡成都人也，字長卿。少時好讀書，學擊劍，","notes":[{"source":"索隱","text":"《呂氏春秋》劍伎云「持短入長，倏忽縱橫之術也」。魏文《典論》云「余好擊劍，善以短乘長」是也。"}]},{"id":"a2","section":"司馬相如列傳第五十七","anchor":"相如者，蜀郡成都人也，字長卿。少時好讀書，學擊劍，故其親名之曰犬子。","notes":[{"source":"索隱","text":"孟康云：「愛而字之也。」"}]},{"id":"a3","section":"司馬相如列傳第五十七","anchor":"郡成都人也，字長卿。少時好讀書，學擊劍，故其親名之曰犬子。相如既學，","notes":[{"source":"索隱","text":"案：秦密云「文翁遣相如受七經」。"}]},{"id":"a4","section":"司馬相如列傳第五十七","anchor":"相如既學，慕藺相如之爲人，更名相如。以貲爲郎，事孝景帝，爲武騎常侍，","notes":[{"source":"索隱","text":"張揖曰：「秩六百石，常侍從格猛獸。」"}]},{"id":"a5","section":"司馬相如列傳第五十七","anchor":"帝不好辭賦，是時梁孝王來朝，從游說之士齊人鄒陽、淮陰枚乘、吳莊忌夫子","notes":[{"source":"集解","text":"徐廣曰：「名忌，字夫子。」"},{"source":"索隱","text":"徐廣、郭璞皆云名忌字夫子。案：鄒陽傳云枚先生、嚴夫子，此則夫子是美稱，時人以爲號。《漢書》作「嚴忌」者，案忌本性莊，避明帝諱改姓嚴也。"}]},{"id":"a6","section":"司馬相如列傳第五十七","anchor":"令王吉相善，吉曰：「長卿久宦遊不遂，而來過我。」於是相如往，舍都亭。","notes":[{"source":"索隱","text":"案：臨邛郭下之亭也。"}]},{"id":"a7","section":"司馬相如列傳第五十七","anchor":"，臨邛令前奏琴曰：「竊聞長卿好之，願以自娛。」相如辭謝，爲鼓一再行。","notes":[{"source":"索隱","text":"案：樂府長歌行、短歌行，行者曲也。此言「鼓一再行」，謂一兩曲。"}]},{"id":"a8","section":"司馬相如列傳第五十七","anchor":"再行。是時卓王孫有女文君新寡，好音，故相如繆與令相重，而以琴心挑之。","notes":[{"source":"集解","text":"郭璞曰：「以琴中音挑動之。」"},{"source":"索隱","text":"張揖云：「挑，嬈也。以琴中嬈之。」挑音徒了反。嬈音奴了反。其詩曰「鳳兮鳳兮歸故鄉，遊遨四海求其皇，有一豔女在此堂，室邇人遐毒我腸，何由交接爲鴛鴦」也。又曰「鳳兮鳳兮從皇栖，得託子尾永爲妃。交情通體必和諧，中夜相從別有誰」。"}]},{"id":"a9","section":"司馬相如列傳第五十七","anchor":"，故相如繆與令相重，而以琴心挑之。相如之臨邛，從車騎，雍容閒雅甚都；","notes":[{"source":"集解","text":"韋昭曰：「閒，讀曰「閑』，甚得都邑之容也。」郭璞曰：「都猶姣也。詩曰『恂美且都』。」"}]},{"id":"a10","section":"司馬相如列傳第五十七","anchor":"之，恐不得當也。既罷，相如乃使人重賜文君侍者通殷勤。文君夜亡奔相如，","notes":[{"source":"索隱","text":"郭璞云：「婚不以禮爲亡也。」"}]},{"id":"a11","section":"司馬相如列傳第五十七","anchor":"重賜文君侍者通殷勤。文君夜亡奔相如，相如乃與馳歸成都。家居徒四壁立。","notes":[{"source":"集解","text":"郭璞曰：「言貧窮也。」"},{"source":"索隱","text":"案：孔文祥云「徒，空也。家空無資儲，但有四壁而已，云就此中以安立也」。"}]},{"id":"a12","section":"司馬相如列傳第五十七","anchor":"錢也。」人或謂王孫，王孫終不聽。文君久之不樂，曰：「長卿第俱如臨邛，","notes":[{"source":"索隱","text":"弟如臨邛。文穎云：「弟，且也。」郭璞云：「弟，語辭。如，往也。」"}]},{"id":"a13","section":"司馬相如列傳第五十七","anchor":"自苦如此！」相如與俱之臨邛，盡賣其車騎，買一酒舍酤酒，而令文君當鑪。","notes":[{"source":"集解","text":"韋昭曰：「鑪，酒肆也。以土爲墮，邊高似鑪。」"}]},{"id":"a14","section":"司馬相如列傳第五十七","anchor":"俱之臨邛，盡賣其車騎，買一酒舍酤酒，而令文君當鑪。相如身自著犢鼻褌，","notes":[{"source":"集解","text":"韋昭曰：「今三尺布作形如犢鼻矣。稱此者，言其無恥也。今銅印言犢紐，此其類矣。」"}]},{"id":"a15","section":"司馬相如列傳第五十七","anchor":"賣其車騎，買一酒舍酤酒，而令文君當鑪。相如身自著犢鼻褌，與保庸雜作，","notes":[{"source":"集解","text":"方言曰：「保庸謂之甬，奴婢賤稱也。」"}]},{"id":"a16","section":"司馬相如列傳第五十七","anchor":"一酒舍酤酒，而令文君當鑪。相如身自著犢鼻褌，與保庸雜作，滌器於市中。","notes":[{"source":"集解","text":"韋昭曰：「瓦器也。每食必滌溉者。」"}]},{"id":"a17","section":"司馬相如列傳第五十七","anchor":"犢鼻褌，與保庸雜作，滌器於市中。卓王孫聞而恥之，爲杜門不出。昆弟諸公","notes":[{"source":"集解","text":"郭璞曰：「諸公，父行也。」"}]},{"id":"a18","section":"司馬相如列傳第五十七","anchor":"：「有一男兩女，所不足者非財也。今文君已失身於司馬長卿，長卿故倦游，","notes":[{"source":"集解","text":"郭璞曰：「厭游宦也。」"}]},{"id":"a19","section":"司馬相如列傳第五十七","anchor":"居久之，蜀人楊得意爲狗監，","notes":[{"source":"集解","text":"郭璞曰：「主獵犬也。」"}]},{"id":"a20","section":"司馬相如列傳第五十七","anchor":"賦，賦成奏之。」上許，令尚書給筆札。相如以「子虛」，虛言也，爲楚稱；","notes":[{"source":"集解","text":"郭璞曰：「稱說楚之美。」"}]},{"id":"a21","section":"司馬相如列傳第五十七","anchor":"上許，令尚書給筆札。相如以「子虛」，虛言也，爲楚稱；「烏有先生」者，","notes":[{"source":"集解","text":"徐廣曰：「烏，一作惡。」"}]},{"id":"a22","section":"司馬相如列傳第五十七","anchor":"相如以「子虛」，虛言也，爲楚稱；「烏有先生」者，烏有此事也，爲齊難；","notes":[{"source":"集解","text":"郭璞曰：「詰難楚事也。」"}]},{"id":"a23","section":"司馬相如列傳第五十七","anchor":"有先生」者，烏有此事也，爲齊難；「無是公」者，無是人也，明天子之義。","notes":[{"source":"集解","text":"郭璞曰：「以爲折中之談也。」"}]},{"id":"a24","section":"司馬相如列傳第五十七","anchor":"」者，烏有此事也，爲齊難；「無是公」者，無是人也，明天子之義。故空藉","notes":[{"source":"索隱","text":"音假借，與積同音。"}]},{"id":"a25","section":"司馬相如列傳第五十七","anchor":"子虛使於齊，齊王悉發境內之士，備車騎之眾，與使者出田。田罷，子虛過詫","notes":[{"source":"集解","text":"郭璞曰：「詫，誇也。音託夏反。」"},{"source":"索隱","text":"上音戈，下音勑亞反。誇詫是也。"}]},{"id":"a26","section":"司馬相如列傳第五十七","anchor":"子虛曰：「可。王駕車千乘，選徒萬騎，田於海濱。列卒滿澤，罘罔彌山，","notes":[{"source":"集解","text":"郭璞曰：「罘，罝也。音浮。」"},{"source":"正義","text":"說文云「罘，兔罟也」。今幡車罟也。彌，竟也。"}]},{"id":"a27","section":"司馬相如列傳第五十七","anchor":"車千乘，選徒萬騎，田於海濱。列卒滿澤，罘罔彌山，揜兔轔鹿，射麋脚麟。","notes":[{"source":"集解","text":"徐廣曰：「轔音吝。」駰案：郭璞曰「脚，掎足。轔，車轢」。"},{"source":"索隱","text":"脚麟，韋昭云「謂持其一脚也」。司馬彪曰「脚，掎也」。說文云「掎，偏引一脚也」。"}]},{"id":"a28","section":"司馬相如列傳第五十七","anchor":"。列卒滿澤，罘罔彌山，揜兔轔鹿，射麋脚麟。鶩[1]於鹽浦，割鮮染輪。","notes":[{"source":"集解","text":"郭璞曰：「鹽浦，海邊地多鹽鹵。鮮，生肉也。染，擩也。音而沿反，又音而悅反。擩之於輪，鹽而食之。鶩，馳也。音務。」"},{"source":"索隱","text":"李奇云：「鮮，生肉也。染，濡也。切生肉濡鹽而食之。」染或爲「淬」，與下文「脟割輪淬」意同也。"}]},{"id":"a29","section":"司馬相如列傳第五十七","anchor":"顧謂僕曰：『楚亦有平原廣澤游獵之地饒樂若此者乎？楚王之獵何與寡人？』","notes":[{"source":"集解","text":"郭璞曰：「與猶如也。」"}]},{"id":"a30","section":"司馬相如列傳第五十七","anchor":"唯唯。臣聞楚有七澤，嘗見其一，未覩其餘也。臣之所見，蓋特其小小者耳，","notes":[{"source":"索隱","text":"郭璞云：「特，獨也。」"}]},{"id":"a31","section":"司馬相如列傳第五十七","anchor":"楚有七澤，嘗見其一，未覩其餘也。臣之所見，蓋特其小小者耳，名曰雲夢。","notes":[{"source":"索隱","text":"赭詮音亡棟反，又音莫風反。裴駰云「孫叔敖激沮水作此澤」。張揖云「楚藪也，在南郡華容縣」。郭璞曰「江夏安陸有雲夢城，南郡枝江亦有雲夢城。華容縣又有巴丘湖，俗云即古雲夢澤也」。則張揖云在華容者，指巴湖也。今安陸東見有雲夢城、雲夢縣，而枝江亦有者，蓋縣名取此澤，故有城也。"}]},{"id":"a32","section":"司馬相如列傳第五十七","anchor":"方九百里，其中有山焉。其山則盤紆岪鬱，隆崇嵂崒；岑巖參差，日月蔽虧；","notes":[{"source":"集解","text":"《漢書音義》曰：「高山壅蔽，日月虧缺半見。」"},{"source":"索隱","text":"案：《漢書注》此卷多不題注者姓名，解者云是張揖，亦兼有餘人也。"}]},{"id":"a33","section":"司馬相如列傳第五十七","anchor":"，日月蔽虧；交錯糾紛，上干青雲；罷池陂陁，下屬江河。其土則丹青赭堊，","notes":[{"source":"集解","text":"徐廣曰：「一作『瑕』。」"},{"source":"索隱","text":"張揖云：「赭，赤土，出少室山。堊，白堊，本草云一名白墡也。」"}]},{"id":"a34","section":"司馬相如列傳第五十七","anchor":"月蔽虧；交錯糾紛，上干青雲；罷池陂陁，下屬江河。其土則丹青赭堊，雌黃","notes":[{"source":"正義","text":"藥對曰：「雌黃出武都山谷，與雄黃同山。」"}]},{"id":"a35","section":"司馬相如列傳第五十七","anchor":"；交錯糾紛，上干青雲；罷池陂陁，下屬江河。其土則丹青赭堊，雌黃白坿，","notes":[{"source":"集解","text":"徐廣曰：「音符。」駰案：《漢書音義》曰「白坿，白石英也」。"},{"source":"索隱","text":"張揖曰：「白石英也，出魯陽山。」蘇林音附，郭璞音符也。"}]},{"id":"a36","section":"司馬相如列傳第五十七","anchor":"錯糾紛，上干青雲；罷池陂陁，下屬江河。其土則丹青赭堊，雌黃白坿，錫碧","notes":[{"source":"正義","text":"顏云：「錫，青金也。碧謂玉之青白色者也。」"}]},{"id":"a37","section":"司馬相如列傳第五十七","anchor":"，下屬江河。其土則丹青赭堊，雌黃白坿，錫碧金銀，眾色炫燿，照爛龍鱗。","notes":[{"source":"集解","text":"郭璞曰：「如龍之鱗采。」"}]},{"id":"a38","section":"司馬相如列傳第五十七","anchor":"則丹青赭堊，雌黃白坿，錫碧金銀，眾色炫燿，照爛龍鱗。其石則赤玉玫瑰，","notes":[{"source":"集解","text":"郭璞曰：「赤玉，赤瑾也。見楚辭。玫瑰，石珠也。」"}]},{"id":"a39","section":"司馬相如列傳第五十七","anchor":"，雌黃白坿，錫碧金銀，眾色炫燿，照爛龍鱗。其石則赤玉玫瑰，琳瑉琨珸，","notes":[{"source":"集解","text":"《漢書音義》曰：「琳，球也。珉，石次玉者。琨珸，山名也，出善金，尸子曰『昆吾之金』者。」"},{"source":"索隱","text":"琨珸，司馬彪云「石之次玉者」。按：《河圖》云「流州多積石，名昆吾石，鍊之成鐵，以作劍，光明昭如水精」。案：字或作「昆吾」。"}]},{"id":"a40","section":"司馬相如列傳第五十七","anchor":"，錫碧金銀，眾色炫燿，照爛龍鱗。其石則赤玉玫瑰，琳瑉琨珸，瑊玏玄厲，","notes":[{"source":"集解","text":"徐廣曰：「瑊音古咸反，玏音勒，皆次玉者。」駰案：《漢書音義》曰「玄厲，黑石可用磨者」。"}]},{"id":"a41","section":"司馬相如列傳第五十七","anchor":"，眾色炫燿，照爛龍鱗。其石則赤玉玫瑰，琳瑉琨珸，瑊玏玄厲，瑌石武夫。","notes":[{"source":"集解","text":"徐廣曰：「石似玉。」駰案：《漢書音義》曰「瑌石出鴈門，武夫出長沙也」。"}]},{"id":"a42","section":"司馬相如列傳第五十七","anchor":"照爛龍鱗。其石則赤玉玫瑰，琳瑉琨珸，瑊玏玄厲，瑌石武夫。其東則有蕙圃","notes":[{"source":"索隱","text":"司馬彪云：「蕙，香草也。」本草云：「蕙草一名蕙。」廣志云：「薰草綠葉紫莖，魏武帝以此燒香，今東下田有此草，莖葉似麻，其華正紫也。」"}]},{"id":"a43","section":"司馬相如列傳第五十七","anchor":"其石則赤玉玫瑰，琳瑉琨珸，瑊玏玄厲，瑌石武夫。其東則有蕙圃衡蘭，芷若","notes":[{"source":"集解","text":"《漢書音義》曰：「衡，杜衡也。其狀若葵，其臭如蘪蕪。芷，白芷。若，杜若。」"},{"source":"索隱","text":"張揖云「衡，杜衡，生下田山」。案：《山海經》云「天帝之山有草，葉如葵，臭如蘪蕪，可以走馬」。博物志云「一名土杏，其根一似細辛，葉似葵」。故藥對亦爲似細辛是也。蘭，張揖云「秋蘭」。芷若，張揖云「若，杜若；芷，白芷也」。本草云「一名茝」。埤蒼云「齊曰茝，晉曰虈」。《字林》曰「茝音昌亥反，又音昌里反。虈音火嬌反」。本草又曰「杜若，一名杜衡。」今杜若葉似薑而有文理，莖葉皆有長毛。古今名號不同，故其所呼別也。"}]},{"id":"a44","section":"司馬相如列傳第五十七","anchor":"赤玉玫瑰，琳瑉琨珸，瑊玏玄厲，瑌石武夫。其東則有蕙圃衡蘭，芷若射干，","notes":[{"source":"索隱","text":"廣雅云「烏蓬，射干」。本草名烏扇。"}]},{"id":"a45","section":"司馬相如列傳第五十七","anchor":"玫瑰，琳瑉琨珸，瑊玏玄厲，瑌石武夫。其東則有蕙圃衡蘭，芷若射干，穹窮","notes":[{"source":"索隱","text":"芎藭。司馬彪云：「芎藭似藳本。」郭璞云：「今歷陽呼爲江離。」《淮南子》云：「夫亂人者，若芎藭之與槀本。」"}]},{"id":"a46","section":"司馬相如列傳第五十七","anchor":"瑌石武夫。其東則有蕙圃衡蘭，芷若射干，穹窮昌蒲，江離麋蕪，諸蔗猼且。","notes":[{"source":"集解","text":"徐廣曰：「猼音匹沃反。」駰案：《漢書音義》曰「江離，香草，蘪蕪，蘄芷也，似蛇床而香。諸蔗，甘柘也。猼且，蘘荷也」。"},{"source":"索隱","text":"吳錄曰「臨海縣海水中生江離，正青似亂髮，即離騷所云者是也」。廣志云「赤葉紅華」，則與張勃所說又別。案：今芎藭苗曰江離，綠葉白華，又不同。孟康云「麋蕪，蘄芷也，似蛇床而香」。樊光曰「藁本一名麋蕪，根名蘄芷」。又藥對以爲麋蕪一名江離，芎藭苗也。則芎藭、藁本、江離、麋蕪並相似，非是一物也。諸柘，張揖云「諸柘，甘柘也」。搏且，上音並卜反，下音子余反。《漢書》作「巴且」，文穎云「巴蕉也」。郭璞云「搏且，蘘荷屬」。未知孰是也。"}]},{"id":"a47","section":"司馬相如列傳第五十七","anchor":"芷若射干，穹窮昌蒲，江離麋蕪，諸蔗猼且。其南則有平原廣澤，登降陁靡，","notes":[{"source":"集解","text":"音移糜。"}]},{"id":"a48","section":"司馬相如列傳第五十七","anchor":"穹窮昌蒲，江離麋蕪，諸蔗猼且。其南則有平原廣澤，登降陁靡，案衍壇曼，","notes":[{"source":"索隱","text":"司馬彪云：「案衍，窳下；壇曼，平博也。」衍音弋戰反。"}]},{"id":"a49","section":"司馬相如列傳第五十七","anchor":"諸蔗猼且。其南則有平原廣澤，登降陁靡，案衍壇曼，緣以大江，限以巫山。","notes":[{"source":"集解","text":"郭璞曰：「巫山今在建平巫縣也。」"}]},{"id":"a50","section":"司馬相如列傳第五十七","anchor":"原廣澤，登降陁靡，案衍壇曼，緣以大江，限以巫山。其高燥則生葴䔮苞荔，","notes":[{"source":"集解","text":"徐廣曰：「葴音針，馬藍也。䔮，或曰草，生水中，華可食。荔音力詣反。草，似蒲。」駰案：《漢書音義》曰「苞，藨也」。"},{"source":"索隱","text":"葴析。音針斯二音。孟康曰「葴，馬藍也」。郭璞曰「葴，酸漿，江東名烏葴」。析，《漢書》作「斯」，孟康云「斯，禾，似燕麥」。埤蒼又云「生水中，華可食」。廣志云「涼州地生析草，皆如中國燕麥」是也。"}]},{"id":"a51","section":"司馬相如列傳第五十七","anchor":"降陁靡，案衍壇曼，緣以大江，限以巫山。其高燥則生葴䔮苞荔，薛莎青薠。","notes":[{"source":"集解","text":"徐廣曰：「薛音先結反。」駰案：《漢書音義》曰「薛，賴蒿也。莎，鎬侯也。青薠，似莎而大也。音煩」。"}]},{"id":"a52","section":"司馬相如列傳第五十七","anchor":"，案衍壇曼，緣以大江，限以巫山。其高燥則生葴䔮苞荔，薛莎青薠。其卑溼","notes":[{"source":"索隱","text":"其庳溼。庳音婢。庳，下也。"}]},{"id":"a53","section":"司馬相如列傳第五十七","anchor":"江，限以巫山。其高燥則生葴䔮苞荔，薛莎青薠。其卑溼則生藏莨蒹葭，東薔","notes":[{"source":"集解","text":"徐廣曰：「烏桓國有薔，似蓬草，實如葵子，十月熟。」駰案：《漢書音義》曰「藏，似薍而葉大。莨，莨尾草也。蒹，薕也。葭，蘆也」。"},{"source":"索隱","text":"藏莨，郭璞云「狼尾，似茅」。蒹葭音兼加。孟康云「蒹葭似蘆也」。郭璞云「蒹，𧁱也。似雚而細小，高數尺，江東人呼爲蒹蒿」。又云「葭，蘆也。似葦而細小，江東人呼爲烏蓲」。薍音五患反。𧁱音敵。東薔，案《續漢書》云「東薔似蓬草，實如葵子，十一月熟」。廣志云「子色青黑，河西語云『貸我東薔，償我白粱』也」。"}]},{"id":"a54","section":"司馬相如列傳第五十七","anchor":"以巫山。其高燥則生葴䔮苞荔，薛莎青薠。其卑溼則生藏莨蒹葭，東薔雕胡，","notes":[{"source":"索隱","text":"彫胡。案謂菰米。"}]},{"id":"a55","section":"司馬相如列傳第五十七","anchor":"高燥則生葴䔮苞荔，薛莎青薠。其卑溼則生藏莨蒹葭，東薔雕胡，蓮藕菰蘆，","notes":[{"source":"集解","text":"徐廣曰：「生水中。」"},{"source":"索隱","text":"郭璞云：「菰，蔣也。蘆，葦也。」"}]},{"id":"a56","section":"司馬相如列傳第五十七","anchor":"䔮苞荔，薛莎青薠。其卑溼則生藏莨蒹葭，東薔雕胡，蓮藕菰蘆，菴䕡軒芋，","notes":[{"source":"集解","text":"《漢書音義》曰：「奄閭，蒿也。軒芋，蕕草也。」"},{"source":"索隱","text":"郭璞云：「菴閭，蒿，子可療病也。軒芋生水中，今楊州有也。」"}]},{"id":"a57","section":"司馬相如列傳第五十七","anchor":"卑溼則生藏莨蒹葭，東薔雕胡，蓮藕菰蘆，菴䕡軒芋，衆物居之，不可勝圖。","notes":[{"source":"集解","text":"郭璞曰：「圖，畫也。」"}]},{"id":"a58","section":"司馬相如列傳第五十七","anchor":"有湧泉清池，激水推移；外發芙蓉蔆華，內隱鉅石白沙。其中則有神龜蛟鼉，","notes":[{"source":"正義","text":"郭注《山海經》云：「蛟，似蛇而四腳，小頭細頸，有白嬰，大者數十圍，卵生，子如一二斛瓮，吞人。鼉，似蜥蜴而大，身有甲，皮可以冒鼓。」"}]},{"id":"a59","section":"司馬相如列傳第五十七","anchor":"泉清池，激水推移；外發芙蓉蔆華，內隱鉅石白沙。其中則有神龜蛟鼉，瑇瑁","notes":[{"source":"正義","text":"似觜觿，甲有文，出南海，可飾器物也。"}]},{"id":"a60","section":"司馬相如列傳第五十七","anchor":"外發芙蓉蔆華，內隱鉅石白沙。其中則有神龜蛟鼉，瑇瑁鼈黿。其北則有陰林","notes":[{"source":"集解","text":"郭璞曰：「林在山北陰地。」"}]},{"id":"a61","section":"司馬相如列傳第五十七","anchor":"隱鉅石白沙。其中則有神龜蛟鼉，瑇瑁鼈黿。其北則有陰林巨樹，楩枏豫章，","notes":[{"source":"集解","text":"郭璞曰：「楩，杞也，似梓。枏，葉似桑。豫章，大木也，生七年乃可知也。」"},{"source":"正義","text":"案：（溫）活人云「豫，今之枕木也。章，今之樟木也。二木生至七年，枕樟乃可分別」。"}]},{"id":"a62","section":"司馬相如列傳第五十七","anchor":"石白沙。其中則有神龜蛟鼉，瑇瑁鼈黿。其北則有陰林巨樹，楩枏豫章，桂椒","notes":[{"source":"正義","text":"郭璞云：「桂，似枇杷葉而大，白花，花而不著子，藂生巖嶺閒，無雜木，冬夏常青。」案：今諸寺有桂樹，葉若枇杷而小，光靜，冬夏常青，其皮不中食，蓋二色桂樹。"}]},{"id":"a63","section":"司馬相如列傳第五十七","anchor":"。其中則有神龜蛟鼉，瑇瑁鼈黿。其北則有陰林巨樹，楩枏豫章，桂椒木蘭，","notes":[{"source":"集解","text":"駰案：郭璞曰「木蘭，樹，皮辛香可食」。"},{"source":"正義","text":"廣雅云：「似桂，皮辛可食，葉冬夏榮，常以冬華，其實如小（甘）柿，辛美，南人以爲梅也。」"}]},{"id":"a64","section":"司馬相如列傳第五十七","anchor":"神龜蛟鼉，瑇瑁鼈黿。其北則有陰林巨樹，楩枏豫章，桂椒木蘭，蘗離朱楊，","notes":[{"source":"集解","text":"徐廣曰：「蘗音扶戾反。」《漢書音義》曰：「離，山梨。朱楊，赤楊也。」"},{"source":"索隱","text":"朱楊，郭璞云「赤莖柳，生水邊」，《爾雅》云檉河柳是也。"}]},{"id":"a65","section":"司馬相如列傳第五十七","anchor":"瑇瑁鼈黿。其北則有陰林巨樹，楩枏豫章，桂椒木蘭，蘗離朱楊，樝梸梬栗，","notes":[{"source":"集解","text":"徐廣曰：「梬音郢。」駰案：《漢書音義》曰「梬，梬棗也」。"}]},{"id":"a66","section":"司馬相如列傳第五十七","anchor":"其北則有陰林巨樹，楩枏豫章，桂椒木蘭，蘗離朱楊，樝梸梬栗，橘柚芬芳。","notes":[{"source":"正義","text":"小曰橘，大曰柚。樹有刺，冬不凋，葉青，花白，子黃赤。二樹相似。非橙也。"}]},{"id":"a67","section":"司馬相如列傳第五十七","anchor":"楩枏豫章，桂椒木蘭，蘗離朱楊，樝梸梬栗，橘柚芬芳。其上則有赤猨蠷蝚，","notes":[{"source":"集解","text":"徐廣曰：「音劬柔。」"},{"source":"正義","text":"蠷音劬，蝚音柔，皆猿猴類。"}]},{"id":"a68","section":"司馬相如列傳第五十七","anchor":"蘗離朱楊，樝梸梬栗，橘柚芬芳。其上則有赤猨蠷蝚，鵷雛孔鸞，騰遠射干。","notes":[{"source":"集解","text":"郭璞曰：「鵷雛，鳳屬也。孔，孔雀；鸞，鸞鳥也。」《漢書音義》曰：「騰遠，鳥名。射干，似狐，能緣木。」"},{"source":"索隱","text":"孟康云「騰遠，鳥名」，非也。司馬彪云：「騰遠，虵也。」郭璞云：「騰虵，龍屬，能興雲霧。」張揖云：「射干，似狐，能緣木。」"}]},{"id":"a69","section":"司馬相如列傳第五十七","anchor":"。其上則有赤猨蠷蝚，鵷雛孔鸞，騰遠射干。其下則有白虎玄豹，蟃蜒貙豻，","notes":[{"source":"集解","text":"郭璞曰：「蟃蜒，大獸，長百尋。貙，似貍而大。」《漢書音義》曰：「豻，胡地野犬，似狐而小也。」"},{"source":"索隱","text":"郭璞云：「蟃蜒，大獸，長百尋。」張揖云：「貙，似貍而大。豻，胡地野犬，似狐而小，黑喙。」應劭音顏，韋昭一音岸。鄒誕生音苦姦反，協音，是。"}]},{"id":"a70","section":"司馬相如列傳第五十七","anchor":"赤猨蠷蝚，鵷雛孔鸞，騰遠射干。其下則有白虎玄豹，蟃蜒貙豻，兕象野犀，","notes":[{"source":"正義","text":"兕，狀如水牛。象，大獸，長鼻，牙長一丈，俗呼爲江猨。犀，頭似猨，一角在額。《漢書》無此一句。"}]},{"id":"a71","section":"司馬相如列傳第五十七","anchor":"「『於是乃使專諸之倫，手格此獸。楚王乃駕馴駁之駟，","notes":[{"source":"集解","text":"《漢書音義》曰：「馴，擾也。駁，如馬，白身，黑尾，一角，鋸牙，食虎豹。擾而駕之，以當駟馬。」"}]},{"id":"a72","section":"司馬相如列傳第五十七","anchor":"乃使專諸之倫，手格此獸。楚王乃駕馴駁之駟，乘雕玉之輿，靡魚須之橈旃，","notes":[{"source":"集解","text":"郭璞曰：「以海魚須爲旒旌，言橈弱也。通帛爲旃也。」"}]},{"id":"a73","section":"司馬相如列傳第五十七","anchor":"手格此獸。楚王乃駕馴駁之駟，乘雕玉之輿，靡魚須之橈旃，曳明月之珠旗，","notes":[{"source":"集解","text":"《漢書音義》曰：「以明月珠綴飾旗。」"}]},{"id":"a74","section":"司馬相如列傳第五十七","anchor":"乃駕馴駁之駟，乘雕玉之輿，靡魚須之橈旃，曳明月之珠旗，建干將之雄戟，","notes":[{"source":"集解","text":"《漢書音義》曰：「干將，韓王劍師。雄戟，胡中有𧣒，干將所造也。」"},{"source":"索隱","text":"應劭曰：「干將，吳善冶者姓。」如淳曰：「干將，鐵所出。」晉灼曰：「闔閭鑄干將劍。」應劭說是。方言云：「戟中小孑刺者，所謂雄戟也。」周處風土記云：「戟爲五兵雄也。」𧣒音巨。案：《周禮》「冶氏爲戈，胡三之」。注云「胡其孑」也。又禮圖謂「戟支曲下爲胡」也。"}]},{"id":"a75","section":"司馬相如列傳第五十七","anchor":"乘雕玉之輿，靡魚須之橈旃，曳明月之珠旗，建干將之雄戟，左烏嗥之雕弓，","notes":[{"source":"索隱","text":"烏號之雕弓。黃帝上仙，羣臣舉弓抱之而號，見《封禪書》及《郊祀志》文。韓詩外傳云弓工之妻曰「此弓大山南烏號之柘」。案：《淮南子》云「烏號，柘桑，其材堅勁，烏棲其上，將飛，枝勁復起，號呼其上。伐取其材爲弓，因曰『烏號』」。　《古史考》、風俗通皆同此說也。"}]},{"id":"a76","section":"司馬相如列傳第五十七","anchor":"魚須之橈旃，曳明月之珠旗，建干將之雄戟，左烏嗥之雕弓，右夏服之勁箭；","notes":[{"source":"集解","text":"徐廣曰：「韋昭云夏，夏羿也。矢室名曰服。」呂靜曰：「步叉謂之服也。」"},{"source":"索隱","text":"案：夏羿，善射者。又服，箭室之名，故云「夏服」。又夏后氏有良弓名「繁弱」，其矢亦良，即「繁弱箭服」是也。"}]},{"id":"a77","section":"司馬相如列傳第五十七","anchor":"珠旗，建干將之雄戟，左烏嗥之雕弓，右夏服之勁箭；陽子驂乘，纖阿爲御；","notes":[{"source":"集解","text":"《漢書音義》曰：「陽子，僊人陵陽子。纖阿，月御也。」韋昭曰：「陽子，古賢也。」"},{"source":"索隱","text":"服虔云：「陽子，仙人陵陽子也。」張揖云：「陽子，伯樂也。孫陽字伯樂，秦繆公臣，善御者也。」服虔云：「纖阿爲月御。或曰美女姣好貌。」又樂產曰：「纖阿，山名，有女子處其巖，月歷巖度，躍入月中，因名月御也。」"}]},{"id":"a78","section":"司馬相如列傳第五十七","anchor":"將之雄戟，左烏嗥之雕弓，右夏服之勁箭；陽子驂乘，纖阿爲御；案節未舒，","notes":[{"source":"索隱","text":"郭璞曰：「言頓轡也。」司馬彪云「案轡徐行得節，故曰案節，馬足未展，故曰未舒之也」，亦（曰未）〔爲〕得也。"}]},{"id":"a79","section":"司馬相如列傳第五十七","anchor":"夏服之勁箭；陽子驂乘，纖阿爲御；案節未舒，即陵狡獸，轔邛邛，蹵距虛，","notes":[{"source":"集解","text":"郭璞曰：「邛邛，似馬而色青。距虛即邛邛，變文互言之。穆天子傳曰『邛邛距虛，日走五百里』也。」"}]},{"id":"a80","section":"司馬相如列傳第五十七","anchor":"驂乘，纖阿爲御；案節未舒，即陵狡獸，轔邛邛，蹵距虛，軼野馬而𨎥騊駼，","notes":[{"source":"集解","text":"徐廣曰：「𨎥音銳。」駰案：郭璞曰「野馬，如馬而小。騊駼，似馬。𨎥，車軸頭」。"},{"source":"索隱","text":"䡺騊駼。上音衞。䡺，車軸頭也。謂車軸衝殺之。騊駼，野馬。"}]},{"id":"a81","section":"司馬相如列傳第五十七","anchor":"案節未舒，即陵狡獸，轔邛邛，蹵距虛，軼野馬而𨎥騊駼，乘遺風而射游騏；","notes":[{"source":"集解","text":"《漢書音義》曰：「遺風，千里馬。《爾雅》曰巂，如馬，一角。不角者，騏也。」"},{"source":"索隱","text":"《呂氏春秋》云：「遺風之乘。」古今注云：「秦始皇馬名。」韋昭云：「騏如馬，一角。」《爾雅》云：「巂無角曰騏。」非麒麟之騏。巂音攜。"}]},{"id":"a82","section":"司馬相如列傳第五十七","anchor":"即陵狡獸，轔邛邛，蹵距虛，軼野馬而𨎥騊駼，乘遺風而射游騏；儵眒淒浰，","notes":[{"source":"集解","text":"徐廣曰：「淒音七見反。浰音力詣反。」駰案：《漢書音義》曰「皆疾貌」。"}]},{"id":"a83","section":"司馬相如列傳第五十七","anchor":"，乘遺風而射游騏；儵眒淒浰，靁動熛至，星流霆擊，弓不虛發，中必決眥，","notes":[{"source":"集解","text":"韋昭曰：「在目所指，中必決於眼眥也。」"}]},{"id":"a84","section":"司馬相如列傳第五十七","anchor":"必決眥，洞胸達腋，絕乎心繫，獲若雨獸，揜草蔽地。於是楚王乃弭節裴回，","notes":[{"source":"集解","text":"郭璞曰：「或云節，今之所杖信節也。」"},{"source":"索隱","text":"司馬彪云：「弭猶低也。或云節，今之所言杖（節）信〔節〕也。」"}]},{"id":"a85","section":"司馬相如列傳第五十七","anchor":"胸達腋，絕乎心繫，獲若雨獸，揜草蔽地。於是楚王乃弭節裴回，翱翔容與，","notes":[{"source":"索隱","text":"郭璞曰：「言自得。」"}]},{"id":"a86","section":"司馬相如列傳第五十七","anchor":"回，翱翔容與，覽乎陰林，觀壯士之暴怒，與猛獸之恐懼，徼{谷凡}受詘，","notes":[{"source":"集解","text":"{{{1}}}"},{"source":"索隱","text":"{{{1}}}"}]},{"id":"a87","section":"司馬相如列傳第五十七","anchor":"「『於是鄭女曼姬，","notes":[{"source":"集解","text":"郭璞曰：「曼姬謂鄧曼。姬，婦人之總稱。」"},{"source":"正義","text":"文穎云：「鄭國出好女。曼者，其色理曼澤也。」如淳云：「鄭女，夏姬也。曼姬，楚武王夫人鄧曼。」"}]},{"id":"a88","section":"司馬相如列傳第五十七","anchor":"「『於是鄭女曼姬，被阿錫，","notes":[{"source":"集解","text":"《漢書音義》曰：「阿，細繒也。錫，布也。」"},{"source":"正義","text":"按：東阿出繒也。"}]},{"id":"a89","section":"司馬相如列傳第五十七","anchor":"「『於是鄭女曼姬，被阿錫，揄紵縞，","notes":[{"source":"集解","text":"徐廣曰：「揄音臾。」"},{"source":"正義","text":"揄，曳也。韋昭云：「紵之色若縞也。」顏云：「紵，織紵也。縞，鮮支也。」"}]},{"id":"a90","section":"司馬相如列傳第五十七","anchor":"「『於是鄭女曼姬，被阿錫，揄紵縞，襍纖羅，垂霧縠；","notes":[{"source":"集解","text":"郭璞曰：「言細如霧，垂以覆頭。」"}]},{"id":"a91","section":"司馬相如列傳第五十七","anchor":"曼姬，被阿錫，揄紵縞，襍纖羅，垂霧縠；襞積褰縐，紆徐委曲，鬱橈谿谷；","notes":[{"source":"集解","text":"《漢書音義》曰：「襞積，簡齰也。褰，縮也。縐，裁也。其縐中文理，茀鬱𨒅曲，有似於谿谷也。」"},{"source":"索隱","text":"小顏云：「襞積，今之裙襵，古謂之素積。」蘇林曰「褰縐，縮蹙之」是也。縐音側救反。齰音叉革反。裁音在代反。鬱橈谿谷，孟康曰「其縐中文理，茀鬱𨒅曲，有似于谿谷也」。𨒅，《字林》音丘亦反。"}]},{"id":"a92","section":"司馬相如列傳第五十七","anchor":"錫，揄紵縞，襍纖羅，垂霧縠；襞積褰縐，紆徐委曲，鬱橈谿谷；衯衯裶裶，","notes":[{"source":"索隱","text":"郭璞云：「衣長貌。」"},{"source":"正義","text":"上芳云反，下方非反。"}]},{"id":"a93","section":"司馬相如列傳第五十七","anchor":"，襍纖羅，垂霧縠；襞積褰縐，紆徐委曲，鬱橈谿谷；衯衯裶裶，揚袘卹削，","notes":[{"source":"集解","text":"徐廣曰：「袘音迤，衣袖也。」駰案：《漢書音義》曰「卹削，裁制貌也」。"},{"source":"索隱","text":"揚袘戌削。張晏曰：「揚，舉也。袘，衣袖也。戌削，裁制貌也。」"}]},{"id":"a94","section":"司馬相如列傳第五十七","anchor":"垂霧縠；襞積褰縐，紆徐委曲，鬱橈谿谷；衯衯裶裶，揚袘卹削，蜚纖垂髾；","notes":[{"source":"集解","text":"徐廣曰：「纖音芟。」駰案：郭璞云「纖，袿衣飾；髾，髻髾也」。"}]},{"id":"a95","section":"司馬相如列傳第五十七","anchor":"積褰縐，紆徐委曲，鬱橈谿谷；衯衯裶裶，揚袘卹削，蜚纖垂髾；扶與猗靡，","notes":[{"source":"集解","text":"郭璞曰：「淮南所謂『曾折摩地，扶與猗委』也。」"},{"source":"正義","text":"輿音餘。猗，於綺反。謂鄭女曼姬侍從王者，扶其車輿而猗靡。"}]},{"id":"a96","section":"司馬相如列傳第五十七","anchor":"徐委曲，鬱橈谿谷；衯衯裶裶，揚袘卹削，蜚纖垂髾；扶與猗靡，噏呷萃蔡，","notes":[{"source":"集解","text":"《漢書音義》曰：「噏呷，衣裳張起也。萃蔡，衣聲也。」"},{"source":"索隱","text":"孟康曰：「噏呷，衣起張也。」韋昭云：「呷音呼甲反。」萃𭽀，孟康云「萃𭽀，衣聲也」。郭璞曰「萃𭽀猶璀璨也」。"},{"source":"正義","text":"呷，火甲反。萃音翠。蔡，千賄反。"}]},{"id":"a97","section":"司馬相如列傳第五十七","anchor":"削，蜚纖垂髾；扶與猗靡，噏呷萃蔡，下摩蘭蕙，上拂羽蓋，錯翡翠之威蕤，","notes":[{"source":"集解","text":"徐廣曰：「錯音措。或作『錯粉翠蕤』。」"}]},{"id":"a98","section":"司馬相如列傳第五十七","anchor":"髾；扶與猗靡，噏呷萃蔡，下摩蘭蕙，上拂羽蓋，錯翡翠之威蕤，繆繞玉綏；","notes":[{"source":"集解","text":"郭璞曰：「綏，所執以登車。」"},{"source":"正義","text":"顏云：「下摩蘭蕙，謂垂髾也。上拂羽蓋，謂飛襳也。玉綏，以玉飾綏也。」言飛襳垂髾，錯襍翡翠之旌幡，或繞玉綏也。張揖云：「翡翠大小一如雀，雄赤曰翡，雌青曰翠。」博物志云：「翡身通黑，唯胸前背上翼後有赤毛。翠身通青黃，唯六翮上毛長寸餘青。其飛則羽鳴翠翡翠翡然，因以爲名也。」"}]},{"id":"a99","section":"司馬相如列傳第五十七","anchor":"下摩蘭蕙，上拂羽蓋，錯翡翠之威蕤，繆繞玉綏；縹乎忽忽，若神仙之仿佛。","notes":[{"source":"正義","text":"仿佛，言似神仙也。《戰國策》云：「鄭之美女粉白黛黑而立於衢，不知者謂之神仙。」"}]},{"id":"a100","section":"司馬相如列傳第五十七","anchor":"「『於是乃相與獠於蕙圃，","notes":[{"source":"集解","text":"郭璞曰：「獠，獵也。音遼。」"},{"source":"索隱","text":"《爾雅》云：「宵獵曰獠。」郭璞曰：「獠，獵也。又音遼也。」"}]},{"id":"a101","section":"司馬相如列傳第五十七","anchor":"「『於是乃相與獠於蕙圃，媻珊勃窣","notes":[{"source":"索隱","text":"盤㹪勃猝。韋昭曰：「盤㹪，匍匐上下也。」猝音素忽反。"}]},{"id":"a102","section":"司馬相如列傳第五十七","anchor":"「『於是乃相與獠於蕙圃，媻珊勃窣上金隄，揜翡翠，射鵕䴊，","notes":[{"source":"集解","text":"《漢書音義》曰：「鵕䴊，鳥，似鳳也。」"},{"source":"索隱","text":"司馬彪云：「鵕䴊，山雞也。」許慎云：「鷩鳥也。」郭璞曰：「似鳳，有光彩。音浚宜。」李彤云：「鵕䴊，神鳥，飛光竟天也。」"}]},{"id":"a103","section":"司馬相如列傳第五十七","anchor":"於是乃相與獠於蕙圃，媻珊勃窣上金隄，揜翡翠，射鵕䴊，微矰出，纖繳施，","notes":[{"source":"集解","text":"徐廣曰：「繳音斫。」"}]},{"id":"a104","section":"司馬相如列傳第五十七","anchor":"圃，媻珊勃窣上金隄，揜翡翠，射鵕䴊，微矰出，纖繳施，弋白鵠，連駕鵝，","notes":[{"source":"集解","text":"郭璞曰：「野鵝也。駕音加。」"},{"source":"索隱","text":"駕鵝。《爾雅》云：「舒鴈，鵝也。」郭璞曰：「野鵝也。」"},{"source":"正義","text":"鵠，水烏也。駕鵝連謂兼獲也。抱朴子云：「千歲之鵠純白，能登於木。」"}]},{"id":"a105","section":"司馬相如列傳第五十七","anchor":"隄，揜翡翠，射鵕䴊，微矰出，纖繳施，弋白鵠，連駕鵝，雙鶬下，玄鶴加。","notes":[{"source":"集解","text":"郭璞曰：「《詩》云『弋言加之』是也。」"},{"source":"正義","text":"司馬彪云：「鶬似鴈而黑，亦呼爲鶬括。韓詩外傳云胎生也。」相鶴經云：「鶴壽二百六十歲則色純黑。」案：弋雙鶬既下，又加玄鶴之上也。"}]},{"id":"a106","section":"司馬相如列傳第五十七","anchor":"纖繳施，弋白鵠，連駕鵝，雙鶬下，玄鶴加。怠而後發，游於清池；浮文鷁，","notes":[{"source":"集解","text":"《漢書音義》曰：「鷁，水鳥也。畫其象於船首。《淮南子》曰『龍舟鷁首，天子之乘也』。」"}]},{"id":"a107","section":"司馬相如列傳第五十七","anchor":"弋白鵠，連駕鵝，雙鶬下，玄鶴加。怠而後發，游於清池；浮文鷁，揚桂枻，","notes":[{"source":"集解","text":"徐廣曰：「音曳。」駰案：韋昭曰「枻，檝也」。"}]},{"id":"a108","section":"司馬相如列傳第五十七","anchor":"怠而後發，游於清池；浮文鷁，揚桂枻，張翠帷，建羽蓋，罔瑇瑁，釣紫貝；","notes":[{"source":"集解","text":"郭璞曰：「紫質黑文也。」"},{"source":"正義","text":"毛詩蟲魚疏云：「貝，水之介蟲。大者蚢，音下郎反。小者爲貝，其白質如玉，紫點爲文，皆成行列。當大者徑一尺，小者七八寸。今九真、交阯以爲杯盤實物也。」貨殖傳云「貝寶龜」是也。"}]},{"id":"a109","section":"司馬相如列傳第五十七","anchor":"池；浮文鷁，揚桂枻，張翠帷，建羽蓋，罔瑇瑁，釣紫貝；摐金鼓，吹鳴籟，","notes":[{"source":"集解","text":"《漢書音義》曰：「摐，撞也。籟，簫也。」"}]},{"id":"a110","section":"司馬相如列傳第五十七","anchor":"鷁，揚桂枻，張翠帷，建羽蓋，罔瑇瑁，釣紫貝；摐金鼓，吹鳴籟，榜人歌，","notes":[{"source":"集解","text":"郭璞曰：「唱櫂歌也。榜，船也，音謗。」"}]},{"id":"a111","section":"司馬相如列傳第五十七","anchor":"枻，張翠帷，建羽蓋，罔瑇瑁，釣紫貝；摐金鼓，吹鳴籟，榜人歌，聲流喝，","notes":[{"source":"集解","text":"徐廣曰：「烏邁反。」"}]},{"id":"a112","section":"司馬相如列傳第五十七","anchor":"「『將息獠者，擊靈鼓，","notes":[{"source":"集解","text":"郭璞曰：「靈鼓，六面也。」"}]},{"id":"a113","section":"司馬相如列傳第五十七","anchor":"「『將息獠者，擊靈鼓，起烽燧，車案行，騎就隊，纚乎淫淫，班乎裔裔。","notes":[{"source":"集解","text":"郭璞曰：「皆羣行貌也。」"}]},{"id":"a114","section":"司馬相如列傳第五十七","anchor":"，起烽燧，車案行，騎就隊，纚乎淫淫，班乎裔裔。於是楚王乃登陽雲之臺，","notes":[{"source":"集解","text":"徐廣曰：「宋玉云楚王游於陽雲之臺。」駰案：郭璞曰「在雲夢之中」。"}]},{"id":"a115","section":"司馬相如列傳第五十七","anchor":"裔裔。於是楚王乃登陽雲之臺，泊乎無爲，澹乎自持，勺藥之和具而後御之。","notes":[{"source":"集解","text":"郭璞曰：「勺藥，五味也。」"}]},{"id":"a116","section":"司馬相如列傳第五十七","anchor":"，勺藥之和具而後御之。不若大王終日馳騁而不下輿，脟割輪淬，自以爲娛。","notes":[{"source":"集解","text":"徐廣曰：「淬，千內反。」駰案：郭璞曰「脟，膊；淬，染也。脟音臠也」。"}]},{"id":"a117","section":"司馬相如列傳第五十七","anchor":"烏有先生曰：「是何言之過也！足下不遠千里，來況齊國，","notes":[{"source":"集解","text":"郭璞曰：「言有惠況也。」"}]},{"id":"a118","section":"司馬相如列傳第五十七","anchor":"傷私義，二者無一可，而先生行之，必且輕於齊而累於楚矣。且齊東陼巨海，","notes":[{"source":"索隱","text":"陼，蘇林音渚。小洲曰陼。謂東有大海之陼也。"}]},{"id":"a119","section":"司馬相如列傳第五十七","anchor":"者無一可，而先生行之，必且輕於齊而累於楚矣。且齊東陼巨海，南有琅邪，","notes":[{"source":"集解","text":"郭璞曰：「山名，在琅邪縣界。」"},{"source":"正義","text":"山名，在密州東南百三十里。琅邪臺在山上。"}]},{"id":"a120","section":"司馬相如列傳第五十七","anchor":"而先生行之，必且輕於齊而累於楚矣。且齊東陼巨海，南有琅邪，觀乎成山，","notes":[{"source":"集解","text":"徐廣曰：「在東萊不夜縣。」"},{"source":"索隱","text":"張揖云：「觀，闕也。於山上築宮闕。」郭璞云：「言在山下遊觀，音館也。」"},{"source":"正義","text":"《封禪書》云「成山斗入海」，言上山觀也。《括地志》云：「成山在萊州文登縣東北百八十里也。」"}]},{"id":"a121","section":"司馬相如列傳第五十七","anchor":"，必且輕於齊而累於楚矣。且齊東陼巨海，南有琅邪，觀乎成山，射乎之罘，","notes":[{"source":"集解","text":"《漢書音義》曰：「之罘山在牟平縣。射獵其上也。」"},{"source":"正義","text":"《括地志》云：「罘山在萊州文登縣西北百九十里。」言射獵其上也。罘音浮。"}]},{"id":"a122","section":"司馬相如列傳第五十七","anchor":"於齊而累於楚矣。且齊東陼巨海，南有琅邪，觀乎成山，射乎之罘，浮勃澥，","notes":[{"source":"集解","text":"《漢書音義》曰：「海別枝名也。」"},{"source":"索隱","text":"案：齊都賦云「海傍曰勃，斷水曰澥」也。"}]},{"id":"a123","section":"司馬相如列傳第五十七","anchor":"於楚矣。且齊東陼巨海，南有琅邪，觀乎成山，射乎之罘，浮勃澥，游孟諸，","notes":[{"source":"集解","text":"郭璞曰：「宋之藪澤名。」"},{"source":"正義","text":"《周禮》職方氏「青州藪曰望諸」，鄭玄云「望諸，孟瀦也」。"}]},{"id":"a124","section":"司馬相如列傳第五十七","anchor":"陼巨海，南有琅邪，觀乎成山，射乎之罘，浮勃澥，游孟諸，邪與肅慎爲鄰，","notes":[{"source":"正義","text":"邪謂東北接之。《括地志》云：「靺鞨國，古肅慎也，亦曰挹婁，在京東北八千四百里，南去扶餘千五百里，東及北各抵大海也。」"}]},{"id":"a125","section":"司馬相如列傳第五十七","anchor":"邪，觀乎成山，射乎之罘，浮勃澥，游孟諸，邪與肅慎爲鄰，右以湯谷爲界，","notes":[{"source":"正義","text":"言右者，北向天子也。海外經云：「湯谷在黑齒北，上有扶桑木，水中十日所浴。」張揖云：「日所出也。」許慎云：「熱如湯。」"}]},{"id":"a126","section":"司馬相如列傳第五十七","anchor":"，射乎之罘，浮勃澥，游孟諸，邪與肅慎爲鄰，右以湯谷爲界，秋田乎青丘，","notes":[{"source":"集解","text":"郭璞曰：「青丘，山名。亦有田，出九尾狐，在海外矣。」"},{"source":"索隱","text":"郭璞云：「山名。出九尾狐也。」"},{"source":"正義","text":"服虔云：「青丘國在海東三百里。」郭璞云：「青丘，山名。上有田，亦有國，出九尾狐，在海外。」"}]},{"id":"a127","section":"司馬相如列傳第五十七","anchor":"湯谷爲界，秋田乎青丘，傍偟乎海外，吞若雲夢者八九，其於胸中曾不蔕芥。","notes":[{"source":"索隱","text":"張揖曰：「刺鯁也。」郭璞云：「言不覺有也。」"}]},{"id":"a128","section":"司馬相如列傳第五十七","anchor":"殊類，珍怪鳥獸，萬端鱗萃，充仞其中者，不可勝記，禹不能名，契不能計。","notes":[{"source":"正義","text":"禹爲堯司空，辨九州土地山川草木禽獸。契爲司徒，敷五教，主四方會計。言二人猶不能名計其數。"}]},{"id":"a129","section":"司馬相如列傳第五十七","anchor":"記，禹不能名，契不能計。然在諸侯之位，不敢言游戲之樂，苑囿之大；先生","notes":[{"source":"索隱","text":"指子虛也。"}]},{"id":"a130","section":"司馬相如列傳第五十七","anchor":"能名，契不能計。然在諸侯之位，不敢言游戲之樂，苑囿之大；先生又見客，","notes":[{"source":"索隱","text":"如淳曰：「見賓客禮待故也。」李善曰：「言見先生是（賓）客（之）也。」"}]},{"id":"a131","section":"司馬相如列傳第五十七","anchor":"然在諸侯之位，不敢言游戲之樂，苑囿之大；先生又見客，是以王辭而不復，","notes":[{"source":"索隱","text":"郭璞曰：「復，答也。」"}]},{"id":"a132","section":"司馬相如列傳第五十七","anchor":"無是公听然而笑","notes":[{"source":"集解","text":"郭璞曰：「听，笑貌也。」"},{"source":"索隱","text":"說文云：「听，笑皃。」"}]},{"id":"a133","section":"司馬相如列傳第五十七","anchor":"曰：「楚則失矣，齊亦未爲得也。夫使諸侯納貢者，非爲財幣，所以述職也；","notes":[{"source":"集解","text":"郭璞曰：「諸侯朝於天子曰述職，言述所職。見孟子。」"}]},{"id":"a134","section":"司馬相如列傳第五十七","anchor":"諸侯納貢者，非爲財幣，所以述職也；封疆畫界者，非爲守禦，所以禁淫也。","notes":[{"source":"集解","text":"郭璞曰：「禁絕淫放也。」"}]},{"id":"a135","section":"司馬相如列傳第五十七","anchor":"「左蒼梧，右西極，","notes":[{"source":"集解","text":"郭璞曰：「西極，邠國也。見《爾雅》。」"},{"source":"正義","text":"文穎云：「蒼梧郡屬交州，在長安東南，故言左。《爾雅》云西至於豳國爲極。在長安西，故言右。」"}]},{"id":"a136","section":"司馬相如列傳第五十七","anchor":"「左蒼梧，右西極，丹水更其南，","notes":[{"source":"集解","text":"《漢書音義》曰：「丹水出上洛冢領山。」"}]},{"id":"a137","section":"司馬相如列傳第五十七","anchor":"「左蒼梧，右西極，丹水更其南，紫淵徑其北；","notes":[{"source":"集解","text":"郭璞曰：「紫淵所未詳。」"},{"source":"正義","text":"《山海經》云：「紫淵水出根耆之山，西流注河。」文穎云：「西河穀羅縣有紫澤，（其水紫色注亦紫）在縣北，於長安爲北。」"}]},{"id":"a138","section":"司馬相如列傳第五十七","anchor":"「左蒼梧，右西極，丹水更其南，紫淵徑其北；終始霸滻，出入涇渭；","notes":[{"source":"索隱","text":"張揖云：「灞出藍田西北而入渭。滻亦出藍田谷，北至霸陵入灞。灞滻二水盡於苑中不出，故云終始也。涇渭二水從苑外來，又出苑去也。涇水出安定涇陽縣幵頭山，東至陽陵入渭。渭水出隴西首陽縣鳥鼠同穴山，東北至華陰入河。」"}]},{"id":"a139","section":"司馬相如列傳第五十七","anchor":"「左蒼梧，右西極，丹水更其南，紫淵徑其北；終始霸滻，出入涇渭；酆鄗","notes":[{"source":"索隱","text":"豐鎬。張揖云：「豐水出鄠縣南山豐谷，北入渭。鎬在昆明池北。」郭璞云：「鎬水，豐水下流也。」"}]},{"id":"a140","section":"司馬相如列傳第五十七","anchor":"左蒼梧，右西極，丹水更其南，紫淵徑其北；終始霸滻，出入涇渭；酆鄗潦潏","notes":[{"source":"集解","text":"郭璞曰：「皆水流貌，音決。」"},{"source":"索隱","text":"應劭云：「潦，流也。潏，涌出聲也。」張揖云：「又有潏水，出南山。」姚氏云：「潦，或作『澇』也。澇水出鄠縣，北注渭。潏水出杜陵，今名沇水，自南山皇子陂西北流注昆明池入渭。」案：此下文「八川分流」，則從涇、渭、灞、滻、豐、鎬、潦、潏爲八。晉灼曰：「從丹水下則有九，從灞以下則七。」案：今潏既是水名，除丹紫二川，自涇渭以下適足八川，是經營乎其內也。又潘岳《關中記》曰「涇、渭、灞、滻、豐、鎬、澇、潏，上林賦所謂『八川分流』」。"}]},{"id":"a141","section":"司馬相如列傳第五十七","anchor":"入涇渭；酆鄗潦潏，紆餘委蛇，經營乎其內。蕩蕩兮八川分流，相背而異態。","notes":[{"source":"集解","text":"郭璞曰：「八川名在上。」"}]},{"id":"a142","section":"司馬相如列傳第五十七","anchor":"川分流，相背而異態。東西南北，馳騖往來，出乎椒丘之闕，行乎洲淤之浦，","notes":[{"source":"集解","text":"郭璞曰：「椒丘，丘名，言有巖闕也，見楚辭。淤亦洲名，蜀人云，見方言。」"},{"source":"索隱","text":"服虔云：「丘名，楚詞曰『馳椒丘且焉止息』也。」案：兩山俱起，象雙闕。如淳云「丘多椒也」。"}]},{"id":"a143","section":"司馬相如列傳第五十七","anchor":"異態。東西南北，馳騖往來，出乎椒丘之闕，行乎洲淤之浦，徑乎桂林之中，","notes":[{"source":"集解","text":"郭璞曰：「桂林，林名也，見南海經也。」"}]},{"id":"a144","section":"司馬相如列傳第五十七","anchor":"，馳騖往來，出乎椒丘之闕，行乎洲淤之浦，徑乎桂林之中，過乎泱莽之野。","notes":[{"source":"集解","text":"《漢書音義》曰：「《山海經》所謂大荒之野。」"}]},{"id":"a145","section":"司馬相如列傳第五十七","anchor":"之闕，行乎洲淤之浦，徑乎桂林之中，過乎泱莽之野。汨乎渾流，順阿而下，","notes":[{"source":"集解","text":"郭璞曰：「阿，大陵。」"}]},{"id":"a146","section":"司馬相如列傳第五十七","anchor":"之中，過乎泱莽之野。汨乎渾流，順阿而下，赴隘陝之口。觸穹石，激堆埼，","notes":[{"source":"集解","text":"郭璞曰：「穹隆，大石貌。堆，沙堆。埼，曲岸頭，音祁。」"},{"source":"索隱","text":"郭璞曰：「堆，沙堆；埼，曲岸頭也。」"}]},{"id":"a147","section":"司馬相如列傳第五十七","anchor":"汨乎渾流，順阿而下，赴隘陝之口。觸穹石，激堆埼，沸乎暴怒，洶涌滂㵒，","notes":[{"source":"集解","text":"洶音許勇反。涌音勇。滂音浦橫反。㵒音浦拜反。"},{"source":"索隱","text":"洶湧澎湃。司馬彪云：「洶湧，跳起貌。澎湃，相戾也。」湧，或作「容」。澎，或作「滂」。"}]},{"id":"a148","section":"司馬相如列傳第五十七","anchor":"順阿而下，赴隘陝之口。觸穹石，激堆埼，沸乎暴怒，洶涌滂㵒，滭浡滵汩，","notes":[{"source":"索隱","text":"司馬彪云：「滭沸，盛貌。滵汩，去疾也。」"},{"source":"正義","text":"畢渤密三音。汨，于筆反。"}]},{"id":"a149","section":"司馬相如列傳第五十七","anchor":"赴隘陝之口。觸穹石，激堆埼，沸乎暴怒，洶涌滂㵒，滭浡滵汩，湢測泌瀄，","notes":[{"source":"集解","text":"郭璞曰：「逼側筆櫛四音。」"},{"source":"索隱","text":"司馬彪云：「湢測，相迫也。泌瀄，相楔也。」郭璞云：「逼側筆櫛四音。」"}]},{"id":"a150","section":"司馬相如列傳第五十七","anchor":"激堆埼，沸乎暴怒，洶涌滂㵒，滭浡滵汩，湢測泌瀄，橫流逆折，轉騰潎洌，","notes":[{"source":"索隱","text":"蘇林曰：「流輕疾也。」"}]},{"id":"a151","section":"司馬相如列傳第五十七","anchor":"乎暴怒，洶涌滂㵒，滭浡滵汩，湢測泌瀄，橫流逆折，轉騰潎洌，澎濞沆瀣，","notes":[{"source":"索隱","text":"滂濞沆溉。溉，亦作「瀣」。司馬彪云：「滂濞，水流聲也。沆溉，徐流。」郭璞云：「鼓怒鬱鯁之皃也。」"},{"source":"正義","text":"澎，普彭反。濞，普祕反。沆，胡朗反。溉，胡代反。"}]},{"id":"a152","section":"司馬相如列傳第五十七","anchor":"涌滂㵒，滭浡滵汩，湢測泌瀄，橫流逆折，轉騰潎洌，澎濞沆瀣，穹隆雲撓，","notes":[{"source":"索隱","text":"穹崇雲橈。服虔云：「水旋還作泉也。」郭璞云：「水隴起回窳也。」"}]},{"id":"a153","section":"司馬相如列傳第五十七","anchor":"浡滵汩，湢測泌瀄，橫流逆折，轉騰潎洌，澎濞沆瀣，穹隆雲撓，蜿灗膠戾，","notes":[{"source":"索隱","text":"司馬彪云：「蜿灗，展轉也。膠戾，邪屈也。」音婉善交戾四音也。"},{"source":"正義","text":"蜿音婉。蟬音善。"}]},{"id":"a154","section":"司馬相如列傳第五十七","anchor":"測泌瀄，橫流逆折，轉騰潎洌，澎濞沆瀣，穹隆雲撓，蜿灗膠戾，踰波趨浥，","notes":[{"source":"集解","text":"徐廣曰：「烏狹反。」"},{"source":"索隱","text":"隃波趨浥。司馬彪云：「隃波，後陵前也。趨浥，輸于深泉也。」浥音焉浹反。"}]},{"id":"a155","section":"司馬相如列傳第五十七","anchor":"流逆折，轉騰潎洌，澎濞沆瀣，穹隆雲撓，蜿灗膠戾，踰波趨浥，莅莅下瀨，","notes":[{"source":"索隱","text":"司馬彪云：「莅莅，水聲也。」音利。"}]},{"id":"a156","section":"司馬相如列傳第五十七","anchor":"騰潎洌，澎濞沆瀣，穹隆雲撓，蜿灗膠戾，踰波趨浥，莅莅下瀨，批壧衝壅，","notes":[{"source":"正義","text":"批，白結反。壧，巖。司馬彪云：「批，反擊也。壅，曲隈也。」"}]},{"id":"a157","section":"司馬相如列傳第五十七","anchor":"濞沆瀣，穹隆雲撓，蜿灗膠戾，踰波趨浥，莅莅下瀨，批壧衝壅，犇揚滯沛，","notes":[{"source":"索隱","text":"滯沛，郭璞云「水洒散皃」。滯音丑制反。"}]},{"id":"a158","section":"司馬相如列傳第五十七","anchor":"隆雲撓，蜿灗膠戾，踰波趨浥，莅莅下瀨，批壧衝壅，犇揚滯沛，臨坻注壑，","notes":[{"source":"正義","text":"坻音遟。坻，水中沙微起出水者也。《爾雅》云「小沚曰坻」。壑，墟也。"}]},{"id":"a159","section":"司馬相如列傳第五十七","anchor":"撓，蜿灗膠戾，踰波趨浥，莅莅下瀨，批壧衝壅，犇揚滯沛，臨坻注壑，瀺灂","notes":[{"source":"索隱","text":"上音士湛反，下音士卓反。說文云「水小聲也」。"}]},{"id":"a160","section":"司馬相如列傳第五十七","anchor":"灗膠戾，踰波趨浥，莅莅下瀨，批壧衝壅，犇揚滯沛，臨坻注壑，瀺灂霣墜，","notes":[{"source":"正義","text":"霣音隕。隧，直類反。"}]},{"id":"a161","section":"司馬相如列傳第五十七","anchor":"戾，踰波趨浥，莅莅下瀨，批壧衝壅，犇揚滯沛，臨坻注壑，瀺灂霣墜，湛湛","notes":[{"source":"集解","text":"徐廣曰：「湛音沈。」"}]},{"id":"a162","section":"司馬相如列傳第五十七","anchor":"莅下瀨，批壧衝壅，犇揚滯沛，臨坻注壑，瀺灂霣墜，湛湛隱隱，砰磅訇礚，","notes":[{"source":"正義","text":"砰，披萌反。磅，蒲黃反。訇，呼宏反。礚，苦蓋反。皆水流鼓怒之聲也。"}]},{"id":"a163","section":"司馬相如列傳第五十七","anchor":"揚滯沛，臨坻注壑，瀺灂霣墜，湛湛隱隱，砰磅訇礚，潏潏淈淈，湁潗鼎沸，","notes":[{"source":"集解","text":"郭璞曰：「湁音勑立反。潗音緝。」"},{"source":"索隱","text":"潏淈湁潗。郭璞云，皆水微轉細涌貌。潏淈音決骨。湁音勑力反。潗音緝。廣雅云「淈淈，決流也」。周成襍字云「湁潗，水沸之皃也」。"}]},{"id":"a164","section":"司馬相如列傳第五十七","anchor":"坻注壑，瀺灂霣墜，湛湛隱隱，砰磅訇礚，潏潏淈淈，湁潗鼎沸，馳波跳沫，","notes":[{"source":"集解","text":"徐廣：「一云『吸呷』。」"}]},{"id":"a165","section":"司馬相如列傳第五十七","anchor":"灂霣墜，湛湛隱隱，砰磅訇礚，潏潏淈淈，湁潗鼎沸，馳波跳沫，汩㴔漂疾，","notes":[{"source":"索隱","text":"㴔，晉灼曰「華給反」，郭璞云「許立反」。汩㴔，急轉皃也。"}]},{"id":"a166","section":"司馬相如列傳第五十七","anchor":"湛隱隱，砰磅訇礚，潏潏淈淈，湁潗鼎沸，馳波跳沫，汩㴔漂疾，悠遠長懷，","notes":[{"source":"正義","text":"放散貌也。"}]},{"id":"a167","section":"司馬相如列傳第五十七","anchor":"沸，馳波跳沫，汩㴔漂疾，悠遠長懷，寂漻無聲，肆乎永歸。然後灝溔潢漾，","notes":[{"source":"正義","text":"晃養二音。郭云「皆水無涯際也」。"}]},{"id":"a168","section":"司馬相如列傳第五十七","anchor":"疾，悠遠長懷，寂漻無聲，肆乎永歸。然後灝溔潢漾，安翔徐徊，翯乎滈滈，","notes":[{"source":"索隱","text":"翯音鶴。滈音鎬。詩曰「白鳥翯翯」。郭璞云「水白光皃」。翯音皛，滈音昊也。"}]},{"id":"a169","section":"司馬相如列傳第五十七","anchor":"懷，寂漻無聲，肆乎永歸。然後灝溔潢漾，安翔徐徊，翯乎滈滈，東注大湖，","notes":[{"source":"正義","text":"太湖在蘇州西南。"}]},{"id":"a170","section":"司馬相如列傳第五十七","anchor":"後灝溔潢漾，安翔徐徊，翯乎滈滈，東注大湖，衍溢陂池。於是乎蛟龍赤螭，","notes":[{"source":"索隱","text":"文穎曰：「龍子曰螭。」張揖云：「雌龍也。」"},{"source":"正義","text":"螭，丑知反。文穎云「龍子爲螭」，張揖曰「雌龍也」，二說皆非。廣雅云：「有角曰虬，無角曰螭。」案：虬螭皆龍類而非龍。"}]},{"id":"a171","section":"司馬相如列傳第五十七","anchor":"，安翔徐徊，翯乎滈滈，東注大湖，衍溢陂池。於是乎蛟龍赤螭，䱍䲛螹離，","notes":[{"source":"集解","text":"徐廣曰：「螹音漸。」駰案：郭璞曰「䱍䲛，鮪也。」音亙瞢。螹離未聞。"},{"source":"正義","text":"䱍，古鄧反。䲛，末鄧反。李奇云：「周洛曰鮪，蜀曰䱍䲛。出鞏山穴中，三月遡河上，能度龍門之限，則爲龍矣。」"}]},{"id":"a172","section":"司馬相如列傳第五十七","anchor":"，翯乎滈滈，東注大湖，衍溢陂池。於是乎蛟龍赤螭，䱍䲛螹離，鰅鱅鰬魠，","notes":[{"source":"集解","text":"徐廣曰：「鰅音娛匈反。皮有文，出樂浪。鰬音虔。魠音託，哆口魚。」駰案：郭璞曰「鱅似鰱而黑」。《漢書音義》曰「鰬似鯉而大」也。"}]},{"id":"a173","section":"司馬相如列傳第五十七","anchor":"，東注大湖，衍溢陂池。於是乎蛟龍赤螭，䱍䲛螹離，鰅鱅鰬魠，禺禺鱋魶，","notes":[{"source":"集解","text":"徐廣曰：「禺禺，魚牛也。鱋，一作『魼』，音榻。魶音納，一作『鰨』。」駰案：《漢書音義》曰「魼，比目魚也。魶，鯷魚」。"}]},{"id":"a174","section":"司馬相如列傳第五十七","anchor":"注大湖，衍溢陂池。於是乎蛟龍赤螭，䱍䲛螹離，鰅鱅鰬魠，禺禺鱋魶，揵鰭","notes":[{"source":"正義","text":"揵音乾。鰭音祁。揵，舉也。鰭者，魚背上鬣也。"}]},{"id":"a175","section":"司馬相如列傳第五十七","anchor":"擢尾，振鱗奮翼，潛處于深巖；魚鼈讙聲，萬物眾夥，明月珠子，玓瓅江靡，","notes":[{"source":"集解","text":"郭璞曰：「靡，崖也。」"},{"source":"索隱","text":"旳皪江靡。應劭曰：「靡，邊也。明月珠子生於江中，其光耀乃照于江邊。」張揖曰：「靡，涯也。」郭璞曰：「旳皪，照也。」"}]},{"id":"a176","section":"司馬相如列傳第五十七","anchor":"奮翼，潛處于深巖；魚鼈讙聲，萬物眾夥，明月珠子，玓瓅江靡，蜀石黃碝，","notes":[{"source":"集解","text":"郭璞曰：「碝石黃色也。」"}]},{"id":"a177","section":"司馬相如列傳第五十七","anchor":"于深巖；魚鼈讙聲，萬物眾夥，明月珠子，玓瓅江靡，蜀石黃碝，水玉磊砢，","notes":[{"source":"集解","text":"郭璞曰：「水玉，水精也。」"}]},{"id":"a178","section":"司馬相如列傳第五十七","anchor":"黃碝，水玉磊砢，磷磷爛爛，采色㵆旰，叢積乎其中。鴻鵠鷫鴇，𪀁䳘鸀𩿱，","notes":[{"source":"集解","text":"郭璞曰：「鷫，鷫霜。𪈺鳿，似鴨而大，長頸赤目，紫紺色也。」"},{"source":"索隱","text":"鴇音保。郭璞云：「鴇似鴈，無後指。」毛詩鳥獸疏云：「鴇似鴈而虎文也。」"},{"source":"正義","text":"𪈺鳿，燭玉二音。郭云：「似鴨而大，長頸赤目，紫紺色。辟水毒，生子在深谷澗中。若時有雨，鳴。雌者生子，善鬬。江東呼爲燭玉。」"}]},{"id":"a179","section":"司馬相如列傳第五十七","anchor":"，水玉磊砢，磷磷爛爛，采色㵆旰，叢積乎其中。鴻鵠鷫鴇，𪀁䳘鸀𩿱，𪁉𪂴","notes":[{"source":"正義","text":"郭云：「𪁉𪂴似鳧而腳高，有毛冠，辟火災。」"}]},{"id":"a180","section":"司馬相如列傳第五十七","anchor":"磊砢，磷磷爛爛，采色㵆旰，叢積乎其中。鴻鵠鷫鴇，𪀁䳘鸀𩿱，𪁉𪂴䴋目，","notes":[{"source":"集解","text":"徐廣曰：「䴋音環。」"},{"source":"索隱","text":"䴉目。郭璞云未詳。小顏云：「荊郢閒有水鳥，大如鷺而短尾，其色紅白，深目，目旁毛長而旋，此其旋目乎？」䴉音旋。"}]},{"id":"a181","section":"司馬相如列傳第五十七","anchor":"爛爛，采色㵆旰，叢積乎其中。鴻鵠鷫鴇，𪀁䳘鸀𩿱，𪁉𪂴䴋目，煩鶩鷛𪆫，","notes":[{"source":"集解","text":"徐廣曰：「煩鶩，一作『番䴌』。鷛音容。」駰案：《漢書音義》曰「煩鶩，鳧也。鷛𪆫似鶩，灰色而雞足」。"},{"source":"索隱","text":"煩鶩鷛渠。郭璞云：「煩鶩，鴨屬。鷛渠，一名章渠也。」"}]},{"id":"a182","section":"司馬相如列傳第五十七","anchor":"㵆旰，叢積乎其中。鴻鵠鷫鴇，𪀁䳘鸀𩿱，𪁉𪂴䴋目，煩鶩鷛𪆫，𪇅䳄鵁鸕，","notes":[{"source":"集解","text":"徐廣曰：「𪇅音斟。水鳥也。䳄音斯。鳼音火交反。」駰案：《漢書音義》曰「𪇅䳄，蒼黑色」。郭璞曰「鵁，魚鵁也，腳近尾。鸕，鸕鷀也」。"},{"source":"索隱","text":"葴鴜。張揖云「葴鴜似魚虎而蒼黑」。鄒誕本作「鴟䳄」也。"}]},{"id":"a183","section":"司馬相如列傳第五十七","anchor":"鷫鴇，𪀁䳘鸀𩿱，𪁉𪂴䴋目，煩鶩鷛𪆫，𪇅䳄鵁鸕，羣浮乎其上。汎淫泛濫，","notes":[{"source":"索隱","text":"郭璞云：「皆鳥任風波自縱漂皃。」汎音馮。泛音芳劍反。廣雅云：「汎汎，氾氾，浮也。」"}]},{"id":"a184","section":"司馬相如列傳第五十七","anchor":"鷛𪆫，𪇅䳄鵁鸕，羣浮乎其上。汎淫泛濫，隨風澹淡，與波搖蕩，掩薄草渚，","notes":[{"source":"索隱","text":"張揖云：「掩，覆也。草叢生曰薄也。」"},{"source":"正義","text":"掩，覆也。薄，依也。言或依草渚而遊戲也。"}]},{"id":"a185","section":"司馬相如列傳第五十七","anchor":"，𪇅䳄鵁鸕，羣浮乎其上。汎淫泛濫，隨風澹淡，與波搖蕩，掩薄草渚，唼喋","notes":[{"source":"正義","text":"唼，疏甲反。喋，丈甲反。鳥食之聲也。"}]},{"id":"a186","section":"司馬相如列傳第五十七","anchor":"鵁鸕，羣浮乎其上。汎淫泛濫，隨風澹淡，與波搖蕩，掩薄草渚，唼喋菁藻，","notes":[{"source":"集解","text":"郭璞曰：「菁，水草。《呂氏春秋》曰『太湖之菁』也。」"},{"source":"索隱","text":"郭璞云：「菁，水草；藻，藂也。《呂氏春秋》曰『太湖之菁』。《左傳》云『蘋蘩蘊藻』。蘊即聚。」"}]},{"id":"a187","section":"司馬相如列傳第五十七","anchor":"「於是乎崇山巃嵸，崔巍嵯峨，","notes":[{"source":"正義","text":"巃，力孔反。嵸，子孔反。崔，在回反。巍，五回反。郭云：「皆峻貌。」"}]},{"id":"a188","section":"司馬相如列傳第五十七","anchor":"「於是乎崇山巃嵸，崔巍嵯峨，深林鉅木，嶄巖嵾嵯，","notes":[{"source":"正義","text":"嶄音咸，又仕銜反。嵾音楚林反。嵳楚宜反。顏云：「嶄巖，尖銳貌。嵾嵳，不齊也。」"}]},{"id":"a189","section":"司馬相如列傳第五十七","anchor":"於是乎崇山巃嵸，崔巍嵯峨，深林鉅木，嶄巖嵾嵯，九嵏、嶻嶭，南山峨峨，","notes":[{"source":"集解","text":"《漢書音義》曰：「九嵏山在左馮翊谷口縣西。嶻嶭山在池陽縣北。」"},{"source":"正義","text":"嵏，子公反。嶻，才切反。嶭，五結反。"}]},{"id":"a190","section":"司馬相如列傳第五十七","anchor":"乎崇山巃嵸，崔巍嵯峨，深林鉅木，嶄巖嵾嵯，九嵏、嶻嶭，南山峨峨，巖陁","notes":[{"source":"集解","text":"音遟。"}]},{"id":"a191","section":"司馬相如列傳第五十七","anchor":"嵯峨，深林鉅木，嶄巖嵾嵯，九嵏、嶻嶭，南山峨峨，巖陁甗錡，嶊崣崛崎，","notes":[{"source":"集解","text":"郭璞曰：「陁，崖際。甗音魚晚反。錡音蟻。嶊音作罪反。」"},{"source":"索隱","text":"嶊崣崛崎，郭璞云：「皆崇屈窳折皃。嶊音作罪反。崣音委。崛音掘。崎音倚。」"}]},{"id":"a192","section":"司馬相如列傳第五十七","anchor":"鉅木，嶄巖嵾嵯，九嵏、嶻嶭，南山峨峨，巖陁甗錡，嶊崣崛崎，振谿通谷，","notes":[{"source":"索隱","text":"張揖云：「振，拔也。水注川曰溪，注溪曰谷。」郭璞曰：「振猶灑也。」"}]},{"id":"a193","section":"司馬相如列傳第五十七","anchor":"嵾嵯，九嵏、嶻嶭，南山峨峨，巖陁甗錡，嶊崣崛崎，振谿通谷，蹇產溝瀆，","notes":[{"source":"集解","text":"《漢書音義》曰：「蹇產，屈折也。」"}]},{"id":"a194","section":"司馬相如列傳第五十七","anchor":"、嶻嶭，南山峨峨，巖陁甗錡，嶊崣崛崎，振谿通谷，蹇產溝瀆，谽呀豁閜，","notes":[{"source":"集解","text":"郭璞曰：「皆澗谷之形容也。谽音呼含反。呀音呼加反。閜音呼下反。」"},{"source":"索隱","text":"𧮰呀豁閜。司馬彪云：「𧮰呀，大皃。豁閜，空虛也。」"}]},{"id":"a195","section":"司馬相如列傳第五十七","anchor":"山峨峨，巖陁甗錡，嶊崣崛崎，振谿通谷，蹇產溝瀆，谽呀豁閜，𨸏陵別島，","notes":[{"source":"正義","text":"高平曰陸，大陸曰阜，大阜曰陵，水中山曰島。"}]},{"id":"a196","section":"司馬相如列傳第五十七","anchor":"陁甗錡，嶊崣崛崎，振谿通谷，蹇產溝瀆，谽呀豁閜，𨸏陵別島，崴磈嵔瘣，","notes":[{"source":"正義","text":"崴，於鬼反。磈，魚鬼反。嵔，烏罪反。瘣，胡罪反。皆高峻貌。"}]},{"id":"a197","section":"司馬相如列傳第五十七","anchor":"崣崛崎，振谿通谷，蹇產溝瀆，谽呀豁閜，𨸏陵別島，崴磈嵔瘣，丘虛崛𡾋，","notes":[{"source":"正義","text":"虛音墟。崛，口忽反，又口罪反。𡾋，力罪反。皆堆壟不平貌。"}]},{"id":"a198","section":"司馬相如列傳第五十七","anchor":"谿通谷，蹇產溝瀆，谽呀豁閜，𨸏陵別島，崴磈嵔瘣，丘虛崛𡾋，隱轔鬱𡾊，","notes":[{"source":"正義","text":"𡾊音律。郭云：「皆其形勢也。」"}]},{"id":"a199","section":"司馬相如列傳第五十七","anchor":"產溝瀆，谽呀豁閜，𨸏陵別島，崴磈嵔瘣，丘虛崛𡾋，隱轔鬱𡾊，登降施靡，","notes":[{"source":"正義","text":"郭云：「施靡猶連延。」"}]},{"id":"a200","section":"司馬相如列傳第五十七","anchor":"呀豁閜，𨸏陵別島，崴磈嵔瘣，丘虛崛𡾋，隱轔鬱𡾊，登降施靡，陂池貏豸，","notes":[{"source":"集解","text":"郭璞曰：「貏音衣被。豸音蟲豸也。」"},{"source":"索隱","text":"郭璞曰：「陂池，旁穨兒。陂音皮。貏音『衣被』之『被』。」"}]},{"id":"a201","section":"司馬相如列傳第五十七","anchor":"陵別島，崴磈嵔瘣，丘虛崛𡾋，隱轔鬱𡾊，登降施靡，陂池貏豸，沇溶淫鬻，","notes":[{"source":"索隱","text":"郭璞云：「游激淖衍兒。」"},{"source":"正義","text":"溶音容。鬻音育。張云：「水流谿谷之閒。」"}]},{"id":"a202","section":"司馬相如列傳第五十七","anchor":"磈嵔瘣，丘虛崛𡾋，隱轔鬱𡾊，登降施靡，陂池貏豸，沇溶淫鬻，散渙夷陸，","notes":[{"source":"索隱","text":"司馬彪曰：「平地。」"}]},{"id":"a203","section":"司馬相如列傳第五十七","anchor":"轔鬱𡾊，登降施靡，陂池貏豸，沇溶淫鬻，散渙夷陸，亭皋千里，靡不被築。","notes":[{"source":"集解","text":"郭璞曰：「言爲亭候於皋隰，皆築地令平，賈山所謂『隱以金椎』也。」"}]},{"id":"a204","section":"司馬相如列傳第五十七","anchor":"降施靡，陂池貏豸，沇溶淫鬻，散渙夷陸，亭皋千里，靡不被築。掩以綠蕙，","notes":[{"source":"正義","text":"張云：「綠，王蒭蒭也。蕙，薰草也。」顏云：「綠蕙，言蕙草色綠耳，非王蒭蒭也。」《爾雅》云菉一名王蒭。"}]},{"id":"a205","section":"司馬相如列傳第五十七","anchor":"溶淫鬻，散渙夷陸，亭皋千里，靡不被築。掩以綠蕙，被以江離，糅以蘪蕪，","notes":[{"source":"正義","text":"糅，女又反。"}]},{"id":"a206","section":"司馬相如列傳第五十七","anchor":"渙夷陸，亭皋千里，靡不被築。掩以綠蕙，被以江離，糅以蘪蕪，雜以流夷。","notes":[{"source":"集解","text":"《漢書音義》曰：「流夷，新夷也。」"}]},{"id":"a207","section":"司馬相如列傳第五十七","anchor":"亭皋千里，靡不被築。掩以綠蕙，被以江離，糅以蘪蕪，雜以流夷。尃結縷，","notes":[{"source":"集解","text":"徐廣曰：「尃，古『布』字，一作『布』。」駰案：《漢書音義》曰「結縷似白茅，蔓聯而生，布種之者」。"}]},{"id":"a208","section":"司馬相如列傳第五十七","anchor":"，靡不被築。掩以綠蕙，被以江離，糅以蘪蕪，雜以流夷。尃結縷，欑戾莎，","notes":[{"source":"集解","text":"徐廣曰：「草，可染紫。」"}]},{"id":"a209","section":"司馬相如列傳第五十七","anchor":"，被以江離，糅以蘪蕪，雜以流夷。尃結縷，欑戾莎，揭車衡蘭，槀本射干，","notes":[{"source":"集解","text":"徐廣曰：「揭音桀。」駰案：郭璞曰「揭車，一名乞輿。槀本，槀茇；射干，十月生：皆香草」。"},{"source":"索隱","text":"槀本，案桐君藥錄云「苗似穹窮也」。"}]},{"id":"a210","section":"司馬相如列傳第五十七","anchor":"以江離，糅以蘪蕪，雜以流夷。尃結縷，欑戾莎，揭車衡蘭，槀本射干，茈薑","notes":[{"source":"索隱","text":"張揖云：「子薑也。」案：四人月令云「生薑謂之茈薑，音紫」。"}]},{"id":"a211","section":"司馬相如列傳第五十七","anchor":"，糅以蘪蕪，雜以流夷。尃結縷，欑戾莎，揭車衡蘭，槀本射干，茈薑蘘荷，","notes":[{"source":"正義","text":"蘘，人羊反。柯根旁生笋，若芙蓉，可以爲菹，又治蠱毒也。"}]},{"id":"a212","section":"司馬相如列傳第五十七","anchor":"，雜以流夷。尃結縷，欑戾莎，揭車衡蘭，槀本射干，茈薑蘘荷，葴橙若蓀，","notes":[{"source":"集解","text":"郭璞曰：「葴，未詳。橙，柚。若蓀，香草也。」"},{"source":"索隱","text":"張揖云：「葴，持闕。」郭璞云：「橙，柚也。」姚氏以爲此前後皆草，非橙也。小顏云：「葴，寒漿也。持當爲『符』，符，鬼目也。」案：今讀者亦呼爲登，謂金登草也。張揖云：「蓀，香草。」姚氏云：「蓀草似昌蒲而無脊也，生溪澗中。蓀音孫。」"}]},{"id":"a213","section":"司馬相如列傳第五十七","anchor":"。尃結縷，欑戾莎，揭車衡蘭，槀本射干，茈薑蘘荷，葴橙若蓀，鮮枝黃礫，","notes":[{"source":"集解","text":"郭璞曰：「皆未詳。」"},{"source":"索隱","text":"鮮支黃礫。張揖云：「皆草也，未詳。」司馬彪云：「鮮支，支子。或云鮮支亦香草也。」小顏云「黃礫，黃㞕木」，恐非也。"}]},{"id":"a214","section":"司馬相如列傳第五十七","anchor":"欑戾莎，揭車衡蘭，槀本射干，茈薑蘘荷，葴橙若蓀，鮮枝黃礫，蔣芧青薠，","notes":[{"source":"集解","text":"徐廣曰：「芧音佇。」駰案：《漢書音義》曰「蔣，菰也。芧，三稜」。"},{"source":"索隱","text":"蔣，菰也。郭璞芧音佇。又云三稜芧。薠音煩。"}]},{"id":"a215","section":"司馬相如列傳第五十七","anchor":"枝黃礫，蔣芧青薠，布濩閎澤，延曼太原，麗靡廣衍，應風披靡，吐芳揚烈，","notes":[{"source":"集解","text":"郭璞曰：「香酷烈也。」"}]},{"id":"a216","section":"司馬相如列傳第五十七","anchor":"靡廣衍，應風披靡，吐芳揚烈，郁郁斐斐，眾香發越，肸蠁布寫，䁆瞹苾勃。","notes":[{"source":"正義","text":"䁆瞹，奄愛二音。皆芳香之盛也。《詩》云「苾苾芬芬」，氣也。"}]},{"id":"a217","section":"司馬相如列傳第五十七","anchor":"「於是乎周覽泛觀，瞋盼軋沕，","notes":[{"source":"集解","text":"徐廣曰：「瞋音丑人反。盼，一作『緡』。」駰案：郭璞曰「皆不可分貌」。"}]},{"id":"a218","section":"司馬相如列傳第五十七","anchor":"覽泛觀，瞋盼軋沕，芒芒恍忽，視之無端，察之無崖。日出東沼，入於西陂。","notes":[{"source":"索隱","text":"張揖云：「日朝出苑之東池，暮入于苑西陂中也。」"}]},{"id":"a219","section":"司馬相如列傳第五十七","anchor":"之無崖。日出東沼，入於西陂。其南則隆冬生長，踊水躍波；獸則𤛑旄獏犛，","notes":[{"source":"集解","text":"徐廣曰：「𤛑音容，獸類也。犛音貍，一音茅。」駰案：郭璞曰「旄，旄牛。獏似熊，庳腳銳頭。犛牛，黑色，出西南徼外也」。"},{"source":"索隱","text":"郭璞云：「𤛑，𤛑牛，領有肉堆，音容。」案：今之犎牛也。張揖云「旄，旄牛，狀如牛而四節生毛。獏，白豹也，似熊，庳腳銳頭，骨無髓，食銅鐵。音陌。犛音貍，又音茅，或以爲貓牛。犛牛黑色，出西南徼外，毛可爲拂是也」。"}]},{"id":"a220","section":"司馬相如列傳第五十七","anchor":"出東沼，入於西陂。其南則隆冬生長，踊水躍波；獸則𤛑旄獏犛，沈牛麈麋，","notes":[{"source":"集解","text":"《漢書音義》曰：「沈牛，水牛也。」"},{"source":"正義","text":"麈似鹿而大。案：麋似水牛。"}]},{"id":"a221","section":"司馬相如列傳第五十七","anchor":"於西陂。其南則隆冬生長，踊水躍波；獸則𤛑旄獏犛，沈牛麈麋，赤首圜題，","notes":[{"source":"集解","text":"郭璞曰：「題，額也，所未詳。」"}]},{"id":"a222","section":"司馬相如列傳第五十七","anchor":"南則隆冬生長，踊水躍波；獸則𤛑旄獏犛，沈牛麈麋，赤首圜題，窮奇象犀。","notes":[{"source":"集解","text":"《漢書音義》曰：「窮奇狀如牛而蝟毛，其音如嗥狗，食人也。」"},{"source":"索隱","text":"張揖云：「窮奇狀如牛而蝟毛，其音如嗥狗，食人。」郭璞云：「象，大獸，長鼻，牙長一丈。犀，頭似豬，庳腳，一角在頭也。」"}]},{"id":"a223","section":"司馬相如列傳第五十七","anchor":"旄獏犛，沈牛麈麋，赤首圜題，窮奇象犀。其北則盛夏含凍裂地，涉冰揭河；","notes":[{"source":"集解","text":"郭璞曰：「言水漫凍不解，地坼裂也。揭，褰衣。」"}]},{"id":"a224","section":"司馬相如列傳第五十七","anchor":"沈牛麈麋，赤首圜題，窮奇象犀。其北則盛夏含凍裂地，涉冰揭河；獸則麒麟","notes":[{"source":"索隱","text":"張揖曰：「雄曰麒，雌曰麟。其狀麇身，牛尾，狼蹄，一角。」郭璞云：「麒似麟而無角。」毛詩疏云：「麟黃色，角端有肉。」京房傳云：「有五采，腹下黃色也。」"}]},{"id":"a225","section":"司馬相如列傳第五十七","anchor":"麋，赤首圜題，窮奇象犀。其北則盛夏含凍裂地，涉冰揭河；獸則麒麟角𧤗，","notes":[{"source":"集解","text":"郭璞曰：「角𧤗，音端，似豬，角在鼻上，堪作弓。李陵嘗以此弓十張遺蘇武也。」"},{"source":"索隱","text":"張揖云：「音端。角𧤗似牛。」郭璞云：「似豬，角在鼻上。毛詩疏云可以爲弓。李陵曾以此弓遺蘇武。」"}]},{"id":"a226","section":"司馬相如列傳第五十七","anchor":"盛夏含凍裂地，涉冰揭河；獸則麒麟角𧤗，騊駼橐駞，蛩蛩驒騱，駃騠驢騾。","notes":[{"source":"正義","text":"騊駼，桃徒二音。橐音託。駝，徒河反。蛩音其恭反。驒騱，顛奚二音。駃騠音決啼。"}]},{"id":"a227","section":"司馬相如列傳第五十七","anchor":"「於是乎離宮別館，彌山跨谷，","notes":[{"source":"正義","text":"彌，滿也。跨猶騎也。言宮館滿山，又跨谿谷也。"}]},{"id":"a228","section":"司馬相如列傳第五十七","anchor":"「於是乎離宮別館，彌山跨谷，高廊四注，重坐曲閣，","notes":[{"source":"集解","text":"郭璞曰：「重坐，重軒也。曲閣，閣道曲也。」"}]},{"id":"a229","section":"司馬相如列傳第五十七","anchor":"「於是乎離宮別館，彌山跨谷，高廊四注，重坐曲閣，華榱璧璫，","notes":[{"source":"索隱","text":"韋昭曰：「裁玉爲璧，以當榱頭。」司馬彪曰：「以璧爲瓦當。」"}]},{"id":"a230","section":"司馬相如列傳第五十七","anchor":"山跨谷，高廊四注，重坐曲閣，華榱璧璫，輦道纚屬，步櫩周流，長途中宿。","notes":[{"source":"集解","text":"郭璞曰：「途，樓閣閒陛道。中宿言長遠也。」"}]},{"id":"a231","section":"司馬相如列傳第五十七","anchor":"榱璧璫，輦道纚屬，步櫩周流，長途中宿。夷嵏築堂，纍臺增成，巖穾洞房，","notes":[{"source":"集解","text":"郭璞曰：「嵏，山名。平之以安堂其上。成亦重也。《周禮》曰『爲壇三成』。在巖穴底爲室，潛通臺上者。」"},{"source":"索隱","text":"服虔云：「平此山以爲堂。」如淳云：「嵏，山名也。」張揖云：「重累而成之，故曰增成。《禮》曰『爲壇三成』也。」郭璞曰：「言在巖穾底爲室，潛通臺上。」穾音一弔反，釋名以爲穾，幽也。楚辭云「冬有穾厦夏屋寒」，王逸以爲複室也。"}]},{"id":"a232","section":"司馬相如列傳第五十七","anchor":"，巖穾洞房，俛杳眇而無見，仰攀橑而捫天，奔星更於閨闥，宛虹拖於楯軒。","notes":[{"source":"集解","text":"徐廣曰：「楯音食尹反。」"},{"source":"正義","text":"拖音徒我反。顏云：「宛虹，屈曲之虹。拖謂中加於上也。楯，軒之闌板也。言室宇之高，故星虹得經加之。"}]},{"id":"a233","section":"司馬相如列傳第五十七","anchor":"眇而無見，仰攀橑而捫天，奔星更於閨闥，宛虹拖於楯軒。青虯蚴蟉於東箱，","notes":[{"source":"正義","text":"蚴，一糺反。蟉，力糺反。"}]},{"id":"a234","section":"司馬相如列傳第五十七","anchor":"而捫天，奔星更於閨闥，宛虹拖於楯軒。青虯蚴蟉於東箱，象輿婉蟬於西清，","notes":[{"source":"集解","text":"《漢書音義》曰：「山出象輿，瑞應車也。」郭璞曰：「西清，西箱清淨地也。」"},{"source":"正義","text":"婉蟬，宛善二音。顏云：「蚴蟉婉蟬，皆行動之貌也。」"}]},{"id":"a235","section":"司馬相如列傳第五十七","anchor":"天，奔星更於閨闥，宛虹拖於楯軒。青虯蚴蟉於東箱，象輿婉蟬於西清，靈圉","notes":[{"source":"集解","text":"郭璞曰：「靈圉，淳圉，仙人名也。」"},{"source":"索隱","text":"張揖云：「眾仙號。」《淮南子》云「騎飛龍，從淳圉」，許慎曰「淳圉，仙人也」。"}]},{"id":"a236","section":"司馬相如列傳第五十七","anchor":"闥，宛虹拖於楯軒。青虯蚴蟉於東箱，象輿婉蟬於西清，靈圉燕於閒觀，偓佺","notes":[{"source":"集解","text":"《漢書音義》曰：「偓佺，仙人名也。」"},{"source":"索隱","text":"韋昭曰：「古仙人，姓偓。」《列仙傳》云：「槐里採藥父也，食松，形體生毛數寸，方眼，能行追走馬也。」"}]},{"id":"a237","section":"司馬相如列傳第五十七","anchor":"軒。青虯蚴蟉於東箱，象輿婉蟬於西清，靈圉燕於閒觀，偓佺之倫暴於南榮，","notes":[{"source":"索隱","text":"應劭云「屋檐兩頭如翼也」。故鄭玄云「榮，屋翼也」。七誘云「飛榮似鳥舒翼」是也。暴，偃臥日中也。"}]},{"id":"a238","section":"司馬相如列傳第五十七","anchor":"圉燕於閒觀，偓佺之倫暴於南榮，醴泉涌於清室，通川過乎中庭。槃石裖崖，","notes":[{"source":"集解","text":"徐廣曰：「裖音振。」"},{"source":"索隱","text":"盤石裖厓。如淳曰：「裖音振，盛多也。」李奇曰：「裖，整也，整頓池外之厓，音之忍反也。」"}]},{"id":"a239","section":"司馬相如列傳第五十七","anchor":"暴於南榮，醴泉涌於清室，通川過乎中庭。槃石裖崖，嶔巖倚傾，嵯峨磼礏，","notes":[{"source":"集解","text":"徐廣曰：「峩，一作『池』。磼音雜。礏音五合反。」"},{"source":"索隱","text":"磼礏，埤蒼云「高皃也」。上士劫反，下魚揖反。又《字林》音磼，才帀反。礏，五帀反。"}]},{"id":"a240","section":"司馬相如列傳第五十七","anchor":"醴泉涌於清室，通川過乎中庭。槃石裖崖，嶔巖倚傾，嵯峨磼礏，刻削崢嶸，","notes":[{"source":"正義","text":"郭云：「言自然若彫刻也。」"}]},{"id":"a241","section":"司馬相如列傳第五十七","anchor":"乎中庭。槃石裖崖，嶔巖倚傾，嵯峨磼礏，刻削崢嶸，玫瑰碧琳，珊瑚叢生，","notes":[{"source":"正義","text":"郭云：「珊瑚生水底石邊，大者樹高三尺餘，枝格交錯，無有葉。」"}]},{"id":"a242","section":"司馬相如列傳第五十七","anchor":"石裖崖，嶔巖倚傾，嵯峨磼礏，刻削崢嶸，玫瑰碧琳，珊瑚叢生，瑉玉旁唐，","notes":[{"source":"索隱","text":"郭璞云：「旁唐言盤薄。」"}]},{"id":"a243","section":"司馬相如列傳第五十七","anchor":"巖倚傾，嵯峨磼礏，刻削崢嶸，玫瑰碧琳，珊瑚叢生，瑉玉旁唐，璸斒文鱗，","notes":[{"source":"集解","text":"徐廣曰：「璸音彬。斒音班。」"}]},{"id":"a244","section":"司馬相如列傳第五十七","anchor":"峨磼礏，刻削崢嶸，玫瑰碧琳，珊瑚叢生，瑉玉旁唐，璸斒文鱗，赤瑕駁犖，","notes":[{"source":"索隱","text":"赤瑕駮犖。說文云：「瑕，玉之小赤色。」張揖曰：「赤玉也。」司馬彪曰：「駮犖，采點也。犖音洛角反。」"}]},{"id":"a245","section":"司馬相如列傳第五十七","anchor":"削崢嶸，玫瑰碧琳，珊瑚叢生，瑉玉旁唐，璸斒文鱗，赤瑕駁犖，雜臿其閒，","notes":[{"source":"集解","text":"徐廣曰：「雜，一云『插』。臿，一云『遝』。」"}]},{"id":"a246","section":"司馬相如列傳第五十七","anchor":"瑚叢生，瑉玉旁唐，璸斒文鱗，赤瑕駁犖，雜臿其閒，垂綏琬琰，和氏出焉。","notes":[{"source":"集解","text":"徐廣曰：「垂綏，一作『朝采』。」駰案：郭璞曰「汲冢竹《書》曰『桀伐岷山，得女二人，曰琬曰琰。桀愛二女，斲其名于苕華之玉』。苕是琬，華是琰也」。"}]},{"id":"a247","section":"司馬相如列傳第五十七","anchor":"「於是乎盧橘夏孰，","notes":[{"source":"集解","text":"郭璞曰：「今蜀中有給客橙，似橘而非，若柚而芬香，冬夏華實相繼，或如彈丸，或如拳，通歲食之，即盧橘也。」"},{"source":"索隱","text":"應劭曰：「伊尹書『果之美者，箕山之東，青鳥之所，有盧橘，夏孰』。」晉灼曰：「此雖賦上林，博引異方珍奇，不係於一也。」案：廣州記云「盧橘皮厚，大小如甘，酢多，九月結實，正赤，明年二月更青黑，夏孰」。吳錄云「建安有橘，冬月樹上覆裹，明年夏色變青黑，其味甚甘美」。盧即黑是也。"}]},{"id":"a248","section":"司馬相如列傳第五十七","anchor":"「於是乎盧橘夏孰，黃甘橙楱，","notes":[{"source":"集解","text":"徐廣曰：「音湊，橘屬。」"}]},{"id":"a249","section":"司馬相如列傳第五十七","anchor":"「於是乎盧橘夏孰，黃甘橙楱，枇杷橪柿，","notes":[{"source":"集解","text":"徐廣曰：「橪音而善反，果也。」"},{"source":"索隱","text":"張揖曰：「橪，橪支，香草也。」韋昭曰：「橪音汝蕭反。」郭璞云：「橪支，木也。橪音烟。」徐廣曰：「橪，棗也，而善反。」說文曰：「橪，酸小棗也。」《淮南子》云：「伐橪棗以爲矜。」音勤也。"}]},{"id":"a250","section":"司馬相如列傳第五十七","anchor":"「於是乎盧橘夏孰，黃甘橙楱，枇杷橪柿，楟柰厚朴，","notes":[{"source":"集解","text":"徐廣曰：「楟音亭，山梨。」"},{"source":"索隱","text":"張揖云：「楟柰，山梨也。」司馬彪曰：「上黨謂之楟柰。」齊都賦云「楟柰㮈熟」也。厚朴，藥名。"}]},{"id":"a251","section":"司馬相如列傳第五十七","anchor":"「於是乎盧橘夏孰，黃甘橙楱，枇杷橪柿，楟柰厚朴，梬棗","notes":[{"source":"集解","text":"徐廣曰：「梬音弋井反。梬棗似柿。」"},{"source":"索隱","text":"上音弋井反。梬棗似柿也。"}]},{"id":"a252","section":"司馬相如列傳第五十七","anchor":"「於是乎盧橘夏孰，黃甘橙楱，枇杷橪柿，楟柰厚朴，梬棗楊梅，","notes":[{"source":"索隱","text":"張揖云：「其大小似穀子而有核，其味酢。出江南。」荊楊異物志：「其實外肉著核，熟時正赤，味甘酸。」"}]},{"id":"a253","section":"司馬相如列傳第五十七","anchor":"「於是乎盧橘夏孰，黃甘橙楱，枇杷橪柿，楟柰厚朴，梬棗楊梅，櫻桃","notes":[{"source":"索隱","text":"張揖曰：「一名含桃。」《呂氏春秋》「爲鸎鳥所含，故曰含桃」。《爾雅》云爲荊桃也。"}]},{"id":"a254","section":"司馬相如列傳第五十七","anchor":"「於是乎盧橘夏孰，黃甘橙楱，枇杷橪柿，楟柰厚朴，梬棗楊梅，櫻桃蒲陶，","notes":[{"source":"集解","text":"郭璞曰：「蒲陶似燕薁，可作酒也。」"}]},{"id":"a255","section":"司馬相如列傳第五十七","anchor":"甘橙楱，枇杷橪柿，楟柰厚朴，梬棗楊梅，櫻桃蒲陶，隱夫鬱棣，榙𣗶荔枝，","notes":[{"source":"集解","text":"徐廣曰：「鬱，一作『薁』。榙音荅。」駰案：郭璞曰「鬱，車下李也。棣，實似櫻桃。榙𣗶似李。棣音逮。𣗶音沓。隱夫未聞」。"},{"source":"索隱","text":"荅遝離支。郭璞云：「荅遝似李，出蜀。」晉灼曰：「離支大如雞子，皮麤，剝去皮，肌如雞子中黃，其味甘多酢少。」廣異志云：「樹高五六丈，如桂樹，綠葉，冬夏青茂，有華朱色。」離字或作「荔」，音力致反。"}]},{"id":"a256","section":"司馬相如列傳第五十七","anchor":"梬棗楊梅，櫻桃蒲陶，隱夫鬱棣，榙𣗶荔枝，羅乎後宮，列乎北園。䝯丘陵，","notes":[{"source":"集解","text":"郭璞曰：「䝯猶延也，音施。」"},{"source":"索隱","text":"䝯丘陵。郭璞曰：「䝯，延也。」"}]},{"id":"a257","section":"司馬相如列傳第五十七","anchor":"鬱棣，榙𣗶荔枝，羅乎後宮，列乎北園。䝯丘陵，下平原，揚翠葉，杌紫莖，","notes":[{"source":"集解","text":"郭璞曰：「杌，搖也。」"}]},{"id":"a258","section":"司馬相如列傳第五十七","anchor":"平原，揚翠葉，杌紫莖，發紅華，秀朱榮，煌煌扈扈，照曜鉅野。沙棠櫟櫧，","notes":[{"source":"集解","text":"《漢書音義》曰：「沙棠似棠，黃華赤實，其味如李。《呂氏春秋》曰『果之美者沙棠之實』。櫟，果名。櫧似柃，葉冬不落也。」"}]},{"id":"a259","section":"司馬相如列傳第五十七","anchor":"葉，杌紫莖，發紅華，秀朱榮，煌煌扈扈，照曜鉅野。沙棠櫟櫧，華氾檘櫨，","notes":[{"source":"集解","text":"徐廣曰：「氾，一作『楓』。」駰案：《漢書音義》曰「華，木，皮可以爲索也」。"},{"source":"索隱","text":"華楓檘櫨。張揖曰：「華皮可以爲索。」古今《字林》云：「櫨，合樺之木。楓，木，厚葉弱支，善搖。」郭璞云：「似白楊，葉圓而岐，有脂而香。犍爲舍人曰『楓爲樹厚葉弱莖，大風則鳴，故曰楓』。」《爾雅》云一名欇。檘枰即平仲木也。櫨，今黃櫨木也。一云玉精，食其子得仙也。"}]},{"id":"a260","section":"司馬相如列傳第五十七","anchor":"秀朱榮，煌煌扈扈，照曜鉅野。沙棠櫟櫧，華氾檘櫨，留落胥餘，仁頻并閭，","notes":[{"source":"集解","text":"徐廣曰：「頻，一作『賓』。」駰案：郭璞曰「落，檴也。胥餘似并閭。并閭，椶也，皮可作索。餘未詳」。"},{"source":"索隱","text":"留落胥邪。晉灼云：「留落，未詳。」郭璞曰：「落，檴也，中作器索。胥邪似并閭。」司馬彪云：「胥邪，樹高十尋，葉在其末。」異物志：「實大如瓠，繫在顛，若挂物。實外有皮，中有核，如胡桃。核裏有膚，厚半寸，如豬膏。裏有汁斗餘，清如水，味美於蜜。」孟康曰：「仁頻，椶也。」張揖云：「并閭皮可爲索。」姚氏云：「檳，一名椶，即仁頻也。」林邑記云：「樹葉似甘蕉。」頻音賓。"}]},{"id":"a261","section":"司馬相如列傳第五十七","anchor":"曜鉅野。沙棠櫟櫧，華氾檘櫨，留落胥餘，仁頻并閭，欃檀木蘭，豫章女貞，","notes":[{"source":"集解","text":"《漢書音義》曰：「欃檀，檀別名也。女貞，木，葉冬不落。」"},{"source":"索隱","text":"欃音讒，檀別名也。《皇覽》云「孔子墓後有欃檀樹」也。荊州記云：「宜都有喬木，叢生，名爲女貞，葉冬不落。」"}]},{"id":"a262","section":"司馬相如列傳第五十七","anchor":"，長千仞，大連抱，夸條直暢，實葉葰茂，攢立叢倚，連卷累佹，崔錯癹骫，","notes":[{"source":"集解","text":"古「委」字。"}]},{"id":"a263","section":"司馬相如列傳第五十七","anchor":"大連抱，夸條直暢，實葉葰茂，攢立叢倚，連卷累佹，崔錯癹骫，阬衡閜砢，","notes":[{"source":"集解","text":"徐廣曰：「癹音拔。」駰案：郭璞曰「骫音委。閜音惡可反。砢音魯可反」。"},{"source":"索隱","text":"崔錯癹骫，郭璞云「蟠戾相摎」。楚詞云林木。癹音跋。骫音委。阬衡閜砢，郭璞云「揭孼傾欹兒」。"}]},{"id":"a264","section":"司馬相如列傳第五十七","anchor":"葉葰茂，攢立叢倚，連卷累佹，崔錯癹骫，阬衡閜砢，垂條扶於，落英幡纚，","notes":[{"source":"集解","text":"郭璞曰：「扶於猶扶疏也。幡纚，偏幡也，音灑。」"},{"source":"索隱","text":"張晏云：「飛揚兒。」纚音所綺反。"}]},{"id":"a265","section":"司馬相如列傳第五十七","anchor":"卷累佹，崔錯癹骫，阬衡閜砢，垂條扶於，落英幡纚，紛容蕭蔘，旖旎從風，","notes":[{"source":"索隱","text":"張揖云：「旖旎，阿𨙻也。」"}]},{"id":"a266","section":"司馬相如列傳第五十七","anchor":"錯癹骫，阬衡閜砢，垂條扶於，落英幡纚，紛容蕭蔘，旖旎從風，瀏莅芔吸，","notes":[{"source":"集解","text":"徐廣曰：「莅音栗。」"},{"source":"索隱","text":"劉莅芔歙。郭璞云：「皆林木鼓動之聲。瀏音留。莅如字，又音栗也。」"}]},{"id":"a267","section":"司馬相如列傳第五十七","anchor":"砢，垂條扶於，落英幡纚，紛容蕭蔘，旖旎從風，瀏莅芔吸，蓋象金石之聲，","notes":[{"source":"正義","text":"金，鐘。石，磬。"}]},{"id":"a268","section":"司馬相如列傳第五十七","anchor":"於，落英幡纚，紛容蕭蔘，旖旎從風，瀏莅芔吸，蓋象金石之聲，管籥之音。","notes":[{"source":"正義","text":"廣雅云：「象篪，長一尺，圍一寸，有六孔，無底。籥謂之笛，有七孔。」說文云：「籥，三孔籟也。」"}]},{"id":"a269","section":"司馬相如列傳第五十七","anchor":"纚，紛容蕭蔘，旖旎從風，瀏莅芔吸，蓋象金石之聲，管籥之音。柴池茈虒，","notes":[{"source":"集解","text":"徐廣曰：「柴音差。虒音豸。」"},{"source":"索隱","text":"張揖曰：「柴池，參差也。茈虒，不齊也。柴音差。虒音惻氏反。」"}]},{"id":"a270","section":"司馬相如列傳第五十七","anchor":"風，瀏莅芔吸，蓋象金石之聲，管籥之音。柴池茈虒，旋環後宮，雜遝累輯，","notes":[{"source":"集解","text":"徐廣曰：「雜，一作『插』。」"}]},{"id":"a271","section":"司馬相如列傳第五十七","anchor":"「於是玄猨素雌，蜼玃飛鸓，","notes":[{"source":"集解","text":"徐廣曰：「蜼音于季反。」駰案：《漢書音義》曰「蜼似獼猴，仰鼻而長尾。玃似獼猴而大。飛鸓，飛鼠也。其狀如兔而鼠首，以其𩓿飛也」。"},{"source":"索隱","text":"張揖曰：「蜼似獼猴，卬鼻而長尾。玃似獼猴而大。飛蠝，飛鼠也。其狀如兔而鼠首，以其𩓿飛。」郭璞曰：「蠝，飛鼠也。毛紫赤色。飛且生，一名飛生。蜼音遺。蠝音誄。玄猨，猨之雄者色也。素雌，猨之雌者色也。」玃音钁。蜼似猴，尾端爲兩岐，天雨便以尾窒鼻兩孔。郭璞云：「玃色蒼黑，能攫搏人，故云玃也。」"}]},{"id":"a272","section":"司馬相如列傳第五十七","anchor":"「於是玄猨素雌，蜼玃飛鸓，蛭蜩蠗蝚，","notes":[{"source":"集解","text":"徐廣曰：「蛭音質。」駰案：《漢書音義》曰「《山海經》曰『不咸之山有飛蛭，四翼』。郭璞曰『蠗蝚似獼猴而黃。蜩未聞』」。"},{"source":"索隱","text":"蛭蜩蠼蝚。司馬彪云：「《山海經》云『不咸之山有飛蛭，四翼』。」蜩，蟬也。蠼蝚，獼猴也。郭璞云：「蛭蜩未聞。」如淳曰：「蛭音質。」顧氏云：「玃音塗卓反。《山海經》曰『皐塗山下有獸，似鹿，馬足人首，四角，名爲玃』。玃猱即此也。字作『𤣎』。郭璞云玃，非也。上已有蜼玃，此不應重見。又《神異經》云『西方深山有獸，毛色如猴，能緣高木，其名曰蜩』。《字林》蠗音狄，蛭音質，蛭蜩二獸名。」"}]},{"id":"a273","section":"司馬相如列傳第五十七","anchor":"「於是玄猨素雌，蜼玃飛鸓，蛭蜩蠗蝚，螹胡豰蛫，","notes":[{"source":"集解","text":"徐廣曰：「螹音在廉反，似猨，黑身。豰音呼谷反。蛫音詭。」駰案：《漢書音義》曰「豰，白狐子也」。"},{"source":"索隱","text":"獑胡豰蛫。張揖曰：「獑胡似獼猴，頭上有髦，腰以後黑。」郭璞曰：「豰似鼯而大，腰以後黃，一名黃腰，食獼猴。豰，白狐子也。蛫未聞。」姚氏案：《山海經》「即山有獸，狀如龜，白身赤首，其名曰蛫」。又說文云「獑胡黑身，白腰若帶，手有長白毛，似握板也」。"}]},{"id":"a274","section":"司馬相如列傳第五十七","anchor":"素雌，蜼玃飛鸓，蛭蜩蠗蝚，螹胡豰蛫，棲息乎其閒；長嘯哀鳴，翩幡互經，","notes":[{"source":"正義","text":"郭云：「互經，互相經過。」"}]},{"id":"a275","section":"司馬相如列傳第五十七","anchor":"蠗蝚，螹胡豰蛫，棲息乎其閒；長嘯哀鳴，翩幡互經，夭蟜枝格，偃蹇杪顛。","notes":[{"source":"正義","text":"夭音妖。蟜音矯。杪音弭沼反。郭云：「皆猨猴在樹共戲恣態也。夭蟜，頻申也。」"}]},{"id":"a276","section":"司馬相如列傳第五十七","anchor":"，棲息乎其閒；長嘯哀鳴，翩幡互經，夭蟜枝格，偃蹇杪顛。於是乎隃絕梁，","notes":[{"source":"正義","text":"張云：「絕梁，斷橋也。」郭云：「梁，厚石絕水也。」"}]},{"id":"a277","section":"司馬相如列傳第五十七","anchor":"其閒；長嘯哀鳴，翩幡互經，夭蟜枝格，偃蹇杪顛。於是乎隃絕梁，騰殊榛，","notes":[{"source":"正義","text":"榛，仕斤反。（爾）〔廣〕雅云「木叢生爲榛」也。殊，異也。"}]},{"id":"a278","section":"司馬相如列傳第五十七","anchor":"嘯哀鳴，翩幡互經，夭蟜枝格，偃蹇杪顛。於是乎隃絕梁，騰殊榛，捷垂條，","notes":[{"source":"正義","text":"捷音才業反。張云：「捷持懸垂之條。」"}]},{"id":"a279","section":"司馬相如列傳第五十七","anchor":"翩幡互經，夭蟜枝格，偃蹇杪顛。於是乎隃絕梁，騰殊榛，捷垂條，踔稀閒，","notes":[{"source":"集解","text":"郭璞曰：「踔，縣蹢也，託釣反。」"},{"source":"索隱","text":"踔，懸蹢也。"}]},{"id":"a280","section":"司馬相如列傳第五十七","anchor":"偃蹇杪顛。於是乎隃絕梁，騰殊榛，捷垂條，踔稀閒，牢落陸離，爛曼遠遷。","notes":[{"source":"正義","text":"郭云：「奔走崩騰狀也。」顏云：「言其聚散不常，雜亂移徙。」"}]},{"id":"a281","section":"司馬相如列傳第五十七","anchor":"「若此輩者，數千百處。嬉游往來，宮宿館舍，庖廚不徙，後宮不移，","notes":[{"source":"正義","text":"說文云：「庖，廚屋。」鄭玄注周《禮》云：「庖之言苞也。苞裹肉曰苞苴也。」後宮，內人也。言宮館各自有。"}]},{"id":"a282","section":"司馬相如列傳第五十七","anchor":"「於是乎背秋涉冬，天子校獵。乘鏤象，六玉虯，","notes":[{"source":"集解","text":"徐廣曰：「以玉爲飾。」駰案：郭璞曰「鏤象山所出輿，言有雕鏤。虯，龍屬也。韓子曰『黃帝駕象車六交龍』是也」。"}]},{"id":"a283","section":"司馬相如列傳第五十七","anchor":"「於是乎背秋涉冬，天子校獵。乘鏤象，六玉虯，拖蜺旌，","notes":[{"source":"正義","text":"拖音徒可反。張云：「析毛羽，染以五采，綴以縷爲旌，有似虹蜺氣。」"}]},{"id":"a284","section":"司馬相如列傳第五十七","anchor":"「於是乎背秋涉冬，天子校獵。乘鏤象，六玉虯，拖蜺旌，靡雲旗，","notes":[{"source":"正義","text":"張云：「畫熊虎於旌似雲氣也。」"}]},{"id":"a285","section":"司馬相如列傳第五十七","anchor":"背秋涉冬，天子校獵。乘鏤象，六玉虯，拖蜺旌，靡雲旗，前皮軒，後道游；","notes":[{"source":"集解","text":"郭璞曰：「皮軒，革車也。或曰即曲禮『前有士師，則載虎皮』者也。道，道車；游，游車：皆見《周禮》也。」"}]},{"id":"a286","section":"司馬相如列傳第五十七","anchor":"乘鏤象，六玉虯，拖蜺旌，靡雲旗，前皮軒，後道游；孫叔奉轡，衞公驂乘，","notes":[{"source":"集解","text":"《漢書音義》曰：「孫叔者，太僕公孫賀也。衞公者，衞青也。太僕御，大將軍驂乘也。」"},{"source":"索隱","text":"孫叔，鄭氏云太僕公孫賀。衞公，大將軍衞青也。案：大駕出，太僕御，大將軍驂乘也。"}]},{"id":"a287","section":"司馬相如列傳第五十七","anchor":"靡雲旗，前皮軒，後道游；孫叔奉轡，衞公驂乘，扈從橫行，出乎四校之中。","notes":[{"source":"集解","text":"郭璞曰：「言跋扈縱恣，不安鹵簿矣。」"},{"source":"索隱","text":"晉灼曰：「扈，大也。」張揖曰：「跋扈縱橫，不案鹵簿也。」文穎曰：「凡五校，今言四者，一校隨天子乘輿也。」"}]},{"id":"a288","section":"司馬相如列傳第五十七","anchor":"後道游；孫叔奉轡，衞公驂乘，扈從橫行，出乎四校之中。鼓嚴簿，縱獠者，","notes":[{"source":"集解","text":"《漢書音義》曰：「鼓嚴，嚴鼓也。簿，鹵簿也。」駰謂鼓嚴於林薄之中，然後縱獠也。"},{"source":"索隱","text":"張揖曰：「鼓，嚴鼓也。簿，鹵簿也。謂擊嚴鼓於鹵簿中也。」"}]},{"id":"a289","section":"司馬相如列傳第五十七","anchor":"公驂乘，扈從橫行，出乎四校之中。鼓嚴簿，縱獠者，江河爲阹，泰山爲櫓，","notes":[{"source":"集解","text":"郭璞曰：「櫓，望樓也。因山谷遮禽獸爲阹，音去車反。」"},{"source":"索隱","text":"郭璞曰：「因山谷遮禽獸爲阹。櫓，望樓也。」"}]},{"id":"a290","section":"司馬相如列傳第五十七","anchor":"「生貔豹，","notes":[{"source":"集解","text":"郭璞曰：「貔，執夷，虎屬也，音毗。」"}]},{"id":"a291","section":"司馬相如列傳第五十七","anchor":"「生貔豹，搏豺狼，","notes":[{"source":"正義","text":"搏，擊也。杜林云：「豺似㹮，白色。」說文云：「狼爪。」"}]},{"id":"a292","section":"司馬相如列傳第五十七","anchor":"「生貔豹，搏豺狼，手熊羆，","notes":[{"source":"正義","text":"張云：「熊，犬身人足，黑色。羆大於熊，黃白色。皆能攀沿上高樹。冬至入穴而蟄，始春而出也。」"}]},{"id":"a293","section":"司馬相如列傳第五十七","anchor":"「生貔豹，搏豺狼，手熊羆，足野羊，","notes":[{"source":"集解","text":"郭璞曰：「野羊如羊，千斤。手足，謂拍蹹殺之。」"}]},{"id":"a294","section":"司馬相如列傳第五十七","anchor":"「生貔豹，搏豺狼，手熊羆，足野羊，蒙鶡蘇，","notes":[{"source":"集解","text":"徐廣曰：「蘇，尾也。」"},{"source":"索隱","text":"孟康曰：「鶡尾也。蘇，析羽也。」張揖曰：「鶡似雉，鬬死不卻。」案：蒙謂覆而取之。鶡以蘇爲奇，故特言之以成文耳。鶡音曷。決疑注云「鳥尾爲蘇」也。"}]},{"id":"a295","section":"司馬相如列傳第五十七","anchor":"「生貔豹，搏豺狼，手熊羆，足野羊，蒙鶡蘇，絝白虎，","notes":[{"source":"集解","text":"徐廣曰：「絝音袴。」駰案：郭璞曰「絝謂絆絡之」。"},{"source":"索隱","text":"張揖曰：「著白虎文絝。」郭璞曰：「絝謂絆絡也。」"}]},{"id":"a296","section":"司馬相如列傳第五十七","anchor":"「生貔豹，搏豺狼，手熊羆，足野羊，蒙鶡蘇，絝白虎，被豳文，","notes":[{"source":"集解","text":"郭璞曰：「著斑衣。」"},{"source":"索隱","text":"被斑文。文穎曰：「著斑文之衣。輿服志云『虎賁騎被虎文單衣』，單衣即此斑文也。」"}]},{"id":"a297","section":"司馬相如列傳第五十七","anchor":"「生貔豹，搏豺狼，手熊羆，足野羊，蒙鶡蘇，絝白虎，被豳文，跨野馬。","notes":[{"source":"索隱","text":"跨壄馬。案：壄音野。跨，乘之也。"}]},{"id":"a298","section":"司馬相如列傳第五十七","anchor":"搏豺狼，手熊羆，足野羊，蒙鶡蘇，絝白虎，被豳文，跨野馬。陵三嵏之危，","notes":[{"source":"集解","text":"《漢書音義》曰：「三嵏，三成之山。」"}]},{"id":"a299","section":"司馬相如列傳第五十七","anchor":"羆，足野羊，蒙鶡蘇，絝白虎，被豳文，跨野馬。陵三嵏之危，下磧歷之坻；","notes":[{"source":"集解","text":"郭璞曰：「磧歷，阪名也。」"},{"source":"正義","text":"坻音遟。磧歷，淺水中沙石也。坻，水中高處。言獵人下此也。"}]},{"id":"a300","section":"司馬相如列傳第五十七","anchor":"被豳文，跨野馬。陵三嵏之危，下磧歷之坻；俓陖赴險，越壑厲水。推蜚廉，","notes":[{"source":"集解","text":"郭璞曰：「飛廉，龍雀也，鳥身鹿頭者。」"},{"source":"索隱","text":"椎蜚廉。郭璞曰：「飛廉，龍雀也，鳥身鹿頭，象在平樂觀。」椎音直追反。"}]},{"id":"a301","section":"司馬相如列傳第五十七","anchor":"跨野馬。陵三嵏之危，下磧歷之坻；俓陖赴險，越壑厲水。推蜚廉，弄解豸，","notes":[{"source":"集解","text":"《漢書音義》曰：「解豸似鹿而一角。人君刑罰得中則生於朝廷，主觸不直者。可得而弄也。」"},{"source":"索隱","text":"張揖曰：「解豸似鹿而一角。人君刑罰中則生於朝，主觸不直者，言今可得而弄也。」解音蟹。豸音丈妳反，又音丈介反。"}]},{"id":"a302","section":"司馬相如列傳第五十七","anchor":"危，下磧歷之坻；俓陖赴險，越壑厲水。推蜚廉，弄解豸，格瑕蛤，鋋猛氏，","notes":[{"source":"集解","text":"《漢書音義》曰：「瑕蛤、猛氏皆獸名。」"},{"source":"索隱","text":"格蝦蛤，鋋猛氏。孟康曰：「蝦蛤、猛氏皆獸名。」晉灼曰：「蝦蛤闕。」郭璞曰：「今蜀中有獸，狀如熊而小，毛淺有光澤，名猛氏。」說文云「鋋，小矛也」，音蟬。"}]},{"id":"a303","section":"司馬相如列傳第五十七","anchor":"俓陖赴險，越壑厲水。推蜚廉，弄解豸，格瑕蛤，鋋猛氏，罥騕褭，射封豕。","notes":[{"source":"集解","text":"郭璞曰：「騕褭，神馬，日行萬里。兩音窈嫋。封豕，大豬。」"}]},{"id":"a304","section":"司馬相如列傳第五十七","anchor":"推蜚廉，弄解豸，格瑕蛤，鋋猛氏，罥騕褭，射封豕。箭不苟害，解脰陷腦；","notes":[{"source":"索隱","text":"張揖云：「脰，頸也。」陷音苦念反，亦依字讀也。"}]},{"id":"a305","section":"司馬相如列傳第五十七","anchor":"乎乘輿彌節裴回，翱翔往來，睨部曲之進退，覽將率之變態。然後浸潭促節，","notes":[{"source":"索隱","text":"浸潭猶漸䒣也。《漢書》作「浸淫」。或作「乘輿案節」也。潭音尋。"}]},{"id":"a306","section":"司馬相如列傳第五十七","anchor":"裴回，翱翔往來，睨部曲之進退，覽將率之變態。然後浸潭促節，儵敻遠去，","notes":[{"source":"集解","text":"郭璞曰：「敻音詡盛反。」"}]},{"id":"a307","section":"司馬相如列傳第五十七","anchor":"之變態。然後浸潭促節，儵敻遠去，流離輕禽，蹵履狡獸，轊白鹿，捷狡兔，","notes":[{"source":"集解","text":"徐廣曰：「轊音銳。一作『惠』也。」"},{"source":"正義","text":"轊音衞。抱朴子云：「白鹿壽千歲，滿五百歲色純白也。」晉徵祥記云：「白鹿色若霜，不與他鹿爲羣。」"}]},{"id":"a308","section":"司馬相如列傳第五十七","anchor":"促節，儵敻遠去，流離輕禽，蹵履狡獸，轊白鹿，捷狡兔，軼赤電，遺光燿，","notes":[{"source":"集解","text":"徐廣曰：「超陵赤電，電光不及，言去速也。」"}]},{"id":"a309","section":"司馬相如列傳第五十七","anchor":"流離輕禽，蹵履狡獸，轊白鹿，捷狡兔，軼赤電，遺光燿，追怪物，出宇宙，","notes":[{"source":"正義","text":"怪物，謂游梟飛虡也。張揖云：「天地四方曰宇，往古來今曰宙。」許慎云：「宙，舟輿所極也。」案：許說宙是也。"}]},{"id":"a310","section":"司馬相如列傳第五十七","anchor":"，蹵履狡獸，轊白鹿，捷狡兔，軼赤電，遺光燿，追怪物，出宇宙，彎繁弱，","notes":[{"source":"正義","text":"上烏繁反。文穎云：「彎，牽也。繁弱，夏后氏良弓名。《左傳》云『分魯公以夏后之璜，封父之繁弱』。」"}]},{"id":"a311","section":"司馬相如列傳第五十七","anchor":"獸，轊白鹿，捷狡兔，軼赤電，遺光燿，追怪物，出宇宙，彎繁弱，滿白羽，","notes":[{"source":"正義","text":"文穎云：「引弓盡箭鏑爲滿。以白羽羽箭，故云白羽也。」"}]},{"id":"a312","section":"司馬相如列傳第五十七","anchor":"兔，軼赤電，遺光燿，追怪物，出宇宙，彎繁弱，滿白羽，射游梟，櫟蜚虡，","notes":[{"source":"集解","text":"郭璞曰：「梟，梟羊也。似人，長脣，反踵，被髮，食人。蜚虡，鹿頭龍身，神獸。櫟，梢也。」"}]},{"id":"a313","section":"司馬相如列傳第五十七","anchor":"彎繁弱，滿白羽，射游梟，櫟蜚虡，擇肉後發，先中命處，弦矢分，藝殪仆。","notes":[{"source":"集解","text":"徐廣曰：「射準的曰藝。仆音赴。」"}]},{"id":"a314","section":"司馬相如列傳第五十七","anchor":"「然後揚節而上浮，陵驚風，歷駭飇，","notes":[{"source":"正義","text":"飇音必遙反。《爾雅》云扶搖暴風，從下升上，故曰飇。"}]},{"id":"a315","section":"司馬相如列傳第五十七","anchor":"「然後揚節而上浮，陵驚風，歷駭飇，乘虛無，與神俱，","notes":[{"source":"正義","text":"張揖云：「虛無寥廓，與天通靈，言其所乘氣之高，故能出飛鳥之上而與神俱也。」"}]},{"id":"a316","section":"司馬相如列傳第五十七","anchor":"「然後揚節而上浮，陵驚風，歷駭飇，乘虛無，與神俱，轔玄鶴，","notes":[{"source":"集解","text":"徐廣曰：「轔音躪。」"},{"source":"正義","text":"轔音吝。鶴二百六十歲則淺黑色也。"}]},{"id":"a317","section":"司馬相如列傳第五十七","anchor":"飇，乘虛無，與神俱，轔玄鶴，亂昆雞。遒孔鸞，促鵔䴊，拂鷖鳥，捎鳳皇，","notes":[{"source":"集解","text":"《漢書音義》曰：「遒，秦由反。鷖，烏雞反。張云『《山海經》云九疑之山有五采之鳥，名曰鷖鳥』也。」"},{"source":"正義","text":"捎，山交反。京房易傳云：「鳳皇，鴈前麟後，雞喙燕頷，蛇頸龜背，魚尾駢翼，高丈二尺。」東山經云：「其狀如鶴，五采，而首文曰經，翼文曰順，背文曰義，膺文曰仁，股文曰信。是鳥自歌自舞，雄曰鳳，雌曰皇。」"}]},{"id":"a318","section":"司馬相如列傳第五十七","anchor":"俱，轔玄鶴，亂昆雞。遒孔鸞，促鵔䴊，拂鷖鳥，捎鳳皇，捷鴛雛，掩焦明。","notes":[{"source":"集解","text":"焦明似鳳。"},{"source":"索隱","text":"張揖曰：「焦明似鳳，西方鳥。」樂叶圖徵曰：「焦明狀似鳳皇。」宋衷曰水鳥。"},{"source":"正義","text":"案：長喙，疏翼，員尾，非幽閑不集，非珍物不食。"}]},{"id":"a319","section":"司馬相如列傳第五十七","anchor":"「道盡塗殫，迴車而還。招搖乎襄羊，","notes":[{"source":"索隱","text":"消搖乎襄羊。郭璞曰「襄羊猶仿佯。」"}]},{"id":"a320","section":"司馬相如列傳第五十七","anchor":"「道盡塗殫，迴車而還。招搖乎襄羊，降集乎北紘，","notes":[{"source":"集解","text":"郭璞曰：「紘，維也。北方之紘曰委羽。」"}]},{"id":"a321","section":"司馬相如列傳第五十七","anchor":"北紘，率乎直指，闇乎反鄉。蹷石（闕）〔關〕，歷封巒，過䧴鵲，望露寒，","notes":[{"source":"集解","text":"徐廣曰：「䧴音支。」駰案：《漢書音義》曰「皆甘泉宮左右觀名也」。"}]},{"id":"a322","section":"司馬相如列傳第五十七","anchor":"乎直指，闇乎反鄉。蹷石（闕）〔關〕，歷封巒，過䧴鵲，望露寒，下棠梨，","notes":[{"source":"集解","text":"《漢書音義》曰：「宮名也，在雲陽縣東南三十里。」"}]},{"id":"a323","section":"司馬相如列傳第五十七","anchor":"闇乎反鄉。蹷石（闕）〔關〕，歷封巒，過䧴鵲，望露寒，下棠梨，息宜春，","notes":[{"source":"正義","text":"《括地志》云：「宜春宮在雍州萬年縣西南三十里。」"}]},{"id":"a324","section":"司馬相如列傳第五十七","anchor":"〔關〕，歷封巒，過䧴鵲，望露寒，下棠梨，息宜春，西馳宣曲，濯鷁牛首，","notes":[{"source":"集解","text":"《漢書音義》曰：「宣曲，宮名，在昆明池西。牛首，池名，在上林苑西頭。」"}]},{"id":"a325","section":"司馬相如列傳第五十七","anchor":"歷封巒，過䧴鵲，望露寒，下棠梨，息宜春，西馳宣曲，濯鷁牛首，登龍臺，","notes":[{"source":"集解","text":"《漢書音義》曰：「觀名，在豐水西北近渭。」"}]},{"id":"a326","section":"司馬相如列傳第五十七","anchor":"過䧴鵲，望露寒，下棠梨，息宜春，西馳宣曲，濯鷁牛首，登龍臺，掩細柳，","notes":[{"source":"正義","text":"郭云：「觀名，在昆明南柳市。」"}]},{"id":"a327","section":"司馬相如列傳第五十七","anchor":"西馳宣曲，濯鷁牛首，登龍臺，掩細柳，觀士大夫之勤略，鈞獠者之所得獲。","notes":[{"source":"集解","text":"徐廣曰：「鈞，一作『診』也。」"}]},{"id":"a328","section":"司馬相如列傳第五十七","anchor":"牛首，登龍臺，掩細柳，觀士大夫之勤略，鈞獠者之所得獲。徒車之所轔轢，","notes":[{"source":"正義","text":"轔，踐也。轢，輾也。"}]},{"id":"a329","section":"司馬相如列傳第五十七","anchor":"掩細柳，觀士大夫之勤略，鈞獠者之所得獲。徒車之所轔轢，乘騎之所蹂若，","notes":[{"source":"集解","text":"徐廣曰：「蹂音人久反。」"}]},{"id":"a330","section":"司馬相如列傳第五十七","anchor":"得獲。徒車之所轔轢，乘騎之所蹂若，人民之所蹈𨈁，與其窮極倦{谷凡}，","notes":[{"source":"集解","text":"徐廣曰：「音劇。」"}]},{"id":"a331","section":"司馬相如列傳第五十七","anchor":"「於是乎游戲懈怠，置酒乎昊天之臺，","notes":[{"source":"索隱","text":"張揖云：「臺高上干晧天也。」"}]},{"id":"a332","section":"司馬相如列傳第五十七","anchor":"「於是乎游戲懈怠，置酒乎昊天之臺，張樂乎轇輵之宇；","notes":[{"source":"集解","text":"徐廣曰：「輵音葛。」"},{"source":"索隱","text":"郭璞云：「言曠遠深貌也。」"}]},{"id":"a333","section":"司馬相如列傳第五十七","anchor":"臺，張樂乎轇輵之宇；撞千石之鐘，立萬石之鉅；建翠華之旗，樹靈鼉之鼓。","notes":[{"source":"集解","text":"郭璞曰：「木貫鼓中，加羽葆其上，所謂樹鼓。」"}]},{"id":"a334","section":"司馬相如列傳第五十七","anchor":"鐘，立萬石之鉅；建翠華之旗，樹靈鼉之鼓。奏陶唐氏之舞，聽葛天氏之歌，","notes":[{"source":"集解","text":"《漢書音義》曰：「葛天氏，古帝王號也。《呂氏春秋》曰『葛天氏之樂，三人操牛尾，投足以歌』。」"},{"source":"索隱","text":"張揖曰：「葛天氏，三皇君號也。《呂氏春秋》云『其樂三人持牛尾，投足以歌。八闋：一曰載人，二曰玄鳥，三曰遂草木，四曰奮五穀，五曰敬天常，六曰建帝功，七曰依地德，八曰總禽獸之極』。」"}]},{"id":"a335","section":"司馬相如列傳第五十七","anchor":"靈鼉之鼓。奏陶唐氏之舞，聽葛天氏之歌，千人唱，萬人和，山陵爲之震動，","notes":[{"source":"集解","text":"徐廣曰：「一作『勳』。」"}]},{"id":"a336","section":"司馬相如列傳第五十七","anchor":"歌，千人唱，萬人和，山陵爲之震動，川谷爲之蕩波。巴俞宋蔡，淮南于遮，","notes":[{"source":"集解","text":"郭璞曰：「巴西閬中有俞水，獠人居其上，皆剛勇好舞，漢高募取以平三秦。後使樂府習之，因名巴俞舞也。」《漢書音義》曰：「于遮，歌曲名。」"},{"source":"索隱","text":"郭璞曰：「巴西閬中有俞水，獠人居其上，好舞。初，高祖募取以平三秦，後使樂人習之，因名巴俞舞也。」張揖曰：「禮樂記曰『宋音宴女溺志』。蔡人謳，員三人。楚詞云『吳謠蔡謳』。淮南鼓，員四人，于遮曲是其意也。」"}]},{"id":"a337","section":"司馬相如列傳第五十七","anchor":"，萬人和，山陵爲之震動，川谷爲之蕩波。巴俞宋蔡，淮南于遮，文成顛歌，","notes":[{"source":"集解","text":"郭璞曰：「未聞也。」"},{"source":"索隱","text":"郭璞云：「未聞。」文穎曰：「文成，遼西縣名，其縣人善歌。顛，益州顛縣，其人能作西南夷歌。顛即滇也。」"}]},{"id":"a338","section":"司馬相如列傳第五十七","anchor":"山陵爲之震動，川谷爲之蕩波。巴俞宋蔡，淮南于遮，文成顛歌，族舉遞奏，","notes":[{"source":"集解","text":"徐廣曰：「舉，一作『居』。」"}]},{"id":"a339","section":"司馬相如列傳第五十七","anchor":"俞宋蔡，淮南于遮，文成顛歌，族舉遞奏，金鼓迭起，鏗鎗鐺䶀，洞心駭耳。","notes":[{"source":"集解","text":"郭璞曰：「鐺䶀，鼓音。」"}]},{"id":"a340","section":"司馬相如列傳第五十七","anchor":"駭耳。荊吳鄭衞之聲，韶濩武象之樂，陰淫案衍之音，鄢郢繽紛，激楚結風，","notes":[{"source":"集解","text":"郭璞曰：「激楚，歌曲也。《列女傳》曰『聽激楚之遺風』也。」"},{"source":"索隱","text":"文穎曰：「激，衝激，急風也。結風，回風，回亦急風也。楚地風氣既自漂疾，然歌樂者猶復依激結之急風以爲節，其樂促迅哀切也。」"}]},{"id":"a341","section":"司馬相如列傳第五十七","anchor":"韶濩武象之樂，陰淫案衍之音，鄢郢繽紛，激楚結風，俳優侏儒，狄鞮之倡，","notes":[{"source":"集解","text":"徐廣曰：「韋昭云狄鞮，地名，在河內，出善倡者。」"}]},{"id":"a342","section":"司馬相如列傳第五十七","anchor":"，激楚結風，俳優侏儒，狄鞮之倡，所以娛耳目而樂心意者，麗靡爛漫於前，","notes":[{"source":"索隱","text":"郭璞云：「言恣其觀也。《列女傳》曰『桀造爛漫之樂』。」"}]},{"id":"a343","section":"司馬相如列傳第五十七","anchor":"優侏儒，狄鞮之倡，所以娛耳目而樂心意者，麗靡爛漫於前，靡曼美色於後。","notes":[{"source":"索隱","text":"張揖曰：「靡，細；曼，澤也。韓子『曼服晧齒』。」"}]},{"id":"a344","section":"司馬相如列傳第五十七","anchor":"「若夫青琴宓妃之徒，","notes":[{"source":"集解","text":"《漢書音義》曰：「皆古神女名。」"},{"source":"索隱","text":"伏儼曰：「青琴，古神女也。」如淳曰：「宓妃，伏羲女，溺死洛水，遂爲洛水之神。」宓音伏。"}]},{"id":"a345","section":"司馬相如列傳第五十七","anchor":"「若夫青琴宓妃之徒，絕殊離俗，","notes":[{"source":"索隱","text":"郭璞云：「俗無雙。」"}]},{"id":"a346","section":"司馬相如列傳第五十七","anchor":"「若夫青琴宓妃之徒，絕殊離俗，姣冶嫺都，","notes":[{"source":"索隱","text":"姣冶閑都。郭璞云：「姣，好也。都，雅也。」《詩》云：「姣人嫽兮。」方言云：「自關而東，河濟之閒，凡好或謂之姣。」音絞。說文曰：「嫺，雅也。」或作「閑」。小雅曰都，盛也。"}]},{"id":"a347","section":"司馬相如列傳第五十七","anchor":"「若夫青琴宓妃之徒，絕殊離俗，姣冶嫺都，靚莊刻飭，便嬛綽約，","notes":[{"source":"集解","text":"郭璞曰：「靚莊，粉白黛黑也。」"}]},{"id":"a348","section":"司馬相如列傳第五十七","anchor":"若夫青琴宓妃之徒，絕殊離俗，姣冶嫺都，靚莊刻飭，便嬛綽約，柔橈嬛嬛，","notes":[{"source":"集解","text":"徐廣曰：「音娟。」"},{"source":"索隱","text":"郭璞曰：「柔橈嬛嬛，皆骨體耎弱長豔皃也。」廣雅云：「嬛嬛，容也。」張揖曰：「嬛嬛猶婉婉也。」"}]},{"id":"a349","section":"司馬相如列傳第五十七","anchor":"妃之徒，絕殊離俗，姣冶嫺都，靚莊刻飭，便嬛綽約，柔橈嬛嬛，娬媚㚩嫋；","notes":[{"source":"集解","text":"徐廣曰：「㚩音乃冄反。嫋音弱。」"},{"source":"索隱","text":"嫵媚孅弱。埤蒼云：「嫵媚，悅也。」通俗文云：「頰輔謂之嫵媚。」郭璞云：「孅弱，弱皃。」埤蒼曰：「孅弱，謂容體纖細柔弱也。」"}]},{"id":"a350","section":"司馬相如列傳第五十七","anchor":"俗，姣冶嫺都，靚莊刻飭，便嬛綽約，柔橈嬛嬛，娬媚㚩嫋；抴獨繭之褕袘，","notes":[{"source":"集解","text":"徐廣曰：「抴音曳。襜褕。」"},{"source":"索隱","text":"褕袣。張揖云：「褕，襜褕也。袣，袖也。」郭璞曰：「獨繭，一繭絲也。」埤蒼云：「袣，衣長皃也。」"}]},{"id":"a351","section":"司馬相如列傳第五十七","anchor":"靚莊刻飭，便嬛綽約，柔橈嬛嬛，娬媚㚩嫋；抴獨繭之褕袘，眇閻易以戌削，","notes":[{"source":"集解","text":"徐廣曰：「閻易，衣長貌。戌削，言如刻畫作之。」"},{"source":"索隱","text":"眇閻易以恤削。郭璞曰：「閻易，衣長皃。恤削，言如刻畫作也。」"}]},{"id":"a352","section":"司馬相如列傳第五十七","anchor":"，編姺徶{彳㞕}，與世殊服；芬香漚鬱，酷烈淑郁；晧齒粲爛，宜笑旳皪；","notes":[{"source":"索隱","text":"郭璞曰：「鮮明皃也。」楚詞曰：「美人晧齒〔嫮〕以姱。」又曰：「娥眉笑以旳皪。」皪音礫也。"}]},{"id":"a353","section":"司馬相如列傳第五十七","anchor":"世殊服；芬香漚鬱，酷烈淑郁；晧齒粲爛，宜笑旳皪；長眉連娟，微睇緜藐；","notes":[{"source":"索隱","text":"郭璞曰：「連娟，眉曲細也。緜藐，遠視皃也。」娟音一全反。睇，大計反。藐音邈。"}]},{"id":"a354","section":"司馬相如列傳第五十七","anchor":"烈淑郁；晧齒粲爛，宜笑旳皪；長眉連娟，微睇緜藐；色授魂與，心愉於側。","notes":[{"source":"索隱","text":"張揖曰：「彼色來授我，我魂往與接也。」愉音踰，往也。愉，悅也。二義並通也。"}]},{"id":"a355","section":"司馬相如列傳第五十七","anchor":"墾辟，悉爲農郊，以贍萌隸；隤牆填𡐛，使山澤之民得至焉。實陂池而勿禁，","notes":[{"source":"正義","text":"實，滿也。言人滿陂池，任采捕所取也。"}]},{"id":"a356","section":"司馬相如列傳第五十七","anchor":"，以贍萌隸；隤牆填𡐛，使山澤之民得至焉。實陂池而勿禁，虛宮觀而勿仞。","notes":[{"source":"正義","text":"仞音刃，亦滿也。言離宮別館勿令人居止，並廢罷也。"}]},{"id":"a357","section":"司馬相如列傳第五十七","anchor":"「於是歷吉日以齊戒，襲朝衣，乘法駕，建華旗，鳴玉鸞，游乎六藝之囿，","notes":[{"source":"正義","text":"六藝，云言田獵訖，則遍遊六藝，而疾驅於仁義之道也。"}]},{"id":"a358","section":"司馬相如列傳第五十七","anchor":"，乘法駕，建華旗，鳴玉鸞，游乎六藝之囿，騖乎仁義之塗，覽觀春秋之林，","notes":[{"source":"集解","text":"郭璞曰：「春秋所以觀成敗，明善惡者。」"}]},{"id":"a359","section":"司馬相如列傳第五十七","anchor":"，鳴玉鸞，游乎六藝之囿，騖乎仁義之塗，覽觀春秋之林，射貍首，兼騶虞，","notes":[{"source":"集解","text":"禮射義曰：「天子以騶虞爲節，諸侯以貍首爲節。騶虞者，樂官備也。貍首者，樂會時也。」"}]},{"id":"a360","section":"司馬相如列傳第五十七","anchor":"騖乎仁義之塗，覽觀春秋之林，射貍首，兼騶虞，弋玄鶴，建干戚，載雲䍐，","notes":[{"source":"索隱","text":"張揖云：「䍐，畢也。」文穎曰：「即天畢，星名。前有九旒雲䍐之車。」案：說者以雲䍐爲旌旗，非也。且案中朝鹵簿圖云「雲䍐駕駟」，不兼言九旒，䍐車與九旒車別。"}]},{"id":"a361","section":"司馬相如列傳第五十七","anchor":"之塗，覽觀春秋之林，射貍首，兼騶虞，弋玄鶴，建干戚，載雲䍐，揜羣雅，","notes":[{"source":"集解","text":"《漢書音義》曰：「大雅、小雅也。」"},{"source":"索隱","text":"揜，捕也。張揖曰：「詩小雅之材七十四人，大雅之材三十一人，故曰羣雅也。言雲䍐載之於車，以捕羣雅之士。」"}]},{"id":"a362","section":"司馬相如列傳第五十七","anchor":"觀春秋之林，射貍首，兼騶虞，弋玄鶴，建干戚，載雲䍐，揜羣雅，悲伐檀，","notes":[{"source":"索隱","text":"張揖曰：「其詩刺賢者不遇明主也。」"}]},{"id":"a363","section":"司馬相如列傳第五十七","anchor":"林，射貍首，兼騶虞，弋玄鶴，建干戚，載雲䍐，揜羣雅，悲伐檀，樂樂胥，","notes":[{"source":"索隱","text":"毛《詩》云「君子樂胥，受天之祜」。言王者樂得賢材之人，使之在位，故天與之福祿也。胥音先呂反。"}]},{"id":"a364","section":"司馬相如列傳第五十七","anchor":"兼騶虞，弋玄鶴，建干戚，載雲䍐，揜羣雅，悲伐檀，樂樂胥，修容乎禮園，","notes":[{"source":"正義","text":"禮所以自修飾整威儀也。"}]},{"id":"a365","section":"司馬相如列傳第五十七","anchor":"鶴，建干戚，載雲䍐，揜羣雅，悲伐檀，樂樂胥，修容乎禮園，翱翔乎書圃，","notes":[{"source":"正義","text":"《尚書》所以明帝王君臣之道也。"}]},{"id":"a366","section":"司馬相如列傳第五十七","anchor":"戚，載雲䍐，揜羣雅，悲伐檀，樂樂胥，修容乎禮園，翱翔乎書圃，述易道，","notes":[{"source":"正義","text":"易所以絜靜微妙，上辨二儀陰陽，中知人事，下明地理也。言田獵乃射訖，又歷涉六經之要也。"}]},{"id":"a367","section":"司馬相如列傳第五十七","anchor":"䍐，揜羣雅，悲伐檀，樂樂胥，修容乎禮園，翱翔乎書圃，述易道，放怪獸，","notes":[{"source":"正義","text":"張揖云：「苑中奇怪之獸，不復獵也。」"}]},{"id":"a368","section":"司馬相如列傳第五十七","anchor":"檀，樂樂胥，修容乎禮園，翱翔乎書圃，述易道，放怪獸，登明堂，坐清廟，","notes":[{"source":"正義","text":"明堂有五帝廟，故言「清廟」，王者朝諸侯之處。"}]},{"id":"a369","section":"司馬相如列傳第五十七","anchor":"述易道，放怪獸，登明堂，坐清廟，恣羣臣，奏得失，四海之內，靡不受獲。","notes":[{"source":"正義","text":"言天下之人無不受恩惠。"}]},{"id":"a370","section":"司馬相如列傳第五十七","anchor":"失，四海之內，靡不受獲。於斯之時，天下大說，嚮風而聽，隨流而化，喟然","notes":[{"source":"索隱","text":"喟，《漢書》作「芔」，音許貴反。"}]},{"id":"a371","section":"司馬相如列傳第五十七","anchor":"而聽，隨流而化，喟然興道而遷義，刑錯而不用，德隆乎三皇，功羨於五帝。","notes":[{"source":"索隱","text":"司馬彪云：「羨，溢也。」音怡戰反。"}]},{"id":"a372","section":"司馬相如列傳第五十七","anchor":"「若夫終日暴露馳騁，勞神苦形，罷車馬之用，抏士卒之精，","notes":[{"source":"索隱","text":"抏音五官反。"}]},{"id":"a373","section":"司馬相如列傳第五十七","anchor":"於是二子愀然","notes":[{"source":"索隱","text":"郭璞云：「變色皃。」音作酉反。"}]},{"id":"a374","section":"司馬相如列傳第五十七","anchor":"楚雲夢所有甚眾，侈靡過其實，且非義理所尚，故刪取其要，歸正道而論之。","notes":[{"source":"索隱","text":"大顏云：「不取其夸奢靡麗之論，唯取終篇歸於正道耳。」小顏云：「刪要，非謂削除其詞，而說者謂此賦已經史家刊剟，失之也。」"}]},{"id":"a375","section":"司馬相如列傳第五十七","anchor":"相如爲郎數歲，會唐蒙使略通","notes":[{"source":"索隱","text":"張揖曰：「蒙，故鄱陽令，今爲郎中，使行略取之。」"}]},{"id":"a376","section":"司馬相如列傳第五十七","anchor":"相如爲郎數歲，會唐蒙使略通夜郎西僰中，","notes":[{"source":"集解","text":"徐廣曰：「羌之別種也。音扶逼反。」"},{"source":"索隱","text":"夜郎、僰中，文穎曰皆西〔南〕夷。後以爲夜郎屬牂柯，僰屬犍爲。音步北反。"}]},{"id":"a377","section":"司馬相如列傳第五十七","anchor":"相如爲郎數歲，會唐蒙使略通夜郎西僰中，發巴蜀","notes":[{"source":"索隱","text":"案：巴、蜀，二郡名。"}]},{"id":"a378","section":"司馬相如列傳第五十七","anchor":"會唐蒙使略通夜郎西僰中，發巴蜀吏卒千人，郡又多爲發轉漕萬餘人，用興法","notes":[{"source":"集解","text":"《漢書》曰「用軍興法」也。"}]},{"id":"a379","section":"司馬相如列傳第五十七","anchor":"居西域，重譯請朝，稽首來享。移師東指，閩越相誅。右弔番禺，太子入朝。","notes":[{"source":"索隱","text":"文穎曰：「番禺，南海郡理也。弔，至也。東伐閩越，後至番禺，故言右至也。」案：姚氏弔讀如字。小顏云「兩國相伐，漢發兵救之，令弔番禺，故遣太子入朝，弔非至也」。"}]},{"id":"a380","section":"司馬相如列傳第五十七","anchor":"，太子入朝。南夷之君，西僰之長，常效貢職，不敢怠墮，延頸舉踵，喁喁然","notes":[{"source":"正義","text":"喁，五恭反，口向上也。"}]},{"id":"a381","section":"司馬相如列傳第五十七","anchor":"，山川阻深，不能自致。夫不順者已誅，而爲善者未賞，故遣中郎將往賓之，","notes":[{"source":"索隱","text":"賈逵云：「賓，伏也。」"}]},{"id":"a382","section":"司馬相如列傳第五十七","anchor":"人，以奉幣帛，衞使者不然，靡有兵革之事，戰鬬之患。今聞其乃發軍興制，","notes":[{"source":"索隱","text":"張揖曰：「發三軍之衆也。興制，謂起軍法制也。」案：唐蒙爲使，而用軍興法制也。"}]},{"id":"a383","section":"司馬相如列傳第五十七","anchor":"夫邊郡之士，聞烽舉燧燔，","notes":[{"source":"集解","text":"《漢書音義》曰：「烽如覆米䉛，縣著桔槔頭，有寇則舉之。燧，積薪，有寇則燔然之。」"},{"source":"索隱","text":"熢燧。韋昭曰：「熢，束草置之長木之端，如挈皋，見敵則燒舉之。燧者，積薪，有難則焚之。熢主晝，燧主夜。」《字林》云：「䉛，漉米籔也，音一六反。」又纂要云：「䉛，淅箕也。」此注是孟康說。"}]},{"id":"a384","section":"司馬相如列傳第五十七","anchor":"夫邊郡之士，聞烽舉燧燔，皆攝弓","notes":[{"source":"索隱","text":"上音奴頰反。"}]},{"id":"a385","section":"司馬相如列傳第五十七","anchor":"蜀異主哉？計深慮遠，急國家之難，而樂盡人臣之道也。故有剖符之封，析珪","notes":[{"source":"索隱","text":"如淳曰：「析，中分也。白藏天子，青在諸侯也。」"}]},{"id":"a386","section":"司馬相如列傳第五十七","anchor":"之難，而樂盡人臣之道也。故有剖符之封，析珪而爵，位爲通侯，居列東第，","notes":[{"source":"索隱","text":"列甲第在帝城東，故云東第也。"}]},{"id":"a387","section":"司馬相如列傳第五十七","anchor":"，因數之以不忠死亡之罪，讓三老孝弟以不教誨之過。方今田時，重煩百姓，","notes":[{"source":"索隱","text":"重猶難也。"}]},{"id":"a388","section":"司馬相如列傳第五十七","anchor":"時，重煩百姓，已親見近縣，恐遠所谿谷山澤之民不徧聞，檄到，亟下縣道，","notes":[{"source":"集解","text":"《漢書百官表》曰：「縣有蠻夷曰道。」"},{"source":"索隱","text":"亟音紀力反。亟，急也。"}]},{"id":"a389","section":"司馬相如列傳第五十七","anchor":"、蜀、廣漢卒，作者數萬人。治道二歲，道不成，士卒多物故，費以巨萬計。","notes":[{"source":"索隱","text":"案：巨萬猶萬萬也。案：數有大小二法。張揖曰「算法萬萬爲億」，是大數也。鬻子曰「十萬爲億」，是小數也。"}]},{"id":"a390","section":"司馬相如列傳第五十七","anchor":"作者數萬人。治道二歲，道不成，士卒多物故，費以巨萬計。蜀民及漢用事者","notes":[{"source":"索隱","text":"案：謂公孫弘也。"}]},{"id":"a391","section":"司馬相如列傳第五十七","anchor":"成，士卒多物故，費以巨萬計。蜀民及漢用事者多言其不便。是時邛筰之君長","notes":[{"source":"索隱","text":"邛笮之君長。文穎曰：「邛者，今爲邛都縣；笮者，今爲定笮縣：皆屬越嶲郡。」"}]},{"id":"a392","section":"司馬相如列傳第五十七","anchor":"是時邛筰之君長聞南夷與漢通，得賞賜多，多欲願爲內臣妾，請吏，比南夷。","notes":[{"source":"索隱","text":"謂請置漢吏，與南夷爲比例也。"}]},{"id":"a393","section":"司馬相如列傳第五十七","anchor":"亦易通，秦時嘗通爲郡縣，至漢興而罷。今誠復通，爲置郡縣，愈於南夷。」","notes":[{"source":"索隱","text":"張揖曰：「愈，差也。」又云：「愈猶勝也。」晉灼曰：「南夷謂犍爲、牂柯也。西夷謂越嶲、益州。」"}]},{"id":"a394","section":"司馬相如列傳第五十七","anchor":"而罷。今誠復通，爲置郡縣，愈於南夷。」天子以爲然，乃拜相如爲中郎將，","notes":[{"source":"索隱","text":"張揖曰：「秩四百石，五歲遷補大縣令。」"}]},{"id":"a395","section":"司馬相如列傳第五十七","anchor":"南夷。」天子以爲然，乃拜相如爲中郎將，建節往使。副使王然于、壺充國、","notes":[{"source":"索隱","text":"案：《漢書》公卿表太初元年爲鴻臚卿也。"}]},{"id":"a396","section":"司馬相如列傳第五十七","anchor":"乘之傳，因巴蜀吏幣物以賂西夷。至蜀，蜀太守以下郊迎，縣令負弩矢先驅，","notes":[{"source":"索隱","text":"案：亭吏二人，弩矢合是亭長負之；令縣令自負矢，則亭長當負弩也。且負弩亦守宰無定，或隨輕重耳。案：霍去病出擊匈奴，河東太守郊迎負弩。又魏公子救趙擊秦，秦軍解去，平原君負䪍矢迎公子於界上。"}]},{"id":"a397","section":"司馬相如列傳第五十七","anchor":"蜀吏幣物以賂西夷。至蜀，蜀太守以下郊迎，縣令負弩矢先驅，蜀人以爲寵。","notes":[{"source":"索隱","text":"蜀以爲寵。華陽國志云：「蜀大城北十里有升仙橋，有送客觀也。相如初入長安，題其門云『不乘赤車駟馬，不過汝下』也。」"}]},{"id":"a398","section":"司馬相如列傳第五十七","anchor":"邛諸公皆因門下獻牛酒以交驩。卓王孫喟然而歎，自以得使女尚司馬長卿晚，","notes":[{"source":"索隱","text":"小顏云：「尚猶配也。」本或作「當」也。"}]},{"id":"a399","section":"司馬相如列傳第五十七","anchor":"，而厚分與其女財，與男等同。司馬長卿便略定西夷，邛、筰、冄、駹、斯榆","notes":[{"source":"索隱","text":"斯，鄭氏音曳。張揖云「斯俞，國也」。案：今斯讀如字，益郡耆舊傳謂之「斯臾」。華陽國志邛都縣有四部，斯臾一也。"}]},{"id":"a400","section":"司馬相如列傳第五十七","anchor":"長卿便略定西夷，邛、筰、冄、駹、斯榆之君皆請爲內臣。除邊關，關益斥，","notes":[{"source":"索隱","text":"張揖曰：「斥，廣也。」"}]},{"id":"a401","section":"司馬相如列傳第五十七","anchor":"，邛、筰、冄、駹、斯榆之君皆請爲內臣。除邊關，關益斥，西至沬、若水，","notes":[{"source":"索隱","text":"張揖曰：「沬水出蜀廣平徼外，與青衣水合也。若水出旄牛徼外，至僰道入江。」華陽國志漢嘉縣有沬水。音妹，又音末。"}]},{"id":"a402","section":"司馬相如列傳第五十七","anchor":"駹、斯榆之君皆請爲內臣。除邊關，關益斥，西至沬、若水，南至牂柯爲徼，","notes":[{"source":"索隱","text":"張揖曰：「徼，塞也。以木柵水爲蠻夷界。」"}]},{"id":"a403","section":"司馬相如列傳第五十七","anchor":"君皆請爲內臣。除邊關，關益斥，西至沬、若水，南至牂柯爲徼，通零關道，","notes":[{"source":"集解","text":"徐廣曰：「越嶲有零關縣。」"}]},{"id":"a404","section":"司馬相如列傳第五十七","anchor":"爲內臣。除邊關，關益斥，西至沬、若水，南至牂柯爲徼，通零關道，橋孫水","notes":[{"source":"集解","text":"韋昭曰：「爲孫水作橋。」"}]},{"id":"a405","section":"司馬相如列傳第五十七","anchor":"邊關，關益斥，西至沬、若水，南至牂柯爲徼，通零關道，橋孫水以通邛都。","notes":[{"source":"索隱","text":"橋孫水通笮。韋昭曰：「爲孫水作橋也。」案：華陽國志云「相如卒開僰道通南夷，置越嶲郡。韓說開益州，唐蒙開牂柯，斬筰王首，置牂柯郡」也。"}]},{"id":"a406","section":"司馬相如列傳第五十七","anchor":"使時，蜀長老多言通西南夷不爲用，唯大臣亦以爲然。相如欲諫，業已建之，","notes":[{"source":"索隱","text":"案：業者，本也。謂本由相如立此事也。"}]},{"id":"a407","section":"司馬相如列傳第五十七","anchor":"漢興七十有八載，","notes":[{"source":"集解","text":"徐廣曰：「元光六年也。」"}]},{"id":"a408","section":"司馬相如列傳第五十七","anchor":"漢興七十有八載，德茂存乎六世，","notes":[{"source":"正義","text":"高祖、惠帝、高后、孝文、孝景、孝武。"}]},{"id":"a409","section":"司馬相如列傳第五十七","anchor":"漢興七十有八載，德茂存乎六世，威武紛紜，湛恩","notes":[{"source":"索隱","text":"韋昭云：「上音沈。」"}]},{"id":"a410","section":"司馬相如列傳第五十七","anchor":"威武紛紜，湛恩汪濊，羣生澍濡，洋溢乎方外。於是乃命使西征，隨流而攘，","notes":[{"source":"索隱","text":"攘，卻也，汝羊反。"}]},{"id":"a411","section":"司馬相如列傳第五十七","anchor":"隨流而攘，風之所被，罔不披靡。因朝冄從駹，定筰存邛，略斯榆，舉苞滿，","notes":[{"source":"索隱","text":"服虔云：「夷種也。」「滿」字或作「蒲」也。"}]},{"id":"a412","section":"司馬相如列傳第五十七","anchor":"而攘，風之所被，罔不披靡。因朝冄從駹，定筰存邛，略斯榆，舉苞滿，結軼","notes":[{"source":"索隱","text":"下音轍。《漢書》作「軌」。張揖云「結，屈也」。"}]},{"id":"a413","section":"司馬相如列傳第五十七","anchor":"徒二十有七人，儼然造焉。辭畢，因進曰：「蓋聞天子之於夷狄也，其義羈縻","notes":[{"source":"索隱","text":"案：羈，馬絡頭也。縻，牛韁也。漢官儀「馬云羈，牛云縻」。言制四夷如牛馬之受羈縻也。"}]},{"id":"a414","section":"司馬相如列傳第五十七","anchor":"者曰：「烏謂此邪？必若所云，則是蜀不變服而巴不化俗也。余尚惡聞若說。","notes":[{"source":"索隱","text":"張揖曰：「惡聞若曹之言也。」包愷音一故反。又音烏。烏者，安也。"}]},{"id":"a415","section":"司馬相如列傳第五十七","anchor":"有非常之事；有非常之事，然後有非常之功。非常者，固常〔人〕之所異也。","notes":[{"source":"索隱","text":"案：常人見之以爲異。"}]},{"id":"a416","section":"司馬相如列傳第五十七","anchor":"然後有非常之功。非常者，固常〔人〕之所異也。故曰非常之原，黎民懼焉；","notes":[{"source":"索隱","text":"張揖曰：「非常之事，其本難知，眾人懼也。」"}]},{"id":"a417","section":"司馬相如列傳第五十七","anchor":"民人登降移徙，陭䧢而不安。夏后氏戚之，乃堙鴻水，決江疏河，漉沈贍菑，","notes":[{"source":"集解","text":"徐廣曰：「漉，一作『灑』。」"},{"source":"索隱","text":"漉沈澹菑。漉音鹿。菑音災。《漢書》作「澌沈澹灾」，解者云「澌作『灑』，灑，分也，音所綺反。澹，安；沈，深也。澹音徒暫反」。"}]},{"id":"a418","section":"司馬相如列傳第五十七","anchor":"水，決江疏河，漉沈贍菑，東歸之於海，而天下永寧。當斯之勤，豈唯民哉。","notes":[{"source":"索隱","text":"案：謂非獨人勤，禹亦親其勞也。"}]},{"id":"a419","section":"司馬相如列傳第五十七","anchor":"下永寧。當斯之勤，豈唯民哉。心煩於慮而身親其勞，躬胝無胈，膚不生毛。","notes":[{"source":"集解","text":"徐廣曰：「胝音竹移反。胈，踵也。一作『腠』，音湊。膚，理也。胈音魃。」"},{"source":"索隱","text":"躬奏胝無胈。張揖曰：「奏，作『戚』。躬，體也。戚，腠理也。」韋昭曰：「胈，其中小毛也。」胝音丁私反。莊子云「禹腓無胈，脛不生毛」。李頤云「胈，白肉也，音蒲末反」。"}]},{"id":"a420","section":"司馬相如列傳第五十七","anchor":"「且夫賢君之踐位也。豈特委瑣握𪘏，","notes":[{"source":"索隱","text":"孔文祥云：「委璅，細碎。握𪘏，局促也。」"}]},{"id":"a421","section":"司馬相如列傳第五十七","anchor":"將崇論閎議，創業垂統，爲萬世規。故馳騖乎兼容并包，而勤思乎參天貳地。","notes":[{"source":"索隱","text":"案：天子比德於地，是貳地也。與己并天爲三，是參天也。故《禮》曰「天子與天地參」是也。"}]},{"id":"a422","section":"司馬相如列傳第五十七","anchor":"乎參天貳地。且詩不云乎：『普天之下，莫非王土；率土之濱，莫非王臣。』","notes":[{"source":"集解","text":"毛詩傳曰：「濱，涯也。」"}]},{"id":"a423","section":"司馬相如列傳第五十七","anchor":"天之下，莫非王土；率土之濱，莫非王臣。』是以六合之內，八方之外，浸潯","notes":[{"source":"索隱","text":"浸淫。案：浸淫猶漸浸。"}]},{"id":"a424","section":"司馬相如列傳第五十七","anchor":"物靡不得其所，今獨曷爲遺己』。舉踵思慕，若枯旱之望雨。盭夫爲之垂涕，","notes":[{"source":"集解","text":"徐廣曰：「盭音戾。」"},{"source":"索隱","text":"張揖曰：「很戾之夫也。」字或作「戾」。盭，古「戾」字。"}]},{"id":"a425","section":"司馬相如列傳第五十七","anchor":"上聖，又惡能已？故北出師以討彊胡，南馳使以誚勁越。四面風德，二方之君","notes":[{"source":"索隱","text":"謂西夷邛、僰，南夷牂柯、夜郎也。"}]},{"id":"a426","section":"司馬相如列傳第五十七","anchor":"誚勁越。四面風德，二方之君鱗集仰流，願得受號者以億計。故乃關沬、若，","notes":[{"source":"集解","text":"《漢書音義》曰：「以沬、若水爲關。」"}]},{"id":"a427","section":"司馬相如列傳第五十七","anchor":"，梁孫原。創道德之塗，垂仁義之統。將博恩廣施，遠撫長駕，使疏逖不閉，","notes":[{"source":"索隱","text":"逖，遠。言其疏遠者不被閉絕也。"}]},{"id":"a428","section":"司馬相如列傳第五十七","anchor":"。創道德之塗，垂仁義之統。將博恩廣施，遠撫長駕，使疏逖不閉，阻深闇昧","notes":[{"source":"索隱","text":"曶爽闇昧。《三蒼》云：「曶爽，早朝也。曶音昧。」案：《字林》又音忽。"}]},{"id":"a429","section":"司馬相如列傳第五十七","anchor":"阻深闇昧得耀乎光明，以偃甲兵於此，而息誅伐於彼。遐邇一體，中外提福，","notes":[{"source":"集解","text":"徐廣曰：「提，一作『禔』，音支。」"},{"source":"索隱","text":"禔福。說文云：「禔，安也。」市支反。"}]},{"id":"a430","section":"司馬相如列傳第五十七","anchor":"且夫王事固未有不始於憂勤，而終於佚樂者也。然則受命之符，合在於此矣。","notes":[{"source":"索隱","text":"張揖云：「在於憂勤佚樂之中也。」"}]},{"id":"a431","section":"司馬相如列傳第五十七","anchor":"於此矣。方將增泰山之封，加梁父之事，鳴和鸞，揚樂頌，上咸五，下登三。","notes":[{"source":"集解","text":"徐廣曰：「咸，一作『函』。」駰案：韋昭曰「咸同於五帝，登三王之上」。"},{"source":"索隱","text":"上減五，下登三。李奇曰：「五帝之德，漢比爲減；三王之德，漢出其上：故云『減五登三』也。」虞憙志林云：「相如欲減五帝之一，以漢盈之。然以漢爲五帝之數，自然是登於三王之上也。」今本「減」或作「咸」，是韋昭之說也。"}]},{"id":"a432","section":"司馬相如列傳第五十七","anchor":"曰：「允哉漢德，此鄙人之所願聞也。百姓雖怠，請以身先之。」敞罔靡徙，","notes":[{"source":"索隱","text":"案：敞罔，失容也。靡徙，失正也。"}]},{"id":"a433","section":"司馬相如列傳第五十七","anchor":"其進仕宦，未嘗肯與公卿國家之事，稱病閒居，不慕官爵。常從上至長楊獵，","notes":[{"source":"正義","text":"《括地志》云：「秦長楊宮在雍州盩厔縣東南三里。上起以宮，內有長楊樹，以爲名。」"}]},{"id":"a434","section":"司馬相如列傳第五十七","anchor":"臣聞物有同類而殊能者，故力稱烏獲，","notes":[{"source":"索隱","text":"張揖曰：「秦武王力士，舉龍文鼎者也。」"}]},{"id":"a435","section":"司馬相如列傳第五十七","anchor":"臣聞物有同類而殊能者，故力稱烏獲，捷言慶忌，","notes":[{"source":"索隱","text":"張揖曰：「吳王僚之子」"}]},{"id":"a436","section":"司馬相如列傳第五十七","anchor":"臣聞物有同類而殊能者，故力稱烏獲，捷言慶忌，勇期賁、育。","notes":[{"source":"正義","text":"賁音奔。孟賁，古之勇士，水行不避蛟龍，陸行不避豺狼，發怒吐氣，聲音動天。夏育，亦古之猛士也。"}]},{"id":"a437","section":"司馬相如列傳第五十七","anchor":"、育。臣之愚，竊以爲人誠有之，獸亦宜然。今陛下好陵阻險，射猛獸，卒然","notes":[{"source":"索隱","text":"猝然。廣雅云：「猝，暴也，音倉兀反。」"}]},{"id":"a438","section":"司馬相如列傳第五十七","anchor":"有之，獸亦宜然。今陛下好陵阻險，射猛獸，卒然遇軼材之獸，駭不存之地，","notes":[{"source":"索隱","text":"謂所不慮而猛獸駭發也。"}]},{"id":"a439","section":"司馬相如列傳第五十七","anchor":"。今陛下好陵阻險，射猛獸，卒然遇軼材之獸，駭不存之地，犯屬車之清塵，","notes":[{"source":"集解","text":"蔡邕曰：「古者諸侯貳車九乘，秦滅九國，兼其車服，故大駕屬車八十一乘。」"}]},{"id":"a440","section":"司馬相如列傳第五十七","anchor":"犯屬車之清塵，輿不及還轅，人不暇施巧，雖有烏獲、逢蒙之伎，力不得用，","notes":[{"source":"集解","text":"吳越春秋曰：「羿傳射於逢蒙。」"},{"source":"索隱","text":"孟子云「逢蒙學射於羿，盡羿之道」也。"}]},{"id":"a441","section":"司馬相如列傳第五十七","anchor":"且夫清道而後行，中路而後馳，猶時有銜橛之變，","notes":[{"source":"集解","text":"徐廣曰：「橛音巨月反。鉤逆者謂之橛矣。」"},{"source":"索隱","text":"銜橜之變。張揖曰：「銜，馬勒銜也。橜，騑馬口長銜也。」周遷輿服志云：「鉤逆上者爲橜。橜在銜中，以鐵爲之，大如雞子。」鹽鐵論云：「無銜橜而禦捍馬。」橜音巨月反。"}]},{"id":"a442","section":"司馬相如列傳第五十七","anchor":"，禍固多藏於隱微而發於人之所忽者也。故鄙諺曰「家累千金，坐不垂堂」。","notes":[{"source":"索隱","text":"張揖云：「畏簷瓦墮中人。」樂產云：「垂，邊也。恐墮墜（之）也。」"}]},{"id":"a443","section":"司馬相如列傳第五十七","anchor":"上善之。還過宜春宮，","notes":[{"source":"正義","text":"《括地志》：「秦宜春宮在雍州萬年縣西南三十里。宜春苑在宮之東，杜之南。始皇本紀云葬二世杜南宜春苑中。」案：今宜春宮見二世陵，故作賦以哀也。"}]},{"id":"a444","section":"司馬相如列傳第五十七","anchor":"登陂阤","notes":[{"source":"索隱","text":"登陂陁。陂音普何反。陁音徒何反。"}]},{"id":"a445","section":"司馬相如列傳第五十七","anchor":"登陂阤之長阪兮，坌入","notes":[{"source":"集解","text":"《漢書音義》曰：「坌，並也。」"},{"source":"索隱","text":"上音步反。"}]},{"id":"a446","section":"司馬相如列傳第五十七","anchor":"登陂阤之長阪兮，坌入曾宮之嵯峨。臨曲江之隑州兮，","notes":[{"source":"集解","text":"《漢書音義》曰：「隑，長也。苑中有曲江之象，泉中有長洲也。」"},{"source":"索隱","text":"案：隑音祈。隑即碕，謂曲岸頭也。張揖曰：「隑，長也。苑中有曲江之象，中有長州，又有宮閣路，謂之曲江，在杜陵西北五里。」又三輔舊事云「樂游原在北」是也。"}]},{"id":"a447","section":"司馬相如列傳第五十七","anchor":"兮，坌入曾宮之嵯峨。臨曲江之隑州兮，望南山之參差。巖巖深山之谾谾兮，","notes":[{"source":"集解","text":"徐廣曰：「谾音力工反。」"},{"source":"索隱","text":"谾音苦江反。晉灼曰：「音籠，古『豅』字。」蕭該云：「谾，或作『豅』，長大皃也。」"}]},{"id":"a448","section":"司馬相如列傳第五十七","anchor":"嵯峨。臨曲江之隑州兮，望南山之參差。巖巖深山之谾谾兮，通谷𧯆兮谽𧯋。","notes":[{"source":"索隱","text":"呼含呼加二反。"}]},{"id":"a449","section":"司馬相如列傳第五十七","anchor":"臨曲江之隑州兮，望南山之參差。巖巖深山之谾谾兮，通谷𧯆兮谽𧯋。汩淢噏","notes":[{"source":"索隱","text":"上音于筆反。淢音域，疾皃也。噏音許及反。《漢書》作「靸」，靸，輕舉意也。"}]},{"id":"a450","section":"司馬相如列傳第五十七","anchor":"谾兮，通谷𧯆兮谽𧯋。汩淢噏習以永逝兮，注平皋之廣衍。觀眾樹之塕薆兮，","notes":[{"source":"索隱","text":"薆音薆，謂隱也。"}]},{"id":"a451","section":"司馬相如列傳第五十七","anchor":"，注平皋之廣衍。觀眾樹之塕薆兮，覽竹林之榛榛。東馳土山兮，北揭石瀨。","notes":[{"source":"索隱","text":"說文云：「瀨，水流沙上也。」"}]},{"id":"a452","section":"司馬相如列傳第五十七","anchor":"衍。觀眾樹之塕薆兮，覽竹林之榛榛。東馳土山兮，北揭石瀨。彌節容與兮，","notes":[{"source":"索隱","text":"容與，游戲貌也。"}]},{"id":"a453","section":"司馬相如列傳第五十七","anchor":"而不食。敻邈絕而不齊兮，彌久遠而愈佅。精罔閬而飛揚兮，拾九天而永逝。","notes":[{"source":"正義","text":"太玄經云：「九天謂一爲中天，二爲羨天，三爲從天，四爲更天，五爲晬天，六爲廓天，七爲減天，八爲沈天，九爲成天。」"}]},{"id":"a454","section":"司馬相如列傳第五十七","anchor":"相如拜爲孝文園令。","notes":[{"source":"索隱","text":"百官志云「陵園令，六百石，掌案行掃除」也。"}]},{"id":"a455","section":"司馬相如列傳第五十七","anchor":"有靡者。臣嘗爲大人賦，未就，請具而奏之。」相如以爲列僊之傳居山澤閒，","notes":[{"source":"索隱","text":"列仙之傳居山澤。案：傳者，謂相傳以列仙居山澤閒，音持全反。小顏及劉氏並作「儒」。儒，柔也，術士之稱，非。"}]},{"id":"a456","section":"司馬相如列傳第五十七","anchor":"嘗爲大人賦，未就，請具而奏之。」相如以爲列僊之傳居山澤閒，形容甚臞，","notes":[{"source":"集解","text":"徐廣曰：「臞，瘦也。」"},{"source":"索隱","text":"韋昭曰：「臞，瘠也。」舍人云：「臞，瘦也。」文子云：「堯癯瘦。」音巨俱反。"}]},{"id":"a457","section":"司馬相如列傳第五十七","anchor":"世有大人","notes":[{"source":"索隱","text":"張揖云：「喻天子。」向秀云：「聖人在位，謂之大人。」張華云：「相如作遠遊之體，以大人賦之也。」"}]},{"id":"a458","section":"司馬相如列傳第五十七","anchor":"世有大人兮，在于中州。宅彌萬里兮，曾不足以少留。悲世俗之迫隘兮，","notes":[{"source":"索隱","text":"如淳曰：「武帝云『誠得如黃帝，去妻子如脫屣』，是悲世俗迫隘也。」"}]},{"id":"a459","section":"司馬相如列傳第五十七","anchor":"而遠遊。垂絳幡之素蜺兮，載雲氣而上浮。建格澤之長竿兮，總光耀之采旄。","notes":[{"source":"集解","text":"《漢書音義》曰：「格澤之氣如炎火狀，黃白色，起地上至天，以此氣爲竿。旄，葆也，總，係也。係光耀之氣於長竿，以爲葆者。」"}]},{"id":"a460","section":"司馬相如列傳第五十七","anchor":"而上浮。建格澤之長竿兮，總光耀之采旄。垂旬始以爲幓兮，抴彗星而爲髾。","notes":[{"source":"集解","text":"《漢書音義》曰：「旬始氣如雄雞，縣於葆下以爲旒也。髾，燕尾也。抴彗星，綴著旒以爲燕尾。」"}]},{"id":"a461","section":"司馬相如列傳第五十七","anchor":"長竿兮，總光耀之采旄。垂旬始以爲幓兮，抴彗星而爲髾。掉指橋以偃蹇兮，","notes":[{"source":"集解","text":"《漢書音義》曰：「指橋，隨風指靡。」"},{"source":"索隱","text":"棹音徒弔反。指音居桀反。橋音矯。張揖曰：「指矯，隨風指靡。偃蹇，高皃。」應劭云：「旌旗屈撓之皃。」"}]},{"id":"a462","section":"司馬相如列傳第五十七","anchor":"爲幓兮，抴彗星而爲髾。掉指橋以偃蹇兮，又旖旎以招搖。攬欃槍以爲旌兮，","notes":[{"source":"正義","text":"《天官書》云：「天欃長四丈，末銳。天槍長數丈，兩頭銳，其形類彗也。」"}]},{"id":"a463","section":"司馬相如列傳第五十七","anchor":"而爲髾。掉指橋以偃蹇兮，又旖旎以招搖。攬欃槍以爲旌兮，靡屈虹而爲綢。","notes":[{"source":"集解","text":"《漢書音義》曰：「綢，韜也。以斷虹爲旌杠之韜。」"},{"source":"索隱","text":"綢音籌，或音韜。屈虹，斷虹也。"}]},{"id":"a464","section":"司馬相如列傳第五十七","anchor":"偃蹇兮，又旖旎以招搖。攬欃槍以爲旌兮，靡屈虹而爲綢。紅杳渺以眩湣兮，","notes":[{"source":"集解","text":"《漢書音義》曰：「旬始，屈虹，氣色。紅杳渺，眩湣，闇冥無光也。」"},{"source":"索隱","text":"紅杳眇以泫湣。蘇林曰：「泫音炫。湣音麪。」晉灼曰：「紅，赤色皃。杳眇，深遠；泫湣，混合也。」紅，或作「虹」也。"}]},{"id":"a465","section":"司馬相如列傳第五十七","anchor":"。駕應龍象輿之蠖略逶麗兮，驂赤螭青虯之𧍘蟉蜿蜒。低卬夭蟜据以驕驁兮，","notes":[{"source":"索隱","text":"張揖曰：「据，直項也。驕驁，縱恣也。」据音據。驕音居召反。驁音五到反。"}]},{"id":"a466","section":"司馬相如列傳第五十七","anchor":"略逶麗兮，驂赤螭青虯之𧍘蟉蜿蜒。低卬夭蟜据以驕驁兮，詘折隆窮蠼以連卷","notes":[{"source":"索隱","text":"躩以連卷。韋昭曰：「龍之形皃也。」躩音起碧反。連卷音輦卷也。"}]},{"id":"a467","section":"司馬相如列傳第五十七","anchor":"之𧍘蟉蜿蜒。低卬夭蟜据以驕驁兮，詘折隆窮蠼以連卷沛艾赳螑仡以佁儗兮，","notes":[{"source":"集解","text":"《漢書音義》曰：「赳螑，申頸低卬也。佁儗，不前也。」"},{"source":"索隱","text":"孟康曰：「赳螑，申頸低頭。」張揖曰：「赳螑，牙跳也。」赳音居幼反。螑音許救反。張揖曰：「仡，舉頭也。佁儗，不前也。」佁音勑吏反。儗音魚吏反也。"}]},{"id":"a468","section":"司馬相如列傳第五十七","anchor":"蟜据以驕驁兮，詘折隆窮蠼以連卷沛艾赳螑仡以佁儗兮，放散畔岸驤以孱顏。","notes":[{"source":"索隱","text":"服虔曰：「馬仰頭，其口開，正孱顏也。」韋昭曰：「顏音吾板反。」《詩》云「兩服上驤」，注云「驤，馬」是也。"}]},{"id":"a469","section":"司馬相如列傳第五十七","anchor":"以佁儗兮，放散畔岸驤以孱顏。跮踱輵轄容以委麗兮，綢繆偃蹇怵㚟以梁倚。","notes":[{"source":"集解","text":"徐廣曰：「跮踱，乍前乍卻也。跮音丑栗反。踱音勑略反。輵，烏葛反。轄音曷。綢，一作『雕』。㚟音他略反。」駰案：《漢書音義》曰「怵㚟，走也。梁倚，相著也」。"},{"source":"索隱","text":"跮踱輵磍。張揖曰：「跮踱，疾行皃。輵磍，前卻也。」跮音褚栗反。踱音褚略反。輵音烏葛反。磍音曷。蜩蟉偃蹇。蜩音徒弔反。蟉音勑弔反。張揖曰：「偃蹇，卻距也。」廣雅曰：「偃蹇，夭矯之皃。」張揖曰：「怵㚟，奔走。梁倚，相著。」韋昭曰：「㚟音笞略反。相如傳云『倏㚟遠去』，㚟，視也。」"}]},{"id":"a470","section":"司馬相如列傳第五十七","anchor":"以孱顏。跮踱輵轄容以委麗兮，綢繆偃蹇怵㚟以梁倚。糾蓼叫奡蹋以艐路兮，","notes":[{"source":"集解","text":"徐廣曰：「艐音介，至也。」"},{"source":"索隱","text":"蓼音了。奡音五到反。小顏云：「叫奡，高舉皃。」踏音徒答反。艐音屆。三倉云：「踏，著地。」孫炎云：「艐，古『界』字也。」"}]},{"id":"a471","section":"司馬相如列傳第五十七","anchor":"以委麗兮，綢繆偃蹇怵㚟以梁倚。糾蓼叫奡蹋以艐路兮，蔑蒙踊躍騰而狂趡。","notes":[{"source":"集解","text":"《漢書音義》曰：「蔑蒙，飛揚也。趡，走。」"},{"source":"索隱","text":"篾蒙。張揖曰：「篾蒙，飛揚也。趡，走皃。」"}]},{"id":"a472","section":"司馬相如列傳第五十七","anchor":"邪絕少陽而登太陰兮，與真人乎相求。","notes":[{"source":"集解","text":"《漢書音義》曰：「少陽，東極；太陰，北極。邪度，東極而升北極者也。"}]},{"id":"a473","section":"司馬相如列傳第五十七","anchor":"邪絕少陽而登太陰兮，與真人乎相求。互折窈窕以右轉兮，橫厲飛泉以正東。","notes":[{"source":"正義","text":"厲，渡也。張云：「飛泉，谷也，在崑崙山西南。」"}]},{"id":"a474","section":"司馬相如列傳第五十七","anchor":"互折窈窕以右轉兮，橫厲飛泉以正東。悉徵靈圉而選之兮，部乘眾神於瑤光。","notes":[{"source":"集解","text":"《漢書音義》曰：「搖光，北斗杓頭第一星。」"}]},{"id":"a475","section":"司馬相如列傳第五十七","anchor":"兮，橫厲飛泉以正東。悉徵靈圉而選之兮，部乘眾神於瑤光。使五帝先導兮，","notes":[{"source":"正義","text":"遵，導。應云「五帝，五畤，帝太晧之屬也」。"}]},{"id":"a476","section":"司馬相如列傳第五十七","anchor":"東。悉徵靈圉而選之兮，部乘眾神於瑤光。使五帝先導兮，反太一而從陵陽。","notes":[{"source":"集解","text":"《漢書音義》曰：「仙人陵陽子明也。」"},{"source":"正義","text":"《天官書》云：「中官天極星，其一明者，太一常居也。」《列仙傳》云：「子明於沛銍縣旋溪釣得白龍，放之，後白龍來迎子明去，止陵陽山上百餘年，遂得仙也。」"}]},{"id":"a477","section":"司馬相如列傳第五十七","anchor":"兮，部乘眾神於瑤光。使五帝先導兮，反太一而從陵陽。左玄冥而右含靁兮，","notes":[{"source":"集解","text":"《漢書音義》曰：「含靁，黔嬴也，天上造化神名也。或曰水神。」"}]},{"id":"a478","section":"司馬相如列傳第五十七","anchor":"光。使五帝先導兮，反太一而從陵陽。左玄冥而右含靁兮，前陸離而後潏湟。","notes":[{"source":"集解","text":"《漢書音義》曰：「皆神名。」"}]},{"id":"a479","section":"司馬相如列傳第五十七","anchor":"帝先導兮，反太一而從陵陽。左玄冥而右含靁兮，前陸離而後潏湟。廝征伯僑","notes":[{"source":"集解","text":"徐廣曰：「燕人也，形解而仙也。」"},{"source":"索隱","text":"應劭曰：「廝，役也。」張揖曰：「王子喬也。」《漢書郊祀志》作「正伯僑」，此當別人，恐非王子喬也。"}]},{"id":"a480","section":"司馬相如列傳第五十七","anchor":"太一而從陵陽。左玄冥而右含靁兮，前陸離而後潏湟。廝征伯僑而役羨門兮，","notes":[{"source":"正義","text":"張云：「羨門，碣石山上仙人羨門高也。」"}]},{"id":"a481","section":"司馬相如列傳第五十七","anchor":"左玄冥而右含靁兮，前陸離而後潏湟。廝征伯僑而役羨門兮，屬岐伯使尚方。","notes":[{"source":"集解","text":"徐廣曰：「岐伯，黃帝臣。」駰案：《漢書音義》曰「尚，主也。岐伯，黃帝太醫，屬使主方藥」。"}]},{"id":"a482","section":"司馬相如列傳第五十七","anchor":"，前陸離而後潏湟。廝征伯僑而役羨門兮，屬岐伯使尚方。祝融驚而蹕御兮，","notes":[{"source":"正義","text":"張云：「祝融，南方炎帝之佐也。獸身人面，乘兩龍，應火正也。火正祝融警蹕清氛氣也。」"}]},{"id":"a483","section":"司馬相如列傳第五十七","anchor":"尚方。祝融驚而蹕御兮，清雰氣而後行。屯余車其萬乘兮，綷雲蓋而樹華旗。","notes":[{"source":"索隱","text":"綷音祖內反。如淳曰：「綷，合也。合五綵雲爲蓋也。」"}]},{"id":"a484","section":"司馬相如列傳第五十七","anchor":"御兮，清雰氣而後行。屯余車其萬乘兮，綷雲蓋而樹華旗。使句芒其將行兮，","notes":[{"source":"正義","text":"張云：「句芒，東方青帝之佐也。鳥身人面，乘兩龍。」顏云：「將行，領從者也。」"}]},{"id":"a485","section":"司馬相如列傳第五十七","anchor":"歷唐堯於崇山兮，過虞舜於九疑。","notes":[{"source":"正義","text":"張云：「崇山，狄山也。海外經云『狄山，帝堯葬其陽』。九疑山，零陵營道縣，舜所葬處。」"}]},{"id":"a486","section":"司馬相如列傳第五十七","anchor":"歷唐堯於崇山兮，過虞舜於九疑。紛湛湛","notes":[{"source":"索隱","text":"音徒感反。"}]},{"id":"a487","section":"司馬相如列傳第五十七","anchor":"歷唐堯於崇山兮，過虞舜於九疑。紛湛湛其差錯兮，雜遝膠葛","notes":[{"source":"索隱","text":"膠輵。廣雅云：「膠輵，驅馳也。」"}]},{"id":"a488","section":"司馬相如列傳第五十七","anchor":"唐堯於崇山兮，過虞舜於九疑。紛湛湛其差錯兮，雜遝膠葛以方馳。騷擾衝蓯","notes":[{"source":"索隱","text":"上昌勇反，下息宂反。"}]},{"id":"a489","section":"司馬相如列傳第五十七","anchor":"其相紛挐兮，滂濞泱軋灑以林離。鑽羅列聚叢以蘢茸兮，衍曼流爛壇以陸離。","notes":[{"source":"集解","text":"徐廣曰：「壇音坦。」"}]},{"id":"a490","section":"司馬相如列傳第五十七","anchor":"蘢茸兮，衍曼流爛壇以陸離。徑入靁室之砰磷鬱律兮，洞出鬼谷之崫礨嵬䃶。","notes":[{"source":"集解","text":"《漢書音義》曰：「鬼谷在北辰下，眾鬼之所聚也。楚辭曰『贅鬼谷于北辰』也。」"},{"source":"正義","text":"䃶，口骨反。礨音力罪反。嵬音烏迴反。䃶音回。張云：「崫礨嵬䃶，不平也。」"}]},{"id":"a491","section":"司馬相如列傳第五十七","anchor":"磷鬱律兮，洞出鬼谷之崫礨嵬䃶。徧覽八紘而觀四荒兮，朅渡九江而越五河。","notes":[{"source":"正義","text":"顏云：「五色之河也。仙經云紫、碧、絳、青、黃之河也。」"}]},{"id":"a492","section":"司馬相如列傳第五十七","anchor":"崫礨嵬䃶。徧覽八紘而觀四荒兮，朅渡九江而越五河。經營炎火而浮弱水兮，","notes":[{"source":"正義","text":"姚丞云：「大荒西經云崑崙之丘，其外有炎火之山，投物輒然。」《括地志》云：「弱水有二原，俱出女國北阿傉達山，南流會于國北，又南歷國北，東去一里，深丈餘，闊六十步，非乘舟不可濟，流入海。阿傉達山一名崑崙山，其山爲天柱，在雍州西南一萬五千三百七十里。」又云：「弱水在甘州張掖縣南山下也。」"}]},{"id":"a493","section":"司馬相如列傳第五十七","anchor":"而觀四荒兮，朅渡九江而越五河。經營炎火而浮弱水兮，杭絕浮渚而涉流沙。","notes":[{"source":"集解","text":"《漢書音義》曰：「杭，船也。絕，渡也。浮渚，流沙中渚也。」"}]},{"id":"a494","section":"司馬相如列傳第五十七","anchor":"而越五河。經營炎火而浮弱水兮，杭絕浮渚而涉流沙。奄息總極氾濫水嬉兮，","notes":[{"source":"集解","text":"《漢書音義》曰：「總極，蔥領山也，在西域中也。」"}]},{"id":"a495","section":"司馬相如列傳第五十七","anchor":"浮弱水兮，杭絕浮渚而涉流沙。奄息總極氾濫水嬉兮，使靈媧鼓瑟而舞馮夷。","notes":[{"source":"集解","text":"徐廣曰：「媧，一作『貽』。」駰案：《漢書音義》曰「靈媧，女媧也。馮夷，河伯字也。《淮南子》曰『馮夷得道，以潛大川』」。"},{"source":"正義","text":"姓馮名夷，以庚日溺死。河常以庚日好溺死人。"}]},{"id":"a496","section":"司馬相如列傳第五十七","anchor":"沙。奄息總極氾濫水嬉兮，使靈媧鼓瑟而舞馮夷。時若薆薆將混濁兮，召屏翳","notes":[{"source":"正義","text":"應云：「屏翳，天神使也。」韋云：「雷師也。」"}]},{"id":"a497","section":"司馬相如列傳第五十七","anchor":"息總極氾濫水嬉兮，使靈媧鼓瑟而舞馮夷。時若薆薆將混濁兮，召屏翳誅風伯","notes":[{"source":"正義","text":"張云：「風伯字飛廉。」"}]},{"id":"a498","section":"司馬相如列傳第五十七","anchor":"水嬉兮，使靈媧鼓瑟而舞馮夷。時若薆薆將混濁兮，召屏翳誅風伯而刑雨師。","notes":[{"source":"正義","text":"沙州有雨師祠。"}]},{"id":"a499","section":"司馬相如列傳第五十七","anchor":"使靈媧鼓瑟而舞馮夷。時若薆薆將混濁兮，召屏翳誅風伯而刑雨師。西望崑崙","notes":[{"source":"正義","text":"張云：「海內經云崑崙去中國五萬里，天帝之下都也。其山廣袤百里，高八萬仞，增城九重，面九井，以玉爲檻，旁有五門，開明獸守之。」《括地志》云：「崑崙在肅州酒泉縣南八十里。十六國春秋後魏昭成帝建國十年，涼張駿酒泉太守馬岌上言：『酒泉南山即崑崙之體，周穆王見西王母，樂而忘歸，即謂此山。有石室，王母堂，珠璣鏤飾，煥若神宮。』又刪丹西河名云弱水，《禹貢》崑崙在臨羌之西，即此明矣。」《括地志》云：「又阿傉達山亦名建末達山，亦名崑崙山。恆河出其南吐師子口，經天竺入達山。嬀水今名爲滸海，出於崑崙西北隅吐馬口，經安息、大夏國入西海。黃河出東北隅吐牛口，東北流經濫澤，潛出大積石山，至華山北，東入海。其三河去山入海各三萬里。此謂大崑崙，肅州謂小崑崙也。禹本紀云『河出崑崙二千五百餘里，日月所相隱避爲光明也』。」"}]},{"id":"a500","section":"司馬相如列傳第五十七","anchor":"將混濁兮，召屏翳誅風伯而刑雨師。西望崑崙之軋沕洸忽兮，直徑馳乎三危。","notes":[{"source":"集解","text":"三危，山名也。"},{"source":"正義","text":"《括地志》云：「三危山在沙州東南三十里。」"}]},{"id":"a501","section":"司馬相如列傳第五十七","anchor":"風伯而刑雨師。西望崑崙之軋沕洸忽兮，直徑馳乎三危。排閶闔而入帝宮兮，","notes":[{"source":"正義","text":"韋昭云：「閶闔，天門也。《淮南子》曰『西方曰西極之山，閶闔之門』。」"}]},{"id":"a502","section":"司馬相如列傳第五十七","anchor":"望崑崙之軋沕洸忽兮，直徑馳乎三危。排閶闔而入帝宮兮，載玉女而與之歸。","notes":[{"source":"正義","text":"張云：「玉女，青要、乘弋等也。」"}]},{"id":"a503","section":"司馬相如列傳第五十七","anchor":"兮，直徑馳乎三危。排閶闔而入帝宮兮，載玉女而與之歸。舒閬風而搖集兮，","notes":[{"source":"正義","text":"張云：「閬風在崑崙閶闔之中。楚辭云『登閬風而緤馬』也。」"}]},{"id":"a504","section":"司馬相如列傳第五十七","anchor":"危。排閶闔而入帝宮兮，載玉女而與之歸。舒閬風而搖集兮，亢烏騰而一止。","notes":[{"source":"集解","text":"《漢書音義》曰：「亢然高飛，如烏之騰也。」"}]},{"id":"a505","section":"司馬相如列傳第五十七","anchor":"，載玉女而與之歸。舒閬風而搖集兮，亢烏騰而一止。低回陰山翔以紆曲兮，","notes":[{"source":"正義","text":"張云：「陰山在大崑崙西二千七百里。」"}]},{"id":"a506","section":"司馬相如列傳第五十七","anchor":"搖集兮，亢烏騰而一止。低回陰山翔以紆曲兮，吾乃今目睹西王母皬然白首。","notes":[{"source":"集解","text":"徐廣曰：「皬音下沃反。」"},{"source":"索隱","text":"皬音鶴也。"},{"source":"正義","text":"張云：「西王母，其狀如人，豹尾，虎齒，蓬鬢，皬然白首。石城金穴，居其中。」"}]},{"id":"a507","section":"司馬相如列傳第五十七","anchor":"而一止。低回陰山翔以紆曲兮，吾乃今目睹西王母皬然白首。載勝而穴處兮，","notes":[{"source":"集解","text":"郭璞曰：「勝，玉勝也。」"},{"source":"正義","text":"顏云：「勝（代），婦人首飾也，漢代謂之華勝也。」"}]},{"id":"a508","section":"司馬相如列傳第五十七","anchor":"紆曲兮，吾乃今目睹西王母皬然白首。載勝而穴處兮，亦幸有三足烏爲之使。","notes":[{"source":"正義","text":"張云：「三足烏，青烏也。主爲西王母取食，在昆墟之北。」"}]},{"id":"a509","section":"司馬相如列傳第五十七","anchor":"回車朅來兮，絕道不周，","notes":[{"source":"集解","text":"《漢書音義》曰：「不周山在崑崙東南。」"}]},{"id":"a510","section":"司馬相如列傳第五十七","anchor":"，絕道不周，會食幽都。呼吸沆瀣〔兮〕餐朝霞（兮），噍咀芝英兮嘰瓊華。","notes":[{"source":"集解","text":"徐廣曰：「嘰音祈，小食也。」駰案：韋昭曰「瓊華，玉英」。"}]},{"id":"a511","section":"司馬相如列傳第五十七","anchor":"不周，會食幽都。呼吸沆瀣〔兮〕餐朝霞（兮），噍咀芝英兮嘰瓊華。嬐侵潯","notes":[{"source":"集解","text":"徐廣曰：「嬐音孅。」"},{"source":"索隱","text":"《漢書》「嬐」作「僸」。僸，仰也，音襟。嬐音魚錦反。"}]},{"id":"a512","section":"司馬相如列傳第五十七","anchor":"），噍咀芝英兮嘰瓊華。嬐侵潯而高縱兮，紛鴻涌而上厲。貫列缺之倒景兮，","notes":[{"source":"集解","text":"《漢書音義》曰：「列缺，天閃也。倒景，日在下。」"}]},{"id":"a513","section":"司馬相如列傳第五十七","anchor":"嘰瓊華。嬐侵潯而高縱兮，紛鴻涌而上厲。貫列缺之倒景兮，涉豐隆之滂沛。","notes":[{"source":"正義","text":"張云：「豐崇，雲師也，《淮南子》云『季春三月，豐崇乃出以將雨』。」案：豐崇將雲雨，故云「滂沛」。"}]},{"id":"a514","section":"司馬相如列傳第五十七","anchor":"高縱兮，紛鴻涌而上厲。貫列缺之倒景兮，涉豐隆之滂沛。馳游道而脩降兮，","notes":[{"source":"正義","text":"游，游車也。道，道車也。脩，長也。降，下也。"}]},{"id":"a515","section":"司馬相如列傳第五十七","anchor":"而遠逝。迫區中之隘陜兮，舒節出乎北垠。遺屯騎於玄闕兮，軼先驅於寒門。","notes":[{"source":"集解","text":"《漢書音義》曰：「玄闕，北極之山。寒門，天北門。」"}]},{"id":"a516","section":"司馬相如列傳第五十七","anchor":"而無天。視眩眠而無見兮，聽惝恍而無聞。乘虛無而上假兮，超無友而獨存。","notes":[{"source":"集解","text":"徐廣曰：「假音古下反，至也。」"}]},{"id":"a517","section":"司馬相如列傳第五十七","anchor":"。天子曰：「司馬相如病甚，可往從悉取其書；若不然，後失之矣。」使所忠","notes":[{"source":"索隱","text":"張揖曰：「使者姓名，見食貨志。」"},{"source":"正義","text":"姓所，名忠也。風俗通姓氏云：「《漢書》有諫大夫所忠氏。」"}]},{"id":"a518","section":"司馬相如列傳第五十七","anchor":"伊上古之初肇，自昊穹兮生民，歷撰","notes":[{"source":"集解","text":"徐廣曰：「撰，一作『選』。」"},{"source":"索隱","text":"歷選。文穎曰：「選，數之也。」"}]},{"id":"a519","section":"司馬相如列傳第五十七","anchor":"伊上古之初肇，自昊穹兮生民，歷撰列辟，以迄于秦。率邇者踵武，","notes":[{"source":"集解","text":"徐廣曰：「率，循也。邇，近也。武，迹也。循省近世之遺迹。」"},{"source":"索隱","text":"案：率，循也。邇，近也。言循覽近代之事，則繼跡可知也。"}]},{"id":"a520","section":"司馬相如列傳第五十七","anchor":"古之初肇，自昊穹兮生民，歷撰列辟，以迄于秦。率邇者踵武，逖聽者風聲。","notes":[{"source":"集解","text":"徐廣曰：「逖，遠也。聽察遠古之風聲。」"},{"source":"索隱","text":"風聲，風雅之聲。以言聽遠古之事，則著在風雅之聲也。"}]},{"id":"a521","section":"司馬相如列傳第五十七","anchor":"自昊穹兮生民，歷撰列辟，以迄于秦。率邇者踵武，逖聽者風聲。紛綸葳蕤，","notes":[{"source":"索隱","text":"紛綸威蕤。胡廣曰：「紛，亂也。綸，沒也。威蕤，委頓也。」張揖云：「亂皃。」"}]},{"id":"a522","section":"司馬相如列傳第五十七","anchor":"葳蕤，堙滅而不稱者，不可勝數也。續昭夏，崇號謚，略可道者七十有二君。","notes":[{"source":"集解","text":"《漢書音義》曰：「昭，明也。夏，大也。德明大，相繼封禪於泰山者七十有二人。」"},{"source":"索隱","text":"七十有二君，韓詩外傳及《封禪書》皆然。"}]},{"id":"a523","section":"司馬相如列傳第五十七","anchor":"也。續昭夏，崇號謚，略可道者七十有二君。罔若淑而不昌，疇逆失而能存？","notes":[{"source":"集解","text":"徐廣曰：「若，順也。」駰案：韋昭曰「疇，誰也。言順善必昌，逆失必亡」。"}]},{"id":"a524","section":"司馬相如列傳第五十七","anchor":"軒轅之前，遐哉邈乎，其詳不可得聞也。五三六經","notes":[{"source":"索隱","text":"胡廣云：「五，五帝也。三，三王也。六，六經也。」案：六經，詩、書、禮、樂、易、春秋也。"}]},{"id":"a525","section":"司馬相如列傳第五十七","anchor":"堯，臣莫賢於后稷。后稷創業於唐，公劉發迹於西戎，文王改制，爰周郅隆，","notes":[{"source":"集解","text":"徐廣曰：「『郅』蓋字誤。皇甫謐曰『王季徙郢』，故《周書》曰『維王季宅郢』。孟子稱『文王（生）〔卒〕於畢郢』。或者『郅』字宜爲『郢』乎？或爲『胵』，北地有郁郅縣。胵，大也，音質。」駰案：《漢書音義》曰「郅，至也」。"},{"source":"索隱","text":"爰，於，及也。郅，大也。隆，盛也。應劭曰「郅，至也」。樊光云「郅，可見之大也」。徐及皇甫之說皆非也。以言文王改制，及周而大盛也。"}]},{"id":"a526","section":"司馬相如列傳第五十七","anchor":"於后稷。后稷創業於唐，公劉發迹於西戎，文王改制，爰周郅隆，大行越成，","notes":[{"source":"集解","text":"《漢書音義》曰：「行，道也。文王始開王業，改正朔，易服色，太平之道於是成矣。」"},{"source":"索隱","text":"案：行，道也。越，於也。以言道德大行，於是而成之也。"}]},{"id":"a527","section":"司馬相如列傳第五十七","anchor":"劉發迹於西戎，文王改制，爰周郅隆，大行越成，而後陵夷衰微，千載無聲，","notes":[{"source":"集解","text":"徐廣曰：「周之王四海，千載之後聲教乃絕。」駰案：韋昭曰「無惡聲」。"}]},{"id":"a528","section":"司馬相如列傳第五十七","anchor":"也；憲度著明，易則也；垂統理順，易繼也。是以業隆於繈褓而崇冠于二后。","notes":[{"source":"集解","text":"《漢書音義》曰：「繈褓謂成王也。二后謂文、武也。周公負成王致太平，功德冠於文武者，道成法易故也。」"}]},{"id":"a529","section":"司馬相如列傳第五十七","anchor":"；垂統理順，易繼也。是以業隆於繈褓而崇冠于二后。揆厥所元，終都攸卒，","notes":[{"source":"集解","text":"《漢書音義》曰：「都，於；卒，終也。」"}]},{"id":"a530","section":"司馬相如列傳第五十七","anchor":"考于今者也。然猶躡梁父，登泰山，建顯號，施尊名。大漢之德，逢涌原泉，","notes":[{"source":"集解","text":"韋昭曰：「漢德逢涌如泉原也。」"},{"source":"索隱","text":"逢源泉。張揖曰：「逢，遇也。喻其德盛若遇泉源之流也。」又作「峰」，讀曰烽。胡廣曰：「自此已下，論漢家之德也。」"}]},{"id":"a531","section":"司馬相如列傳第五十七","anchor":"，建顯號，施尊名。大漢之德，逢涌原泉，沕潏漫衍，旁魄四塞，雲尃霧散，","notes":[{"source":"集解","text":"徐廣曰：「尃音布。」"}]},{"id":"a532","section":"司馬相如列傳第五十七","anchor":"漢之德，逢涌原泉，沕潏漫衍，旁魄四塞，雲尃霧散，上暢九垓，下泝八埏。","notes":[{"source":"集解","text":"徐廣曰：「音衍。」駰案：《漢書音義》曰「暢，達；垓，重也。泝，流也。埏音延，地之際也。言其德上達於九重之天，下流於地之八際也」。"}]},{"id":"a533","section":"司馬相如列傳第五十七","anchor":"下泝八埏。懷生之類霑濡浸潤，協氣橫流，武節飄逝，邇陜游原，迥闊泳沫，","notes":[{"source":"集解","text":"《漢書音義》曰：「邇，近；原，本也。迥，遠；闊，廣也。泳，浮也。恩德比之於水，近者游其原，遠者浮其沫。」"}]},{"id":"a534","section":"司馬相如列傳第五十七","anchor":"濡浸潤，協氣橫流，武節飄逝，邇陜游原，迥闊泳沫，首惡湮沒，闇昧昭晢，","notes":[{"source":"集解","text":"《漢書音義》曰：「始爲惡者皆湮滅。闇昧，喻夷狄皆化。」"}]},{"id":"a535","section":"司馬相如列傳第五十七","anchor":"節飄逝，邇陜游原，迥闊泳沫，首惡湮沒，闇昧昭晢，昆蟲凱澤，回首面內。","notes":[{"source":"集解","text":"韋昭曰：「面，向也。」"}]},{"id":"a536","section":"司馬相如列傳第五十七","anchor":"湮沒，闇昧昭晢，昆蟲凱澤，回首面內。然後囿騶虞之珍羣，徼麋鹿之怪獸，","notes":[{"source":"集解","text":"《漢書音義》曰：「徼，遮也。麋鹿得其奇怪者，謂獲白麟也。」"}]},{"id":"a537","section":"司馬相如列傳第五十七","anchor":"昆蟲凱澤，回首面內。然後囿騶虞之珍羣，徼麋鹿之怪獸，䆃一莖六穗於庖，","notes":[{"source":"集解","text":"徐廣曰：「䆃，瑞禾也。」駰案：《漢書音義》曰「謂嘉禾之米，於庖廚以供祭祀」。"},{"source":"索隱","text":"䆃一莖六蕙。鄭玄云：「䆃，擇也。」說文云：「嘉禾一名䆃。」《字林》云：「禾一莖六蕙謂之䆃也。」"}]},{"id":"a538","section":"司馬相如列傳第五十七","anchor":"內。然後囿騶虞之珍羣，徼麋鹿之怪獸，䆃一莖六穗於庖，犧雙觡共抵之獸，","notes":[{"source":"集解","text":"徐廣曰：「抵音底。」駰案：《漢書音義》曰「犧，牲也。觡，角也。底，本也。武帝獲白麟，兩角共一本，因以爲牲也」。"}]},{"id":"a539","section":"司馬相如列傳第五十七","anchor":"羣，徼麋鹿之怪獸，䆃一莖六穗於庖，犧雙觡共抵之獸，獲周餘珍收龜于岐，","notes":[{"source":"集解","text":"徐廣曰：「一作『放龜』。」駰案：《漢書音義》曰「餘珍，得周鼎也。岐，水名也」。"},{"source":"索隱","text":"餘珍，案謂得周鼎也。"}]},{"id":"a540","section":"司馬相如列傳第五十七","anchor":"，䆃一莖六穗於庖，犧雙觡共抵之獸，獲周餘珍收龜于岐，招翠黃乘龍於沼。","notes":[{"source":"集解","text":"《漢書音義》曰：「翠黃，乘黃也。龍翼馬身，黃帝乘之而登仙。言見乘黃而招呼之。禮樂志曰『訾黃其何不來下』。余吾渥洼水中出神馬，故曰乘龍於沼。」"},{"source":"索隱","text":"服虔云「龍翠色」。又云「即乘黃也。乘四龍也」。《周書》云「乘黃似狐，背上有兩角」也。"}]},{"id":"a541","section":"司馬相如列傳第五十七","anchor":"觡共抵之獸，獲周餘珍收龜于岐，招翠黃乘龍於沼。鬼神接靈圉，賓於閒館。","notes":[{"source":"集解","text":"徐廣曰：「言至德與神明通接，故靈圉爲賓旅于閒館矣。」郭璞曰：「靈圉，仙人名也。」"}]},{"id":"a542","section":"司馬相如列傳第五十七","anchor":"窮變。欽哉，符瑞臻茲，猶以爲薄，不敢道封禪。蓋周躍魚隕杭，休之以燎，","notes":[{"source":"索隱","text":"杭，舟也。胡廣云：「武王渡河，白魚入于王舟，俯取以燎。隕，墜之於舟中也。」"}]},{"id":"a543","section":"司馬相如列傳第五十七","anchor":"道封禪。蓋周躍魚隕杭，休之以燎，微夫斯之爲符也，以登介丘，不亦恧乎！","notes":[{"source":"集解","text":"《漢書音義》曰：「介，大；丘，山也。言周以白魚爲瑞，登太山封禪，不亦慙乎！」"}]},{"id":"a544","section":"司馬相如列傳第五十七","anchor":"，休之以燎，微夫斯之爲符也，以登介丘，不亦恧乎！進讓之道，其何爽與？","notes":[{"source":"集解","text":"徐廣曰：「爽，差異也。」駰案：《漢書音義》曰「進，周也。讓，漢也。言周未可封禪而封禪爲進，漢可封禪而不封禪爲讓也」。"},{"source":"索隱","text":"何其爽與。爽猶差也。言周未可封而封，漢可封而不封，爲進讓之道皆差之也。"}]}]'),s=[],r={id:"117",volume:117,sanjiazhuSourceUrl:t,originalSourceUrl:e,annotations:o,criticalNotes:s};export{o as annotations,s as criticalNotes,r as default,c as id,e as originalSourceUrl,t as sanjiazhuSourceUrl,n as volume};
